        ["I'm also after some Cows, in fact I'll buy up to [number] more while I'm here."] = "También busco algunas vacas; de hecho, compraré hasta [número] más mientras esté aquí.",
        ["Would you like to sell [name] for [number] beans?"] = "¿Le gustaría vender [name] por frijoles [número]?",
        ["Sell [name] for [number] beans?"] = "¿Vender [name] por frijoles [número]?",
        ["Yes."] = "Sí.",
        ["Your currency pouch is full of beans! You need to spend some beans before you can earn any more."] = "¡Tu bolsa de monedas está llena de frijoles! Necesitas gastar algunos frijoles antes de poder ganar más.",
        ["You can't hold anymore beans, I can't purchase this animal off you."] = "No puedes aguantar más frijoles, no puedo comprarte este animal.",
        ["This transaction would take you over the cap of one million beans. In doing so, you would lose out on [number] beans."] = "Esta transacción le llevaría por encima del límite de un millón de frijoles. Al hacerlo, perdería beans [número].",
        ["Complete transaction anyway?"] = "¿Completar la transacción de todos modos?",
        ["[number] beans added to your currency pouch."] = "Frijoles [número] agregados a su bolsa de divisas.",
        ["Let me check what animals I have which match your request."] = "Déjame comprobar qué animales tengo que coincidan con tu solicitud.",
        ["I've bought all the animals I need for now, catch you later!"] = "He comprado todos los animales que necesito por ahora, ¡nos vemos más tarde!",
        ["Are you sure you want me to take all the Cows you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todas las vacas que tienes? No aceptaré ninguno de tus favoritos.",
        ["Sell all of your cows?"] = "¿Vender todas tus vacas?",
        ["Yes"] = "si",
        ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
        ["You've sold [number] animals for [number] total beans."] = "Has vendido animales [número] por un total de frijoles [número].",
    },
    ["Milkshake"] = {
        ["I have a special request for [breed]. Especially if it has the [Trait] trait!"] = "Tengo un pedido especial para [breed]. ¡Especialmente si tiene el rasgo [Trait]!",
        ["I'm also after some Cows, in fact I'll buy up to [number] more while I'm here."] = "También busco algunas vacas; de hecho, compraré hasta [número] más mientras esté aquí.",
        ["Would you like to sell [name] for [number] beans?"] = "¿Le gustaría vender [name] por frijoles [número]?",
        ["Sell [name] for [number] beans?"] = "¿Vender [name] por frijoles [número]?",
        ["Yes."] = "Sí.",
        ["Your currency pouch is full of beans! You need to spend some beans before you can earn any more."] = "¡Tu bolsa de monedas está llena de frijoles! Necesitas gastar algunos frijoles antes de poder ganar más.",
        ["You can't hold anymore beans, I can't purchase this animal off you."] = "No puedes aguantar más frijoles, no puedo comprarte este animal.",
        ["This transaction would take you over the cap of one million beans. In doing so, you would lose out on [number] beans."] = "Esta transacción le llevaría por encima del límite de un millón de frijoles. Al hacerlo, perdería beans [número].",
        ["Complete transaction anyway?"] = "¿Completar la transacción de todos modos?",
        ["[number] beans added to your currency pouch."] = "Frijoles [número] agregados a su bolsa de divisas.",
        ["Let me check what animals I have which match your request."] = "Déjame comprobar qué animales tengo que coincidan con tu solicitud.",
        ["I've bought all the animals I need for now, catch you later!"] = "He comprado todos los animales que necesito por ahora, ¡nos vemos más tarde!",
        ["Are you sure you want me to take all the Cows you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todas las vacas que tienes? No aceptaré ninguno de tus favoritos.",
        ["Sell all of your cows?"] = "¿Vender todas tus vacas?",
        ["Yes"] = "si",
        ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
        ["You've sold [number] animals for [number] total beans."] = "Has vendido animales [número] por un total de frijoles [número].",
    },
    ["Milky Joel"] = {
        ["The coconut barely even reacts to your overly excited call."] = "El coco apenas reacciona a tu llamada demasiado emocionada.",
        ["Why so cold? We're here to rescue you!"] = "¿Por qué hace tanto frío? ¡Estamos aquí para rescatarte!",
        ["The coconut gives a near imperceptible shrug, as if it couldn't care less."] = "El coco se encoge de hombros casi imperceptiblemente, como si no le importara nada.",
        ["Fine, be that way! Maybe I'll just leave you here."] = "¡Bien, sé así! Quizás te deje aquí.",
        ["The coconut shakes a little in fear and pines in your general direction."] = "El coco tiembla un poco de miedo y suspira en tu dirección general.",
        ["Oh, who am I kidding? I can't stay mad at you. Come here!"] = "Oh, ¿a quién engaño? No puedo seguir enojado contigo. ¡Ven aquí!",
        ["As you embrace, Milky Joel whispers in your ear - just a few words that send a chill down your spine, though you're unsure why: 'The Harbinger"] = "Mientras te abrazas, Milky Joel te susurra al oído, solo unas pocas palabras que te provocan un escalofrío, aunque no estás seguro de por qué: 'The Harbinger'.",
    },
    ["Milla"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
        ["Strange how?"] = "¿Qué extraño cómo?",
        ["Like a human!"] = "¡Como un humano!",
        ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["Get lost!"] = "¡Piérdete!",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["Leave me alone."] = "Déjame en paz.",
        ["*Dialogue 7*"] = "*Diálogo 7*",
        ["Have you no manners?"] = "¿No tienes modales?",
        ["*Dialogue 8*"] = "*Diálogo 8*",
        ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
        ["*Dialogue 9*"] = "*Diálogo 9*",
        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
        ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
        ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
        ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
        ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
        ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
        ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
        ["Good day to you, my friend."] = "Buenos días, amigo mío.",
        ["You smell familiar..."] = "Hueles familiar...",
        ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    },
    ["Milli Rehnison"] = {
        ["Have you found Elena yet?"] = "¿Ya encontraste Elena?",
        ["Yes, she's safe at home."] = "Sí, está a salvo en casa.",
        ["I hope she comes and visits sometime."] = "Espero que venga a visitarme alguna vez.",
        ["Maybe."] = "Quizás.",
        ["Hello."] = "Hola.",
        ["I know you Mourners are up to no good, go away!"] = "Sé que ustedes, los dolientes, no traman nada bueno, ¡váyanse!",
        ["It's so good that people can go in and out of the city now! Elena has come to visit often."] = "¡Qué bueno que la gente pueda entrar y salir de la ciudad ahora! Elena ha venido de visita a menudo.",
    },
    ["Millie Miller"] = {
        ["Hello, adventurer. Welcome to Mill Lane Mill. Can I help you?"] = "Hola, aventurero. Bienvenido a Mill Lane Mill. ¿Puedo ayudarle?",
        ["Choose an option:"] = "Elige una opción:",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Miss Millicent Miller, the Miller of Mill Lane Mill. Our family has been milling flour for generations."] = "Soy la señorita Millicent Miller, la molinera de Mill Lane Mill. Nuestra familia lleva generaciones moliendo harina.",
        ["Don't you ever get fed up with flour?"] = "¿Nunca te hartas de la harina?",
        ["It's a good business to be in. People will always need flour."] = "Es un buen negocio. La gente siempre necesitará harina.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is Mill Lane Mill, source of the finest flour in Gielinor, and home to the Miller family for many generations."] = "Este es Mill Lane Mill, fuente de la mejor harina en Gielinor y hogar de la familia Miller durante muchas generaciones.",
        ["We take wheat from the field nearby and mill it into flour."] = "Tomamos trigo del campo cercano y lo molemos para convertirlo en harina.",
        ["Making flour is pretty easy. First of all, you need to get some wheat. You can pick some from wheat fields. There is one just outside the mill, but there are many others scattered across the world."] = "Hacer harina es bastante fácil. En primer lugar, necesitas conseguir algo de trigo. Puedes recoger algunos de los campos de trigo. Hay uno justo afuera del molino, pero hay muchos otros repartidos por todo el mundo.",
        ["Feel free to pick wheat from our field! There always seems to be plenty of wheat there."] = "¡Siéntete libre de recoger trigo de nuestro campo! Siempre parece haber mucho trigo allí.",
        ["Then I bring my wheat here?"] = "¿Entonces traigo mi trigo aquí?",
        ["Yes, or to one of the other mills in Gielinor. They all work the same way."] = "Sí, o a uno de los otros molinos en Gielinor. Todos funcionan de la misma manera.",
        ["Just take your wheat up two levels to the top floor of the mill and place some into the hopper."] = "Simplemente lleva tu trigo dos niveles hasta el piso superior del molino y coloca un poco en la tolva.",
        ["Then you need to start the grinding process by pulling the lever near the hopper. You can add more wheat, but each time you add wheat you'll have to pull the hopper lever again."] = "Luego debes iniciar el proceso de molienda tirando de la palanca cerca de la tolva. Puedes agregar más trigo, pero cada vez que agregues trigo tendrás que jalar la palanca de la tolva nuevamente.",
        ["So, where does the flour go then?"] = "Entonces, ¿adónde va la harina?",
        ["The flour appears in this room here. You'll need an empty pot to put the flour into. One pot will hold the flour made by one load of wheat."] = "La harina aparece aquí en esta habitación. Necesitarás una olla vacía para poner la harina. Una olla contendrá la harina obtenida con una carga de trigo.",
        ["You can buy empty pots from the general store in Lumbridge, south-east of here. You can also buy them from the Grand Exchange in Varrock or make them yourself."] = "Puedes comprar macetas vacías en general store en Lumbridge, al sureste de aquí. También puedes comprarlos en Grand Exchange en Varrock o hacerlos tú mismo.",
        ["That's all there is to it and you'll have a pot of flour."] = "Eso es todo y tendrás una olla de harina.",
        ["Great! Thanks for your help."] = "¡Genial! Gracias por tu ayuda.",
        ["cond=After choosing \"How do I mill flour?"] = "cond=Después de elegir \"¿Cómo muele harina?",
        ["Flour is ideal for making tasty cakes, pies or delicious bread. I'm not a cook so you'll have to ask a cook to find out how to bake things."] = "La harina es ideal para hacer deliciosos pasteles, tartas o deliciosos panes. No soy cocinero, así que tendrás que preguntarle a un cocinero para saber cómo hornear cosas.",
        ["You could also sell it on the Grand Exchange in Varrock for a profit! Likewise, if you need flour and do not have time to make it yourself, you can buy some there."] = "¡También puedes venderlo en Grand Exchange en Varrock para obtener ganancias! Asimismo, si necesitas harina y no tienes tiempo para hacerla tú mismo, puedes comprarla allí.",
        ["I'm fine, thanks."] = "Estoy bien, gracias.",
        ["How do I mill flour?"] = "¿Cómo muele harina?",
        ["Can you tell me about the battlefield?"] = "¿Puedes hablarme sobre el campo de batalla?",
        ["Yes, you can see the battlefield well from here. Saradomin has his camp right outside, and it's not good for business!"] = "Sí, puedes ver bien el campo de batalla desde aquí. Saradomin tiene su campamento justo afuera, ¡y no es bueno para el negocio!",
        ["Fortunately he's currently focusing mainly south, towards Zamorak, and we seem to have escaped the worse!"] = "Afortunadamente, actualmente se está centrando principalmente en el sur, hacia Zamorak, ¡y parece que hemos escapado de lo peor!",
        ["So we do the best we can. I can only hope that it is over soon!"] = "Así que hacemos lo mejor que podemos. ¡Solo puedo esperar que esto termine pronto!",
        ["We were lucky that the battle of Lumbridge left us largely undamaged. You can still see the battlefield to the south."] = "Tuvimos suerte de que la batalla de Lumbridge nos dejara prácticamente ilesos. Todavía puedes ver el campo de batalla hacia el sur.",
        ["But not long ago Saradomin himself set up camp right outside our mill! We were worried that the battle might damage our building."] = "¡Pero no hace mucho, el propio Saradomin instaló un campamento justo afuera de nuestro molino! Nos preocupaba que la batalla pudiera dañar nuestro edificio.",
        ["Fortunately Saradomin defended us from the assault of Zamorak, and defeated him in the end. I hate to think what might have happened if Zamorak had won!"] = "Afortunadamente, Saradomin nos defendió del asalto de Zamorak y al final lo derrotó. ¡Odio pensar qué habría pasado si Zamorak hubiera ganado!",
    },
    ["Miltog"] = {
        ["Do you want to buy a lamp, surface-dweller?"] = "¿Quieres comprar una lámpara de superficie?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes please."] = "Sí, por favor.",
        ["No thanks."] = "No, gracias.",
        ["Suit yourself."] = "Haz lo que quieras.",
        ["Can you fill a lamp with oil, please?"] = "¿Puedes llenar una lámpara con aceite, por favor?",
        ["You can do that yourself! Just put some swamp tar in the lamp oil still here and then use the lamp on the still."] = "¡Puedes hacerlo tú mismo! Simplemente ponga un poco de alquitrán de pantano en el alambique de aceite de la lámpara y luego use la lámpara en el alambique.",
        ["How do the lamps around the city work?"] = "¿Cómo funcionan las lámparas de la ciudad?",
        ["They work by our very own Dorgeshuun magic!"] = "¡Trabajan con nuestra propia magia Dorgeshuun!",
        ["Sometimes they don't work very well, though. The light orbs blow and they have to be replaced."] = "Sin embargo, a veces no funcionan muy bien. Los orbes de luz explotan y hay que reemplazarlos.",
        ["If you ever see a lamp that's gone out, you can fix it by replacing the light orb. You can make new light orbs out of glass, and use a piece of wire on them to add the filament."] = "Si alguna vez ves una lámpara apagada, puedes arreglarla reemplazando el orbe de luz. Puedes hacer nuevos orbes de luz con vidrio y usar un trozo de alambre para agregar el filamento.",
        ["There's a machine in the south of the city that makes the wire you need."] = "Hay una máquina en el sur de la ciudad que fabrica el cable que necesitas.",
    },
    ["Milton the Miller"] = {
        ["Oh, hello. What do you want?"] = "Oh, hola. ¿Qué deseas?",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Milton the Miller of Mill Road Mill. I'll give you one guess what I do for a living."] = "Soy Milton the Miller de Mill Road Mill. Te daré una idea de a qué me dedico.",
        ["You're a miller?"] = "¿Eres molinero?",
        ["And they say common sense is dying out."] = "Y dicen que el sentido común está desapareciendo.",
        ["You're an undercover White Knight?"] = "¿Eres un Caballero Blanco encubierto?",
        ["Very funny."] = "Muy divertido.",
        ["You're an evil culinaromancer?"] = "¿Eres un malvado culinaromante?",
        ["You're a knight who is also a culinaromancer?"] = "¿Eres un caballero y también un culinaromante?",
        ["Hah, yes. They call me the Knight of the Living Bread."] = "Ja, sí. Me llaman el Caballero del Pan Vivo.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["It's a windmill, you idiot."] = "Es un molino de viento, idiota.",
        ["How do I mill flour?"] = "¿Cómo muele harina?",
        ["You go upstairs, put some wheat in the hopper and pull the lever, then the milled flour comes out here."] = "Subes las escaleras, pones un poco de trigo en la tolva y tiras de la palanca, luego sale la harina molida por aquí.",
        ["Then you keep doing that all day, every day, because it's the family business and you have to stay in the family business."] = "Luego sigues haciendo eso todo el día, todos los días, porque es el negocio familiar y tienes que permanecer en el negocio familiar.",
        ["Goodbye."] = "Adiós.",
        ["I want to get in to Sigmund's base."] = "Quiero entrar a la base de Sigmund.",
        ["Didn't you hear? The base was destroyed. There's no H.A.M. activity here any more."] = "¿No te enteraste? La base fue destruida. No hay H.A.M. actividad aquí más.",
        ["To be honest, I think that's for the best. Sigmund was always a little more extreme than what I was comfortable with."] = "Para ser honesto, creo que es lo mejor. Sigmund siempre fue un poco más extremo de lo que me hacía sentir cómodo.",
    },
    ["Mime"] = {
        ["Hello."] = "Hola.",
        ["Select an Option"] = "Selecciona una opción",
        ["How are you?"] = "¿Cómo estás?",
        ["Bored, huh?"] = "Aburrido, ¿eh?",
        ["What are you up to?"] = "¿Qué estás haciendo?",
        ["Not sure what to do with yourself?"] = "¿No estás seguro de qué hacer contigo mismo?",
        ["What do you think of Party Pete?"] = "¿Qué opinas de Party Pete?",
        ["Yes, he's certainly enthusiastic. Anything else?"] = "Sí, ciertamente está entusiasmado. ¿Algo más?",
        ["Oh, really? I guess life isn't just all partying, even for Party Pete."] = "Oh, ¿en serio? Supongo que la vida no es sólo fiesta, incluso para Party Pete.",
        ["Know any good jokes?"] = "¿Conoces algún buen chiste?",
        ["Uhuh."] = "Ajá.",
        ["Right."] = "Correcto.",
        ["Okay."] = "Está bien.",
        ["I said any GOOD jokes!"] = "¡Dije chistes BUENOS!",
        ["Bye!"] = "¡Adiós!",
    },
    ["Mimic (NPC)"] = {
        ["The Giant Mimic fight takes place in a <span style=\"color:#088A08\">safe area</span> - no items will be lost on death. You have 2 minutes 30 seconds to kill the boss or the Giant Mimic will kill you."] = "La pelea de Giant Mimic se lleva a cabo en un área segura <span style=\"color:#088A08\"></span>: no se perderán objetos al morir. Tienes 2 minutos y 30 segundos para matar al jefe o el Giant Mimic te matará.",
        ["Killing the boss will reward you with loot crates, which contain random prizes, and a chance at the rare tradeable tongue cape and mimic plushie."] = "Matar al jefe te recompensará con cajas de botín, que contienen premios aleatorios, y la oportunidad de conseguir una rara capa de lengua intercambiable y un peluche imitador.",
        ["Ooooh treasure!"] = "¡Oh tesoro!",
        ["The Mimic leaps about angrily as you try to reach inside it's{{Sic}} mouth."] = "El Mimic salta enojado mientras intentas meter la mano dentro de su boca {{Sic}}.",
        ["Well that didn't work..."] = "Bueno, eso no funcionó...",
        ["The Mimic looks at you, you can't understand him but he looks worried."] = "El Mimic te mira, no puedes entenderlo pero parece preocupado.",
        ["I'm sorry, I don't really know what you want."] = "Lo siento, realmente no sé lo que quieres.",
        ["The Mimic looks at you again, he opens his mouth and from it you see a Mimic Token."] = "El Mimic te mira de nuevo, abre la boca y en ella ves una Ficha de Mimic.",
        ["No way... you're not getting me again."] = "De ninguna manera... no me entenderás otra vez.",
        ["The Mimic looks at you, you can somehow deduct with what limited knowledge of treasure chest body language you have that he appears to be upset."] = "El Mimic te mira, de alguna manera puedes deducir con el conocimiento limitado que tienes del lenguaje corporal del cofre del tesoro que parece estar molesto.",
        ["Well... if you insist."] = "Bueno... si insistes.",
        ["*(Without space in inventory:)*"] = "*(Sin espacio en inventario:)*",
        ["Wait, hand on I don't ahve space in my backpack!"] = "Espera, ¡mano a la obra! ¡No tengo espacio en mi backpack!",
        ["The Mimic looks at you, you feel like in a way he just sighed at you."] = "El Mimic te mira, sientes como si en cierto modo te acabara de suspirar.",
        ["You need to clear a space in your inventory before you can get the Mimic token from the Mimic."] = "Debes despejar un espacio en tu inventario antes de poder obtener la ficha Mimic del Mimic.",
        ["*(With space in inventory:)*"] = "*(Con espacio en inventario:)*",
        ["You reach insite the Mimic and grab a{{Sic}} untradeable Mimic kill token."] = "Llegas al interior del Mimic y agarras una ficha de muerte de Mimic no intercambiable {{Sic}}.",
        ["Thank you!"] = "¡Gracias!",
        ["You may be able to find more tradeable tokens by killing monsters throughout Gielinor or you might get incredibly lucky and find one skilling!"] = "Es posible que puedas encontrar más tokens intercambiables matando monstruos a lo largo de Gielinor o ¡puedes tener mucha suerte y encontrar una habilidad!",
        ["The Mimic has no more tokens to give you."] = "El Mimic no tiene más fichas para darte.",
    },
    ["Mimic"] = {
        ["The Giant Mimic fight takes place in a <span style=\"color:#088A08\">safe area</span> - no items will be lost on death. You have 2 minutes 30 seconds to kill the boss or the Giant Mimic will kill you."] = "La pelea de Giant Mimic se lleva a cabo en un área segura <span style=\"color:#088A08\"></span>: no se perderán objetos al morir. Tienes 2 minutos y 30 segundos para matar al jefe o el Giant Mimic te matará.",
        ["Killing the boss will reward you with loot crates, which contain random prizes, and a chance at the rare tradeable tongue cape and mimic plushie."] = "Matar al jefe te recompensará con cajas de botín, que contienen premios aleatorios, y la oportunidad de conseguir una rara capa de lengua intercambiable y un peluche imitador.",
        ["Ooooh treasure!"] = "¡Oh tesoro!",
        ["The Mimic leaps about angrily as you try to reach inside it's{{Sic}} mouth."] = "El Mimic salta enojado mientras intentas meter la mano dentro de su boca {{Sic}}.",
        ["Well that didn't work..."] = "Bueno, eso no funcionó...",
        ["The Mimic looks at you, you can't understand him but he looks worried."] = "El Mimic te mira, no puedes entenderlo pero parece preocupado.",
        ["I'm sorry, I don't really know what you want."] = "Lo siento, realmente no sé lo que quieres.",
        ["The Mimic looks at you again, he opens his mouth and from it you see a Mimic Token."] = "El Mimic te mira de nuevo, abre la boca y en ella ves una Ficha de Mimic.",
        ["No way... you're not getting me again."] = "De ninguna manera... no me entenderás otra vez.",
        ["The Mimic looks at you, you can somehow deduct with what limited knowledge of treasure chest body language you have that he appears to be upset."] = "El Mimic te mira, de alguna manera puedes deducir con el conocimiento limitado que tienes del lenguaje corporal del cofre del tesoro que parece estar molesto.",
        ["Well... if you insist."] = "Bueno... si insistes.",
        ["*(Without space in inventory:)*"] = "*(Sin espacio en inventario:)*",
        ["Wait, hand on I don't ahve space in my backpack!"] = "Espera, ¡mano a la obra! ¡No tengo espacio en mi backpack!",
        ["The Mimic looks at you, you feel like in a way he just sighed at you."] = "El Mimic te mira, sientes como si en cierto modo te acabara de suspirar.",
        ["You need to clear a space in your inventory before you can get the Mimic token from the Mimic."] = "Debes despejar un espacio en tu inventario antes de poder obtener la ficha Mimic del Mimic.",
        ["*(With space in inventory:)*"] = "*(Con espacio en inventario:)*",
        ["You reach insite the Mimic and grab a{{Sic}} untradeable Mimic kill token."] = "Llegas al interior del Mimic y agarras una ficha de muerte de Mimic no intercambiable {{Sic}}.",
        ["Thank you!"] = "¡Gracias!",
        ["You may be able to find more tradeable tokens by killing monsters throughout Gielinor or you might get incredibly lucky and find one skilling!"] = "Es posible que puedas encontrar más tokens intercambiables matando monstruos a lo largo de Gielinor o ¡puedes tener mucha suerte y encontrar una habilidad!",
        ["The Mimic has no more tokens to give you."] = "El Mimic no tiene más fichas para darte.",
    },
    ["Mimicking Soul"] = {
        ["A mimicking soul appears nearby. Corner them before they get away."] = "Un mimicking soul aparece cerca. Acorralalos antes de que se escapen.",
        ["As you corner the mimicking soul, they revert to their true form."] = "A medida que acorralas a los mimicking soul, vuelven a su verdadera forma.",
        ["The mimicking soul disappears before you can catch it."] = "El mimicking soul desaparece antes de que puedas atraparlo.",
        ["As you guide the mimicking soul to the underworld, they thank you by sharing some of their [Skill] knowledge."] = "Mientras guías al mimicking soul al inframundo, te lo agradecerán compartiendo algunos de sus conocimientos sobre el [Skill].",
        ["You gain [number] [Skill] XP."] = "Obtienes [número] [Skill] XP.",
        ["The lost soul disappears before you could guide it onwards."] = "El alma perdida desaparece antes de que puedas guiarla hacia adelante.",
    },
    ["Mind-controlled monkey butler"] = {
        ["Would you like to hire the mind-controlled monkey butler?"] = "¿Quieres contratar el mind-controlled monkey butler?",
        ["Yes."] = "Sí.",
        ["Happy! Steve has a new Master."] = "¡Feliz! Steve tiene un nuevo Maestro.",
        ["Happy. Master need Steve?"] = "Feliz. ¿El Maestro necesita a Steve?",
        ["Happy. Master need help?"] = "Feliz. ¿El Maestro necesita ayuda?",
        ["Select an Option"] = "Seleccione una opción",
        ["Go to the bank/sawmill..."] = "Ir al banco/aserradero...",
        ["Take something to the bank"] = "llevar algo al banco",
        ["Can you take something to the bank for me?"] = "¿Puedes llevarme algo al banco?",
        ["Happy! Give to Steve. Steve take to bank."] = "¡Feliz! Dáselo a Steve. Steve lleva al banco.",
        ["Bring something from the bank"] = "Trae algo del banco",
        ["What would you like from the bank?"] = "¿Qué te gustaría del banco?",
        ["*Option set 1*"] = "*Conjunto de opciones 1*",
        ["*(If the player has previously used the butler to retrieve something from the bank:)*"] = "*(Si el player ha utilizado previamente al mayordomo para recuperar algo del banco:)*",
