        ["The servant goes to the bank."] = "El sirviente va al banco.",
        ["*(If the player requested planks and has a plank box with space to hold them:)*"] = "*(Si el player solicitó planks y tiene una caja de tablones con espacio para guardarlos:)*",
        ["Happy! Steve put Master's stuff in Master's plank box."] = "¡Feliz! Steve puso las cosas de la Maestra en la caja de tablones de la Maestra.",
        ["*(If the player did not have enough space in the backpack to hold two or more items:)*"] = "*(Si el player no tenía suficiente espacio en el backpack para contener dos o más elementos:)*",
        ["Happy! Steve hold Master's stuff until Master need them."] = "¡Feliz! Steve guarda las cosas del Maestro hasta que el Maestro las necesite.",
        ["Take it back to the bank"] = "Llévalo de vuelta al banco",
        ["Take it back to the bank please."] = "Llévalo al banco, por favor.",
        ["Happy. Steve return items."] = "Feliz. Steve devuelve artículos.",
        ["Thanks"] = "gracias",
        ["Thanks."] = "Gracias.",
        ["*(If the player did not have enough space in the backpack to hold one item:)*"] = "*(Si el player no tenía suficiente espacio en backpack para contener un elemento:)*",
        ["Happy! Steve hold Master's thing until Master need it."] = "¡Feliz! Steve sostiene la cosa del Maestro hasta que el Maestro la necesite.",
