    },
    ["Miner (Jatizso)"] = {
        ["*When greeting the Miner, one of the following conversations will occur:*"] = "*Al saludar al Minero, ocurrirá una de las siguientes conversaciones:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["My back is killing me!"] = "¡Mi espalda me está matando!",
        ["Could be worse, it could be the trolls killing you."] = "Podría ser peor, podrían ser los trolls los que te están matando.",
        ["How very droll."] = "Qué gracioso.",
        ["Bah! I resist your attempts at jollity."] = "¡Bah! Me resisto a tus intentos de alegría.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["This place rocks!"] = "¡Este lugar es genial!",
        ["No it doesn't, it stays perfectly still."] = "No, no es así, permanece perfectamente quieto.",
        ["Bah! Be quiet, pedant."] = "¡Bah! Cállate, pedante.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["How's your prospecting going?"] = "¿Cómo va tu prospección?",
        ["Mine's going pretty well."] = "El mío va bastante bien.",
        ["Mine? Mine...you get it?"] = "¿Mío? El mío... ¿lo entiendes?",
        ["Oh, I got it. That doesn't make it funny though."] = "Oh, lo tengo. Aunque eso no lo hace divertido.",
        ["Suit yourself."] = "Haz lo que quieras.",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Gah! Trolls everywhere. There's no escape!"] = "¡Gah! Trolls por todas partes. ¡No hay escapatoria!",
        ["You could just leave the mine."] = "Podrías dejar la mina.",
        ["Oh, I'd never thought of that."] = "Oh, nunca había pensado en eso.",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["I've been here for two days straight. When I close my eyes I see rocks."] = "Llevo aquí dos días seguidos. Cuando cierro los ojos veo rocas.",
        ["Why would anyone stay here for so long?"] = "¿Por qué alguien se quedaría aquí tanto tiempo?",
        ["I fear the outside. I fear the big light."] = "Temo al exterior. Temo a la gran luz.",
        ["Oh dear. Being underground for so long may have driven you mad."] = "Dios mío. Es posible que pasar tanto tiempo bajo tierra te haya vuelto loco.",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["High hoe, high hoe!"] = "¡Azada alta, azada alta!",
        ["Why are you singing about farming implements at altitude?"] = "¿Por qué cantas sobre implementos agrícolas en la altura?",
        ["I don't know, I've never thought about it. Ask my Dad, he taught me the song."] = "No lo sé, nunca lo había pensado. Pregúntale a mi Dad, él me enseñó la canción.",
    },
