    ["Monkey (Monkey Madness)"] = {
        ["Hello there, monkey."] = "Hola, mono.",
        ["Are we there yet??"] = "¿Ya llegamos?",
        ["Not quite yet ... you should get back in my backpack now."] = "Aún no... deberías volver a mi backpack ahora.",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["Oww!"] = "¡Ay!",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["What are you trying to do to me!?"] = "¿¡Qué intentas hacerme!?",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["Oi!"] = "¡Oi!",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["That hurt!"] = "¡Eso duele!",
        ["I'm tired!"] = "¡Estoy cansado!",
        ["I'm hungry!"] = "¡Tengo hambre!",
        ["In the jungle, the mighty jungle..."] = "En la jungla, la poderosa jungla...",
        ["*snore* ... Ook? Argh!! It's the Shaihakan!"] = "*ronca* ... ¿Ok? Argh!! ¡Es el Shaihakan!",
        ["The what?"] = "¿El qué?",
        ["Oh, nothing - it was just a bad dream..."] = "Oh, nada, fue solo un mal sueño...",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Are we nearly there yet?"] = "¿Ya casi llegamos?",
        ["It's really crowded in here!"] = "¡Hay mucha gente aquí!",
        ["Mmmm - my favourite!"] = "Mmmm - ¡mi favorito!",
        ["Mmmm - bananas!"] = "Mmmm - ¡plátanos!",
        ["Mmmm - thank you!"] = "Mmmm - ¡gracias!",
        ["Mmmm - you shouldn't have!"] = "Mmmm, ¡no deberías haberlo hecho!",
        ["The monkey chews on the banana and spits out a clue!"] = "¡El mono mastica el plátano y escupe una pista!",
        ["I don't want that!"] = "¡No quiero eso!",
        ["Yay! I'm free!"] = "¡Yay! ¡Soy libre!",
        ["Sorry, you can't bank the monkey."] = "Lo siento, no puedes depositar al mono.",
        ["The monkey in your backpack disappears in a puff of smoke!"] = "¡El mono de tu backpack desaparece en una nube de humo!",
    },
    ["Monkey (Mos Le'Harmless)"] = {
        ["*(Without a Monkeyspeak amulet) Conversation 1*"] = "*(Sin amuleto Monkeyspeak) Conversación 1*",
        ["Eeekeek ookeek!"] = "¡Eeekeek ookeek!",
        ["*Conversation 2*"] = "*Conversación 2*",
        ["Arr!"] = "¡Arr!",
        ["Bored now..."] = "Aburrido ahora...",
        ["*Conversation 3*"] = "*Conversación 3*",
        ["Let me go, can't ye hear them? Howlin' in the dark..."] = "Déjame ir, ¿no puedes oírlos? Aullando en la oscuridad...",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["I'm not hangin' around te be killed!"] = "¡No voy a quedarme esperando que me maten!",
        ["The Horrors, the Horrors!"] = "¡Los horrores, los horrores!",
        ["*Conversation 4*"] = "*Conversación 4*",
        ["I'm not goin' back in that brewery, not fer all the Bitternuts I can carry!"] = "¡No volveré a esa cervecería, no por todas las Bitternuts que pueda llevar!",
        ["*Conversation 5*"] = "*Conversación 5*",
        ["Are ye here for...the stuff?"] = "¿Estás aquí por... las cosas?",
        ["What?"] = "¿Qué?",
        ["You know...the 'special' bananas?"] = "Ya sabes... ¿los plátanos 'especiales'?",
        ["No...why do you ask?"] = "No... ¿por qué lo preguntas?",
        ["No reason. Have a nice day."] = "Sin motivo. Que tenga un lindo día.",
        ["*Conversation 6*"] = "*Conversación 6*",
        ["Arr! Yer messin with me monkey plunder!"] = "¡Arr! ¡Te estás metiendo con mi botín de mono!",
    },
    ["Monkey Child"] = {
        ["Select an Option"] = "Selecciona una opción",
        ["How are you today?"] = "¿Cómo estás hoy?",
        ["I'm good, uncle! I'd quite like my toy back now..."] = "¡Estoy bien, tío! Me gustaría mucho recuperar mi juguete ahora...",
        ["I've lost that toy you gave me..."] = "He perdido ese juguete que me diste...",
        ["You lost it!? What am I going to play with now?"] = "¿¡Lo perdiste!? ¿Con qué voy a jugar ahora?",
        ["The monkey begins to cry..."] = "El mono empieza a llorar...",
        ["The monkey is too busy crying."] = "El mono está demasiado ocupado llorando.",
        ["I'm feeling a bit better now..."] = "Me siento un poco mejor ahora...",
        ["It's good to see you've cheered up then."] = "Entonces es bueno ver que te has animado.",
        ["Yes - Aunty gave me a new toy!"] = "Sí. ¡La tía me regaló un juguete nuevo!",
        ["That's really sweet of her!"] = "¡Eso es muy dulce de su parte!",
        ["Wow - can I borrow it?"] = "Vaya, ¿me lo prestas?",
        ["Only if you promise to give it back..."] = "Sólo si prometes devolverlo...",
        ["Ok, I promise!"] = "¡Vale, lo prometo!",
        ["[The monkey child gives you some kind of talisman.]"] = "[El monkey child te ofrece una especie de talismán.]",
        ["Actually, I don't really need it."] = "En realidad, no lo necesito.",
        ["Hello there, uncle!"] = "¡Hola, tío!",
        ["Thank you uncle - I love you!"] = "Gracias tío, ¡te amo!",
        ["The monkey child gives you a hug!"] = "¡El monkey child te da un abrazo!",
        ["Thank you uncle, but I don't want one!"] = "¡Gracias tío, pero no quiero uno!",
        ["I don't want that - it looks really scary!"] = "No quiero eso, ¡parece realmente aterrador!",
        ["I have no use for that."] = "No me sirve eso.",
    },
    ["Monkey boy"] = {
        ["Hello?"] = "¿Hola?",
        ["Hi there, is something wrong?"] = "Hola, ¿pasa algo?",
        ["Oh wow you can understand me!"] = "¡Oh, vaya, puedes entenderme!",
        ["I happen to be proficient in many languages... anyway, what are you doing here in Varrok?"] = "Resulta que hablo muchos idiomas... de todos modos, ¿qué estás haciendo aquí en Varrok?",
        ["Well my uncle Daga's shop has been a bit slow recently, and we just got some new stock in so I decided to help and advertise a bit."] = "Bueno, la tienda de mi tío Daga ha estado un poco lenta recientemente y acabamos de recibir algunas existencias nuevas, así que decidí ayudar y publicitar un poco.",
        ["What new stock's that then?"] = "¿Qué acciones nuevas son esas entonces?",
        ["Oh just more scimitars, we got a few of there weird red ones too... dra-something..."] = "Oh, solo más scimitars, también tenemos algunos rojos raros... dra-algo...",
        ["Dragon?!"] = "¡¿Dragón?!",
        ["Yeah that's the one, are they valuable?"] = "Sí, ese es el indicado, ¿son valiosos?",
        ["Um... no... not really... I'll be right back..."] = "Um... no... realmente no... Ya vuelvo...",
        ["Oh you bought one of those dra-whatever things, I was told they're not much good."] = "Oh, compraste una de esas cosas dra-lo que sea, me dijeron que no sirven de mucho.",
        ["Oh no it's excellent!"] = "¡Oh, no, es excelente!",
        ["Well I'll be a monkey's nephew, I'm such a noob!"] = "Bueno, seré el sobrino de un mono, ¡soy un novato!",
    },
    ["Monkey colonist"] = {
        ["*Dialogue 1: *"] = "*Diálogo 1:*",
        ["The camels are watching us!"] = "¡Los camellos nos están mirando!",
        ["*Dialogue 2: *"] = "*Diálogo 2:*",
        ["Bwah! Bwah! I wanna go home! There's sand in my sandals."] = "¡Bwa! ¡Bah! ¡Quiero ir a casa! Hay arena en mis sandalias.",
        ["*Dialogue 3: *"] = "*Diálogo 3:*",
        ["They said we were going to the dessert! Where's my banana split?"] = "¡Dijeron que íbamos al postre! ¿Dónde está mi banana split?",
        ["*Dialogue 4: *"] = "*Diálogo 4:*",
        ["I guess the desert isn't too bad. At least I'm catching some sun."] = "Supongo que el desierto no está tan mal. Al menos estoy tomando algo de sol.",
        ["*Dialogue 5: *"] = "*Diálogo 5:*",
        ["I never knew there were so many hairless apes in the world."] = "Nunca pensé que había tantos simios sin pelo en el mundo.",
    },
    ["Monkey minder"] = {
        ["Hello there."] = "Hola.",
        ["Hello, sir."] = "Hola, señor.",
        ["I haven't seen Monkey Minders here before..."] = "No había visto Monkey Minders aquí antes...",
        ["Yes, you wouldn't have. We have newly been posted here."] = "Sí, no lo habrías hecho. Recientemente hemos sido publicados aquí.",
        ["But why do we need Monkey Minders?"] = "¿Pero por qué necesitamos Monkey Minders?",
        ["It's entirely necessary: just take a look at the monkeys. They've been multiplying out of control!"] = "Es totalmente necesario: basta con echar un vistazo a los monos. ¡Se han estado multiplicando sin control!",
        ["Every time we turn our backs another one of them tries to break free. It's almost as if they're plotting to escape!"] = "Cada vez que les damos la espalda, otro de ellos intenta liberarse. ¡Es casi como si estuvieran planeando escapar!",
        ["Select an Option"] = "Selecciona una opción",
        ["Why have the monkeys been multiplying?"] = "¿Por qué se han multiplicado los monos?",
        ["We just don't know. Perhaps it's the weather. Perhaps it's something in the food. Perhaps it's just that time of year."] = "Simplemente no lo sabemos. Quizás sea el clima. Quizás sea algo en la comida. Quizás sea sólo esa época del año.",
        ["Your guess is as good as ours."] = "Tu suposición es tan buena como la nuestra.",
        ["What are you going to do about the monkeys?"] = "¿Qué vas a hacer con los monos?",
        ["We're going to post enough men here to be able to contain the monkeys in case they manage to escape."] = "Vamos a publicar suficientes hombres aquí para poder contener a los monos en caso de que logren escapar.",
        ["Is that very likely?"] = "¿Es eso muy probable?",
        ["Stranger things have happened in Ardougne."] = "Han sucedido cosas más extrañas en Ardougne.",
        ["Ook! Ook!"] = "¡Ok! ¡Ok!",
        ["Why do you monkeys keep trying to escape? Good thing I've caught you before you got away, you little scoundrel."] = "¿Por qué los monos siguen intentando escapar? Menos mal que te atrapé antes de que escaparas, pequeño sinvergüenza.",
        ["Ook!"] = "¡Ok!",
        ["Let's put you back in your cage where you belong..."] = "Vamos a ponerte de nuevo en tu jaula donde perteneces...",
        ["Ok!"] = "¡Vale!",
        ["What??"] = "¿Qué?",
        ["Er... Ook?"] = "Er... ¿vale?",
        ["I must be imagining things... monkeys can't talk."] = "Debo estar imaginando cosas... los monos no pueden hablar.",
        ["Stop hassling me!"] = "¡Deja de molestarme!",
        ["Be quiet, you monkey!"] = "¡Cállate, mono!",
        ["Ook Ook!"] = "¡Ok, ok!",
        ["I don't know what kind of monkey you think you are, but you're not getting anywhere near my monkeys!"] = "No sé qué clase de mono crees que eres, ¡pero no te acercarás a mis monos!",
        ["My word – what are you doing in there?"] = "Dios mío, ¿qué estás haciendo ahí dentro?",
        ["I ... er ... I don't know! One minute I was asleep, and the next minute I was here surrounded by monkeys!"] = "Yo... eh... ¡No lo sé! ¡En un momento estaba dormido y al minuto siguiente estaba aquí rodeado de monos!",
        ["Well, don't worry. We'll have you out of there shortly."] = "Bueno, no te preocupes. Te sacaremos de allí en breve.",
        ["Thank you."] = "Gracias.",
        ["No problem."] = "No hay problema.",
    },
    ["Mono"] = {
        ["Hullo."] = "Hola.",
        ["Who are you?"] = "¿Quién eres?",
        ["What are you?"] = "¿Qué eres?",
        ["Cyclops."] = "Cíclope.",
        ["Why are you here?"] = "¿Por qué estás aquí?",
        ["Fight."] = "Pelea.",
        ["Well.. it's been nice chatting. Goodbye."] = "Bueno... ha sido agradable charlar. Adiós.",
    },
    ["Moorrissey"] = {
        ["Yes?"] = "¿Sí?",
        ["Ahhh! It's a corrupted, talking Yak!"] = "¡Ahhh! ¡Es un Yak corrupto y parlante!",
        ["Ugh, whatever."] = "Uf, lo que sea.",
        ["Um... are you OK?"] = "Um... ¿estás bien?",
        ["Yes? Of course I'm fine. Gods. Like, paint a picture, it will last longer. Do you want something?"] = "¿Sí? Por supuesto que estoy bien. Gallinero. Por ejemplo, pinta un cuadro, durará más. ¿Quieres algo?",
        ["Oh, it's you."] = "Oh, eres tú.",
        ["Select an option{{anchor|init}}"] = "Seleccione una opción{{anchor|init}}",
        ["How does the Yak Track work?"] = "¿Cómo funciona Yak Track?",
        ["You get to go on an adventure and earn rewards along the way. You can complete tasks to progress along the track. You will be given a choice between two tasks at a time, but you only need to complete one of them to progress. If you don't feel like doing either of them then you can use a task skip to move on. As you progress along the track you will earn rewards; Premier Club members and those who have purchased a Premier Pass will earn additional premium rewards. If you purchase a Premier Pass you will receive any premium rewards you would have been eligible for."] = "Puedes embarcarte en una aventura y ganar recompensas a lo largo del camino. Puedes completar tareas para progresar a lo largo de la pista. Podrás elegir entre dos tareas a la vez, pero solo necesitarás completar una de ellas para progresar. Si no tiene ganas de hacer ninguna de las dos, puede saltar tareas para seguir adelante. A medida que avances en la pista, ganarás recompensas; Los miembros de Premier Club y aquellos que hayan comprado un Premier Pass obtendrán recompensas premium adicionales. Si compra un Premier Pass, recibirá todas las recompensas premium para las que hubiera sido elegible.",
        ["Sounds great!"] = "¡Suena genial!",
        ["Can you recommend any good music?"] = "¿Puedes recomendar alguna buena música?",
        ["I've been listening to a lot of 'Panyak! at the Disco' lately."] = "¡He estado escuchando mucho 'Panyak! en la discoteca' últimamente.",
        ["What's a 'disco'?"] = "¿Qué es una 'discoteca'?",
        ["I have no clue. But I really like their music. I've been listening to 'Welcome to the Yak parade' on repeat all day..."] = "No tengo ni idea. Pero me gusta mucho su música. He estado escuchando 'Welcome to the Yak Parade' todo el día...",
        ["I'm amazed you convinced a musician to play on repeat for you."] = "Me sorprende que hayas convencido a un músico para que toque repetidamente para ti.",
        ["I'm paying them with exposure, you see. If you want to embrace your inner rage, try some 'Yak Sabbath'. 'Yak Veil Brides' are also really good. Or like, whatever you enjoy listening to. It's whatever."] = "Les estoy pagando con exposición, ya ves. Si quieres abrazar tu ira interior, prueba un poco de 'Yak Sabbath'. 'Yak Veil Brides' también son realmente buenas. O lo que sea que te guste escuchar. Es lo que sea.",
        ["What's your backstory?"] = "¿Cuál es tu historia de fondo?",
        ["I was refusing to leave my barn, listening to Yak-182 and suffocating under the weight of the misery of life when a dark wizard asked me if I wanted to travel with her. She was brooding, mysterious, powerful... and had great eyeliner. I knew we were soulmates. So I was all like 'gods yes', you know?"] = "Me negaba a salir de mi granero, escuchaba Yak-182 y me asfixiaba bajo el peso de la miseria de la vida cuando un mago oscuro me preguntó si quería viajar con ella. Era melancólica, misteriosa, poderosa... y tenía un delineador de ojos fantástico. Sabía que éramos almas gemelas. Entonces yo estaba como \"dioses, sí\", ¿sabes?",
        ["Err... sure."] = "Err... seguro.",
        ["My mum tried to stop me, because of course she did. She keeps trying to tell me it's 'just a phase'. Like... what the Yak? Travelling with a dark wizard and being physically altered by the sinister forces they command isn't 'just a phase', SHARON."] = "Mi mamá intentó detenerme, porque por supuesto que lo hizo. Ella sigue intentando decirme que es \"sólo una fase\". Como... ¿qué diablos? Viajar con un mago oscuro y ser alterado físicamente por las fuerzas siniestras que él controla no es \"sólo una fase\", SHARON.",
        ["The Yak angrily blows his bangs out of his eyes."] = "El Yak, enojado, se quita el flequillo de los ojos.",
        ["I see. Thanks for sharing."] = "Ya veo. Gracias por compartir.",
        ["Bye!"] = "¡Adiós!",
        ["Whatever."] = "Lo que sea.",
    },
    ["Morai"] = {
        ["[number]/14 owls tracked"] = "[número]/14 búhos rastreados",
        ["Congratulations! You have completed: 'Birds of Prey' - Track all of the owls for Deryn."] = "¡Felicitaciones! Has completado: 'Aves de presa': rastrea todos los búhos para Deryn.",
        ["You have unlocked the title: 'Player, {{Colour'|colour=#00FF00}}"] = "Has desbloqueado el título: 'Player, {{Colour'|colour=#00FF00}}",
        ["You can activate this via the 'Titles' tab in the Customisations interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz de Personalizaciones.",
        ["There won't be any insects eating the garden plants on my watch."] = "No habrá insectos comiendo las plantas del jardín bajo mi supervisión.",
    },
    ["Mord Gunnars"] = {
        ["I do not speak to outlanders. If you have anything of import to say, go and speak to the Chieftain."] = "No hablo con forasteros. Si tienes algo importante que decir, ve y habla con el Cacique.",
        ["Hail the conquering hero!"] = "¡Salve al héroe conquistador!",
        ["Heh. Thanks - I was pretty heroic even if I say so myself."] = "Je. Gracias, fui bastante heroico incluso si lo digo yo mismo.",
        ["Tell me more about Jatizso's history."] = "Cuéntame más sobre la historia de Jatizso.",
        ["Tell me more about Jatizso."] = "Cuéntame más sobre Jatizso.",
        ["Well now, the history of the isles is a bloody tale. When told in its intended form it takes 9 days and 9 nights. However, I will give you the abridged version."] = "Bueno, la historia de las islas es una historia sangrienta. Cuando se cuenta en la forma prevista, se necesitan 9 días y 9 noches. Sin embargo, les daré la versión abreviada.",
        ["Phew!"] = "¡Uf!",
        ["Four generations ago there was a mighty king who ruled wisely and was loved by all."] = "Hace cuatro generaciones hubo un rey poderoso que gobernó sabiamente y era amado por todos.",
        ["He had many sons, most of whom proved themselves in the usual Fremennik ways of fighting, sailing, drinking and so on."] = "Tuvo muchos hijos, la mayoría de los cuales demostraron su valía en las formas habituales Fremennik de luchar, navegar, beber, etc.",
        ["His youngest two sons, however, were a problem. Ever since they were old enough to hit one another they had bickered and fought."] = "Sus dos hijos menores, sin embargo, eran un problema. Desde que tuvieron edad suficiente para golpearse, habían discutido y peleado.",
        ["Their names were Jatizso and Neitiznot."] = "Sus nombres eran Jatizso y Neitiznot.",
        ["Hey! Who's telling this story?"] = "¡Oye! ¿Quién cuenta esta historia?",
        ["Ahem. At the time it was customary for the Kings' sons to claim a prize from his treasury when they came of age."] = "Ejem. En aquella época era costumbre que los hijos de los Reyes reclamaran un premio de su tesoro cuando alcanzaban la mayoría de edad.",
        ["Each brother rallied support and strode out to confront the other on the field of battle to claim the same prize."] = "Cada hermano reunió apoyo y salió a enfrentarse al otro en el campo de batalla para reclamar el mismo premio.",
        ["The brothers met on the field, limbs were bruised, bones were crushed and heads clashed."] = "Los hermanos se encontraron en el campo, las extremidades resultaron magulladas, los huesos aplastados y las cabezas chocaron.",
        ["They probably didn't notice the head-clashing bit. Too thick skulled!"] = "Probablemente no notaron el choque de cabezas. ¡Cráneo demasiado grueso!",
        ["Can I finish the story without interruptions?"] = "¿Puedo terminar la historia sin interrupciones?",
        ["Carry on dear."] = "Continúa querida.",
        ["Anyway, long into the night they fought, until they stood alone, facing each other."] = "De todos modos, lucharon hasta bien entrada la noche, hasta que se quedaron solos, uno frente al otro.",
        ["On the second day the old king, whose patience was exhausted, strode out onto the field and demanded to know who had claimed his prize."] = "El segundo día, el viejo rey, cuya paciencia estaba agotada, salió al campo y preguntó quién había reclamado su premio.",
        ["Jatizso looked at his father and told him yes, it was his, to which the other called out 'No! It's not'."] = "Jatizso miró a su padre y le dijo que sí, era suyo, a lo que el otro gritó '¡No! Que no es'.",
        ["And so, the argument continued through to the third day, with the sounds of 'Jah! 'tis so!', 'Ne! It's not!' echoing over the field, becoming more hoarse as the darkness enveloped the brothers."] = "Y así, la discusión continuó hasta el tercer día, con los sonidos de 'Jah! '¡Es así!', '¡Ne! ¡Que no es!' resonando por el campo, volviéndose más ronco a medida que la oscuridad envolvía a los hermanos.",
        ["Bah! What they needed was a good clip round the ear."] = "¡Bah! Lo que necesitaban era un buen clip alrededor de la oreja.",
        ["At the end of the third day, when the brothers lay unable to move, let alone stand, the King stood between them in shame."] = "Al final del tercer día, cuando los hermanos yacían incapaces de moverse, y mucho menos de mantenerse en pie, el Rey se interpuso entre ellos avergonzado.",
        ["As punishment for their squabbling he banished his sons from his realm, ordering that neither should return until they had conquered lands of their own."] = "Como castigo por sus disputas, desterró a sus hijos de su reino y ordenó que ninguno regresara hasta que hubieran conquistado sus propias tierras.",
        ["Jatizso set sail with a band of loyal followers, sailing into the east, while Neitiznot went west."] = "Jatizso zarpó con un grupo de seguidores leales, navegando hacia el este, mientras Neitiznot se dirigía hacia el oeste.",
        ["Jatizso ventured far into uncharted oceans, his crew dwindling as the trials of sailing and sea monsters took them."] = "Jatizso se aventuró en océanos inexplorados, y su tripulación disminuyó a medida que los llevaron las pruebas de la navegación y los monstruos marinos.",
        ["Jatizso's ship limped through the frozen wastes, in need of repairs, fighting off pirates who thought them easy pickings."] = "El barco de Jatizso cojeaba a través de los páramos helados, necesitaba reparaciones, luchando contra los piratas que pensaban que eran presa fácil.",
        ["At last a promising land was sighted, a land rich in minerals, deep fjords and sweeping mountains."] = "Por fin se avistó una tierra prometedora, una tierra rica en minerales, profundos fiordos y amplias montañas.",
        ["Jatizso claimed the land and named it after himself."] = "Jatizso reclamó la tierra y le puso su nombre.",
        ["A mighty citadel was constructed to protect his land; then Jatizso set forth to explore his new kingdom."] = "Se construyó una poderosa ciudadela para proteger su tierra; luego Jatizso partió a explorar su nuevo reino.",
        ["Crossing a few fjords, Jatizso spied an island which remained green and fertile, even at such latitude."] = "Cruzando algunos fiordos, Jatizso divisó una isla que permanecía verde y fértil, incluso a esa latitud.",
        ["With a mighty cheer Jatizso and his men marched on the island. Upon reaching the island, however, they discovered a wooden stockade."] = "Con una gran alegría, Jatizso y sus hombres marcharon hacia la isla. Al llegar a la isla, sin embargo, descubrieron una empalizada de madera.",
        ["Determined to be master of all the land, Jatizso stood in front of the gates. He looked up and demanded that those within the stockade surrendered."] = "Decidido a ser dueño de toda la tierra, Jatizso se paró frente a las puertas. Levantó la vista y exigió que los que estaban dentro de la empalizada se rindieran.",
        ["Jatizso was horrified when his brother appeared on the battlements and cried 'This is my land! Go find yer own'. To which his brother replied 'No it's not!', throwing some rocks for good measure."] = "Jatizso se horrorizó cuando su hermano apareció en las almenas y gritó '¡Esta es mi tierra! Ve a buscar el tuyo propio'. A lo que su hermano respondió '¡No, no lo es!', arrojándole algunas piedras por si acaso.",
        ["And so the blood feud continued."] = "Y así continuó la enemistad de sangre.",
        ["The fighting between the towns has continued for generations with little sign of improvement."] = "La lucha entre los pueblos ha continuado durante generaciones con pocas señales de mejora.",
        ["Quite recently a massive troll army seized one of the islands to the north, while our townships' militias were busy fighting one another."] = "Recientemente, un enorme ejército de trolls se apoderó de una de las islas del norte, mientras las milicias de nuestros municipios estaban ocupadas luchando entre sí.",
        ["They marched down and razed Neitiznot to the ground while Neitiznot's troops laid siege to Jatizso."] = "Marcharon y arrasaron Neitiznot mientras las tropas de Neitiznot sitiaban Jatizso.",
        ["The smoke damage was atrocious, I had to replace my entire wardrobe."] = "El daño del humo fue atroz, tuve que reemplazar todo mi guardarropa.",
        ["Yes, dear."] = "Sí, querido.",
        ["Anyway, a hasty sort of peace has been agreed until the trolls are dealt with."] = "De todos modos, se ha acordado una especie de paz apresurada hasta que se acabe con los trolls.",
        ["But you can still see the bitter rivalry as guards hurl insults between the towns."] = "Pero aún puedes ver la amarga rivalidad cuando los guardias lanzan insultos entre los pueblos.",
        ["Tell me more about the King of Jatizso."] = "Cuéntame más sobre el Rey de Jatizso.",
        ["Ha! Our benevolent King Gjuki Sorvott IV."] = "¡Ja! Nuestro benévolo rey Gjuki Sorvott IV.",
        ["He is short-tempered, arrogant and cares little about anything except outdoing Neitiznot's Burgher."] = "Es irascible, arrogante y le importa poco excepto superar al Burgher de Neitiznot.",
        ["He's not at all like Burgher Burowgar."] = "No se parece en nada al burgués Burowgar.",
        ["I'm surprised King Sorvott wishes to talk to you. Don't expect much in the way of gratitude."] = "Me sorprende que el rey Sorvott desee hablar contigo. No esperes mucho en términos de gratitud.",
        ["Can you ferry me to Jatizso?"] = "¿Puedes transportarme a Jatizso?",
        ["Of course."] = "Por supuesto.",
        ["I'm too busy to help your King."] = "Estoy demasiado ocupado para ayudar a tu Rey.",
        ["I\"m too busy to help your King."] = "Estoy demasiado ocupado para ayudar a tu Rey.",
        ["I guess I won't be getting paid for finding you then."] = "Supongo que entonces no me pagarán por encontrarte.",
        ["I may be back later."] = "Puede que vuelva más tarde.",
        ["Is there anything I can do for you?"] = "¿Hay algo que pueda hacer por usted?",
        ["Jatizso is a small Fremennik town, which is far less closed to the world than other Fremennik tribes."] = "Jatizso es una pequeña ciudad Fremennik, mucho menos cerrada al mundo que otras tribus Fremennik.",
        ["We maintain trade links with many powers in the world and have moved beyond some traditions to take advantage of modern advances."] = "Mantenemos vínculos comerciales con muchas potencias del mundo y hemos ido más allá de algunas tradiciones para aprovechar los avances modernos.",
        ["We do, however, continue to 'enlighten' our neighbours in Neitiznot. Unfortunately, some of the Islands are infested with trolls."] = "Sin embargo, seguimos \"iluminando\" a nuestros vecinos en Neitiznot. Desafortunadamente, algunas islas están infestadas de trolls.",
        ["We should really be trying to deal with the trolls, but the King tends to get a bit preoccupied with his cousin, the Burgher of Neitiznot."] = "Realmente deberíamos intentar lidiar con los trolls, pero el Rey tiende a preocuparse un poco por su primo, el burgués de Neitiznot.",
        ["Ha! Our benevolent King Gjuki Sorvott IV. He doesn't have much of an opinion about anyone, apart from his cousin Mawnis who rules the other Island. He hates him with a passion that can occasionally be quite scary."] = "¡Ja! Nuestro benévolo rey Gjuki Sorvott IV. No tiene mucha opinión sobre nadie, aparte de su primo Mawnis, quien gobierna la otra isla. Lo odia con una pasión que en ocasiones puede resultar bastante aterradora.",
        ["You might be able to talk to him if you help out around Jatizso. Don't expect much in the way of gratitude though."] = "Es posible que puedas hablar con él si ayudas con Jatizso. Sin embargo, no esperes mucho en términos de gratitud.",
        ["Can you ferry me to Rellekka?"] = "¿Puedes transportarme a Rellekka?",
        ["Sure."] = "Claro.",
        ["No, I'm fine right now."] = "No, estoy bien ahora.",
    },
    ["Morgan"] = {
        ["Praise Saradomin! He has brought you here to save us all!"] = "¡Alabado sea Saradomin! ¡Él te ha traído aquí para salvarnos a todos!",
        ["Wha–"] = "¿Qué?",
        ["He has guided your steps to my door, so that I may beseech you to save my village from a terrible threat!"] = "¡Él ha guiado tus pasos hasta mi puerta, para que pueda suplicarte que salves mi aldea de una terrible amenaza!",
        ["Choose an option:"] = "Elige una opción:",
        ["Why don't you save your own village?"] = "¿Por qué no salvas tu propia aldea?",
        ["What terrible threat?"] = "¿Qué terrible amenaza?",
        ["Isn't there a battle raging nearby?"] = "¿No se está librando una batalla cerca?",
        ["Well, Saradomin himself is on the battlefield, so I can't see why I should be worried for my safety. He will protect us!"] = "Bueno, el propio Saradomin está en el campo de batalla, así que no veo por qué debería preocuparme por mi seguridad. ¡Él nos protegerá!",
        ["I've brought clay rings for you."] = "Te traje anillos de arcilla.",
        ["Anything else I can do for you?"] = "¿Puedo hacer algo más por ti?",
        ["Actually you can, if you have some skill as a crafter. I hear one can have clay rings blessed to defend against foes; I could do with some of those. I'll buy as many as you can provide!"] = "En realidad puedes, si tienes alguna habilidad como artesano. He oído que se pueden bendecir anillos de arcilla para defenderse de los enemigos; Me vendrían bien algunos de esos. ¡Compraré tantos como puedas proporcionar!",
        ["Select an Option"] = "Selecciona una opción",
        ["No, you haven't. Feel free to return with one, though."] = "No, no lo has hecho. Sin embargo, siéntete libre de regresar con uno.",
        ["Ah, excellent. You can never be too careful, you know."] = "Ah, excelente. Nunca se es demasiado cuidadoso, ¿sabes?",
        ["[Morgan trades your ring for a small pile of coins, and stashes it safely away for later.]"] = "[Morgan cambia tu anillo por una pequeña pila de coins y lo guarda de forma segura para más adelante.]",
        ["May I buy all the rings you have with you?"] = "¿Puedo comprar todos los anillos que tienes contigo?",
        ["Just one."] = "Sólo uno.",
        ["All."] = "Todo.",
        ["[Morgan trades your rings for a small pile of coins, and stashes it safely away for later.]"] = "[Morgan cambia tus anillos por una pequeña pila de coins y la guarda de forma segura para más adelante.]",
        ["Right. Well, see you."] = "Correcto. Bueno, nos vemos.",
        ["I cannot thank you enough, Player. My wife and I can truly start a new life here in Draynor, now that the threat of the vampyre is gone."] = "No puedo agradecerte lo suficiente, Player. Mi esposa y yo realmente podemos comenzar una nueva vida aquí en Draynor, ahora que la amenaza del vampyre ha desaparecido.",
        ["I'm glad I could help."] = "Me alegra poder ayudar.",
        ["Next time, you're on your own!"] = "¡La próxima vez estarás solo!",
        ["Next time, you're on your own! I don't want to deal with any more vampyres."] = "¡La próxima vez estarás solo! No quiero tratar más con vampyres.",
        ["I know it was an arduous task, and we can never truly repay you."] = "Sé que fue una tarea ardua y que nunca podremos recompensarte del todo.",
        ["But I killed the vampyre... what's there to defend against?"] = "Pero maté al vampyre... ¿contra qué puedo defenderme?",
        ["Always be prepared for the worst, I say."] = "Esté siempre preparado para lo peor, digo.",
    },
    ["Moritz"] = {
        ["Welcome to NovtumberFest!"] = "¡Bienvenido a NovtumberFest!",
        ["Select an option"] = "Seleccione una opción",
        ["*(Only if not selected last:)*"] = "*(Sólo si no fue seleccionado en último lugar:)*",
        ["Who are you?"] = "¿Quién eres?",
        ["I am Moritz the glassblower!"] = "¡Soy Moritz, el soplador de vidrio!",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["What do I have to do here?"] = "¿Qué tengo que hacer aquí?",
        ["It's very simple."] = "Es muy sencillo.",
        ["Head over to the Glass Blowing Furnace and follow my lead!"] = "¡Dirígete al horno de soplado de vidrio y sigue mi ejemplo!",
        ["You will receive Crafting XP for making steins."] = "Recibirás Crafting XP por hacer jarras.",
        ["How did you become a glass blower?"] = "¿Cómo te convertiste en soplador de vidrio?",
        ["I used to play the trumpet, but apparently I am tone deaf!"] = "Solía tocar la trompeta, ¡pero aparentemente no tengo oído musical!",
        ["So... I took what experience I had from that and put it to good use."] = "Entonces... tomé la experiencia que tuve de eso y la puse en práctica.",
        ["Bye."] = "Adiós.",
        ["Keep yer wits about ye."] = "Mantén tu ingenio.",
    },
    ["Morn"] = {
        ["*(One of the following is seen every two minutes:)*"] = "*(Se ve uno de los siguientes cada dos minutos:)*",
        ["Hello! Hello. Hello!"] = "¡Hola! Hola. ¡Hola!",
        ["Hey?"] = "¿Oye?",
        ["Yes! YES! You're here! You're actually here!"] = "¡Sí! ¡SÍ! ¡Estás aquí! ¡En realidad estás aquí!",
        ["I am indeed here."] = "De hecho, estoy aquí.",
        ["You know where you need to go?"] = "¿Sabes a dónde tienes que ir?",
        ["The Spectacular Summer Skill Off."] = "La espectacular competencia de verano.",
        ["Lumbridge Crater!"] = "¡Cráter Lumbridge!",
        ["But not now."] = "Pero no ahora.",
        ["Later!"] = "¡Más tarde!",
        ["Monday!"] = "¡Lunes!",
        ["Go there on Monday!"] = "¡Ve allí el lunes!",
        ["We'll be waiting."] = "Estaremos esperando.",
        ["What just happened?"] = "¿Qué acaba de pasar?",
        ["*(Only on first time:)*"] = "*(Sólo la primera vez:)*",
        ["*(Camera centers on Morn.)*"] = "*(La cámara se centra en Morn.)*",
        ["Ladies and gentlemen, boys and girls!"] = "¡Damas y caballeros, niños y niñas!",
        ["I am delighted to welcome you to Gielinor's number one skilling based gameshow..."] = "Estoy encantado de darle la bienvenida al programa de juegos número uno basado en habilidades de Gielinor...",
        ["*(Camera zooms closer to Morn.)*"] = "*(La cámara se acerca a Morn.)*",
        ["THE SPECTACULAR!"] = "¡EL ESPECTACULAR!",
        ["SUMMER!"] = "¡VERANO!",
        ["SKILL OFF!"] = "¡HABILIDAD FUERA!",
        ["*(Camera resumes normal position.)*"] = "*(La cámara retoma su posición normal.)*",
        ["It is a concept of my own creation!"] = "¡Es un concepto de mi propia creación!",
        ["My name is Morn and I am a genius!"] = "¡Mi nombre es Morn y soy un genio!",
        ["A true genius."] = "Un verdadero genio.",
        ["And I am oh so generous."] = "Y soy muy generoso.",
        ["Six contestants have entered, one of them will leave with a pile of riches."] = "Han participado seis concursantes, uno de ellos se irá con un montón de riquezas.",
        ["My riches!"] = "¡Mis riquezas!",
        ["And they'll be able to make their wildest dreams come true."] = "Y podrán hacer realidad sus sueños más locos.",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["*(After the first time:)*"] = "*(Después de la primera vez:)*",
        ["Hello! Hello! Hello!"] = "¡Hola! ¡Hola! ¡Hola!",
        ["Select an option"] = "Seleccione una opción",
        ["How does the Skill Off work?"] = "¿Cómo funciona el Skill Off?",
        ["How does the skill off work?"] = "¿Cómo funciona la habilidad desactivada?",
        ["It's simple! Really, really simple."] = "¡Es simple! Realmente, muy simple.",
        ["Step 1."] = "Paso 1.",
        ["Gather tokens by skilling ANYWHERE in the world and bring them back to the Skill Off."] = "Reúne fichas mediante la habilidad en CUALQUIER lugar del mundo y tráelas de vuelta al Skill Off.",
        ["Step 2."] = "Paso 2.",
        ["Take the tokens to a skilling station and you'll get increased XP while skilling there."] = "Lleva las fichas a una estación de habilidades y obtendrás más XP mientras mejoras allí.",
        ["Each 100 tokens you spend there will count as a vote for that skill!"] = "¡Cada 100 tokens que gastes allí contarán como un voto para esa habilidad!",
        ["You'll gain some boosted XP in that skill while doing so."] = "Obtendrás algo de XP mejorado en esa habilidad mientras lo haces.",
        ["Step 3."] = "Paso 3.",
        ["There is no step 3. That is all you have to do."] = "No existe el paso 3. Eso es todo lo que tienes que hacer.",
        ["Step 4."] = "Paso 4.",
        ["There is also no step 4. Were you not listening?"] = "Tampoco existe el paso 4. ¿No estabas escuchando?",
        ["Step 5."] = "Paso 5.",
        ["At the end of the day the least popular skill, as in the skill with the least votes, will be eliminated from the competition."] = "Al final del día, la habilidad menos popular, así como la habilidad con menos votos, será eliminada de la competencia.",
        ["BAM!"] = "¡BAM!",
        ["GONE!"] = "¡FUERA!",
        ["OBLITERATED!"] = "¡BORRADO!",
        ["Well, not entirely."] = "Bueno, no del todo.",
        ["You'll still be able to skill there but you can't vote for it anymore so you'll miss out on that sweet, sweet boosted XP."] = "Aún podrás adquirir habilidades allí, pero ya no podrás votar por ellas, por lo que te perderás esa dulce experiencia mejorada.",
        ["So make sure to vote for your favourite skills if you want to keep them around!"] = "¡Así que asegúrate de votar por tus habilidades favoritas si quieres conservarlas!",
        ["Sounds simple enough, is that all?"] = "Suena bastante simple, ¿eso es todo?",
        ["Yes!"] = "¡Sí!",
        ["Actually no!"] = "¡En realidad no!",
        ["As skills are eliminated all of the non eliminated skills will have their XP rates increased, another reason to keep them around!"] = "A medida que se eliminan las habilidades, todas las habilidades no eliminadas aumentarán sus tasas de XP, ¡otra razón para mantenerlas disponibles!",
        ["There's also some incentives for people who take part in the voting."] = "También hay algunos incentivos para las personas que participan en la votación.",
        ["Especially for you."] = "Especialmente para ti.",
        ["Got it!"] = "¡Entendido!",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["What is the current state of the Skill Off?"] = "¿Cuál es el estado actual del Skill Off?",
        ["What's the current state of the skill off?"] = "¿Cuál es el estado actual de la habilidad?",
        ["Skills! So many skills."] = "¡Habilidades! Tantas habilidades.",
        ["*(Camera centers on Peter.)*"] = "*(La cámara se centra en Peter.)*",
        ["This is Cookie, cooking is his passion and he's not even good at that. But he's representing the Cooking still anyway!"] = "Este es Cookie, cocinar es su pasión y ni siquiera es bueno en eso. ¡Pero de todos modos sigue representando a Cooking!",
        ["We all love a tryer."] = "A todos nos encantan los que prueban.",
        ["*(After the first day:)*"] = "*(Después del primer día:)*",
        ["ELIMINATED!"] = "¡ELIMINADO!",
        ["YOU'RE OUT OF BUSINESS!"] = "¡ESTÁS FUERA DEL NEGOCIO!",
        ["*(Camera centers on Joey.)*"] = "*(La cámara se centra en Joey.)*",
        ["Baldy over here with his itty bitty cauldron is trying to represent Herblore!"] = "¡El calvo de aquí con su pequeño caldero está tratando de representar a Herblore!",
        ["Honestly, baldness is the least of his concerns."] = "Sinceramente, la calvicie es la menor de sus preocupaciones.",
        ["*(After the fourth day:)*"] = "*(Después del cuarto día:)*",
        ["BALD FOREVER!"] = "¡CALVO PARA SIEMPRE!",
        ["*(Camera centers on Gunther.)*"] = "*(La cámara se centra en Gunther.)*",
        ["Then we have Tingle on Hunter! He likes wolpertingers a little too much."] = "¡Entonces tenemos Tingle en Hunter! Le gustan demasiado los wolpertingers.",
        ["Way too much."] = "Demasiado.",
        ["*(After the second day:)*"] = "*(Después del segundo día:)*",
        ["HUNTED LIKE THE ANIMAL YOU ARE!"] = "¡CAZADO COMO EL ANIMAL QUE ERES!",
        ["*(Camera centers on Gabe.)*"] = "*(La cámara se centra en Gabe.)*",
        ["Gobbles is on Agility!"] = "¡Gobbles está en Agility!",
        ["A true friend of the animals, because no one else will be his friend."] = "Un verdadero amigo de los animales, porque nadie más será su amigo.",
        ["*(After the fifth day:)*"] = "*(Después del quinto día:)*",
        ["KILLED!"] = "¡MATADO!",
        ["Not literally."] = "No literalmente.",
        ["*(Camera centers on the Dungeoneering hole.)*"] = "*(La cámara se centra en el agujero Dungeoneering.)*",
        ["This is a big hole. You should jump in it. I'm 90% sure you can Dungeoneer down there."] = "Este es un gran agujero. Deberías saltar dentro de él. Estoy 90% seguro de que puedes hacer Dungeoneer allí abajo.",
        ["*(Camera centers on Eva.)*"] = "*(La cámara se centra en Eva.)*",
        ["And finally we have this massive nerd on Runecrafting!"] = "¡Y finalmente tenemos a este enorme nerd en Runecrafting!",
        ["Maybe she could be friends with Gabe."] = "Quizás podría ser amiga de Gabe.",
        ["*(After the third day:)*"] = "*(Después del tercer día:)*",
        ["Thanks for the run down."] = "Gracias por el resumen.",
        ["Are there any rewards I can earn?"] = "¿Hay alguna recompensa que pueda ganar?",
        ["Are there any special rewards for contributing?"] = "¿Hay alguna recompensa especial por contribuir?",
        ["Why, yes! Yes there are! I am so glad you asked!"] = "¡Pues sí! ¡Sí las hay! ¡Me alegra mucho que hayas preguntado!",
        ["*(Camera centers on Randall.)*"] = "*(La cámara se centra en Randall.)*",
        ["Have you seen this sword!?"] = "¿¡Has visto esta espada!?",
        ["Isn't it fantastic?"] = "¿No es fantástico?",
        ["Aren't you amazed?"] = "¿No te sorprende?",
        ["It looks kind of sinister."] = "Parece un poco siniestro.",
        ["Yes! yes! So very sinister!"] = "¡Sí! ¡Sí! ¡Qué siniestro!",
        ["But best of all..."] = "Pero lo mejor de todo...",
        ["It wants you to have it."] = "Quiere que lo tengas.",
        ["Wait, what?"] = "Espera, ¿qué?",
        ["I said, I want you to have it."] = "Dije, quiero que lo tengas.",
        ["But I can't just give it to you."] = "Pero no puedo dártelo simplemente.",
        ["That would be suspicious, far too suspicious."] = "Eso sería sospechoso, demasiado sospechoso.",
        ["You're going to have to earn it."] = "Tendrás que ganártelo.",
        ["Why are you telling me this?"] = "¿Por qué me cuentas esto?",
        ["Because we're friends!"] = "¡Porque somos amigos!",
        ["The best of friends!"] = "¡Los mejores amigos!",
        ["Right..."] = "Cierto...",
        ["*(Camera pans to the snack yak.)*"] = "*(La cámara se desplaza hacia el snack yak.)*",
        ["What about the snack yak?"] = "¿Qué pasa con el snack yak?",
        ["The snack yak!"] = "¡La merienda yak!",
        ["It looks pretty adorable!"] = "¡Se ve muy adorable!",
        ["Yes! Such a majestic beast covered in delectable delicacies!"] = "¡Sí! ¡Qué bestia tan majestuosa cubierta de delicias deliciosas!",
        ["Just look how fluffy it is!"] = "¡Mira lo esponjoso que es!",
        ["So cute and cuddly!"] = "¡Qué lindo y tierno!",
        ["*(Camera pans slowly back to Randall.)*"] = "*(La cámara se desplaza lentamente hacia Randall.)*",
        ["It's so sharp..."] = "Es tan nítido...",
        ["Sharp?"] = "¿Afilado?",
        ["So powerful..."] = "Tan poderoso...",
        ["Let him in."] = "Déjalo entrar.",
        ["Let the yak in?"] = "¿Dejar entrar al yak?",
        ["The yak!"] = "¡El yak!",
        ["Yes, the yak."] = "Sí, el yak.",
        ["Let the yak in!"] = "¡Deja entrar al yak!",
        ["Where did you get that outfit?"] = "¿De dónde sacaste ese traje?",
        ["Where did you get that creepy jester outfit?"] = "¿De dónde sacaste ese espeluznante disfraz de bufón?",
        ["Creepy?"] = "¿Espeluznante?",
        ["Not creepy!"] = "¡No es espeluznante!",
        ["Stylish, desirable, fantabulous, maybe?"] = "¿Elegante, deseable, fantástico, tal vez?",
        ["Where did you get it?"] = "¿De dónde lo conseguiste?",
        ["Solomon and his store!"] = "¡Solomon y su tienda!",
        ["So many wares, this one's the best."] = "Tantos productos, este es el mejor.",
        ["Alright. Thank you! I'll check it out I guess."] = "Muy bien. ¡Gracias! Lo comprobaré, supongo.",
        ["Goodbye"] = "Adiós",
        ["Goodbye!"] = "¡Adiós!",
        ["Don't be a stranger!"] = "¡No seas un extraño!",
        ["I won't!"] = "¡No lo haré!",
        ["You better not."] = "Será mejor que no.",
        ["You do not have anything to hand in."] = "No tienes nada que entregar.",
        ["Warning"] = "Advertencia",
        ["If you want to make event progress and gain XP at the same time <span style=\"color: red;\">you should use your skill tokens at a skilling station!</span> However, you can hand in skill tokens here if you are only interested in the cosmetic rewards."] = "Si quieres progresar en el evento y ganar XP al mismo tiempo <span style=\"color: red;\">, ¡debes usar tus fichas de habilidad en una estación de habilidades! </span> Sin embargo, puedes entregar fichas de habilidad aquí si solo estás interesado en las recompensas cosméticas.",
        ["Do you wish to continue?"] = "¿Quieres continuar?",
        ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
        ["Yes"] = "si",
        ["You hand in [number] Skill off tokens. You need to hand in [number]K more to complete the event."] = "Entregas fichas de habilidad [número]. Debes entregar [número]K más para completar el evento.",
        ["*(If rewards weren't unlocked, and no rewards have been unlocked previously:)*"] = "*(Si las recompensas no se desbloquearon y no se han desbloqueado recompensas anteriormente:)*",
        ["You need to bring me more skill tokens if you want to claim more rewards."] = "Debes traerme más fichas de habilidad si quieres reclamar más recompensas.",
        ["*(If rewards were unlocked:)*"] = "*(Si las recompensas estuvieran desbloqueadas:)*",
        ["*(Without space for the rewards:)*"] = "*(Sin espacio para las recompensas :)*",
        ["You do not have enough inventory space for some of the rewards. Please make some space and try again."] = "No tienes suficiente espacio en el inventario para algunas de las recompensas. Por favor, deja algo de espacio e inténtalo de nuevo.",
        ["*(With space for the rewards:)*"] = "*(Con espacio para las recompensas :)*",
        ["*(If a big event mystery box is rewarded:)*"] = "*(Si se recompensa con una caja misteriosa de gran evento:)*",
        ["Congratulations, you have unlocked the Big Event mystery box."] = "Felicitaciones, has desbloqueado la caja misteriosa del Gran Evento.",
        ["*(If Blightreaver is rewarded:)*"] = "*(Si Blightreaver es recompensado:)*",
        ["Congratulations, you have unlocked the Blightreaver override. You can find this in the customisations interface."] = "Felicitaciones, has desbloqueado la anulación de Blightreaver. Puede encontrar esto en la interfaz de personalizaciones.",
        ["*(If the snack yak is rewarded:)*"] = "*(Si el snack yak es recompensado :)*",
        ["Congratulations, you have unlocked the Snack Yak. You can find this in the pet interface."] = "Felicitaciones, has desbloqueado el Snack Yak. Puedes encontrar esto en la interfaz de mascotas.",
        ["There you are!"] = "¡Ahí estás!",
        ["*(If some of the rewards have been unlocked:)*"] = "*(Si algunas de las recompensas han sido desbloqueadas:)*",
        ["You have unlocked [number]/4 of the rewards for the Spectacular Summer Skill Off event."] = "Has desbloqueado [número]/4 de las recompensas del evento Spectacular Summer Skill Off.",
        ["*(If there are still rewards to unlock, and none were just claimed:)*"] = "*(Si aún quedan recompensas por desbloquear y no se acaba de reclamar ninguna:)*",
        ["We have more rewards to offer, should you bring me more skill tokens."] = "Tenemos más recompensas que ofrecer, si me traes más fichas de habilidad.",
        ["You have unlocked all of the rewards available for this event. You can convert any remaining currency into consumable rewards."] = "Has desbloqueado todas las recompensas disponibles para este evento. Puedes convertir cualquier moneda restante en recompensas consumibles.",
        ["You can't kill Morn, he is our friend, he's here to help us."] = "No puedes matar a Morn, él es nuestro amigo, está aquí para ayudarnos.",
        ["Congratulations, you have unlocked the [reward]."] = "Felicitaciones, ha desbloqueado el [reward].",
        ["You have unlocked all of the rewards available for this event. You can use any remaining skill tokens at the skilling stations or convert them into mystery boxes."] = "Has desbloqueado todas las recompensas disponibles para este evento. Puedes usar las fichas de habilidad restantes en las estaciones de habilidades o convertirlas en cajas misteriosas.",
        ["You have already claimed all the rewards we have to offer."] = "Ya has reclamado todas las recompensas que tenemos para ofrecer.",
        ["The event is all over now!"] = "¡El evento ya terminó!",
        ["*(Before the game update on 5 August:)*"] = "*(Antes de la actualización del juego el 5 de agosto:)*",
        ["Dungeoneering is the winner!"] = "¡Dungeoneering es el ganador!",
        ["*(After the game update on 5 August:)*"] = "*(Después de la actualización del juego el 5 de agosto:)*",
        ["Agility is the winner!"] = "¡Agility es el ganador!",
        ["You can still hand in any leftover tokens to me or convert them to mystery boxes."] = "Aún puedes entregarme las fichas sobrantes o convertirlas en cajas misteriosas.",
        ["Yes... Yes..."] = "Sí... Sí...",
        ["*(As during the event.)*"] = "*(Como durante el evento.)*",
        ["*(One of the following is seen occasionally, and then continues below:)*"] = "*(Uno de los siguientes se ve ocasionalmente y luego continúa a continuación:)*",
        ["*(Only on first time.)*"] = "*(Sólo la primera vez.)*",
        ["Morn? Shouldn't you be the host?"] = "¿Morn? ¿No deberías ser el anfitrión?",
        ["Hello! Hello! Hello."] = "¡Hola! ¡Hola! Hola.",
        ["We're going to have so much fun."] = "Nos divertiremos mucho.",
        ["This is Morn. He was the host of the Summer Skill Off but this time he has decided to take part himself."] = "Este es Morn. Fue el anfitrión del Summer Skill Off pero esta vez decidió participar él mismo.",
        ["You feel like something is very very wrong."] = "Sientes que algo anda muy, muy mal.",
        ["*(After the first time.)*"] = "*(Después de la primera vez.)*",
        ["Tee hee hee."] = "Je, ji, ji.",
        ["What do I have to do here?"] = "¿Qué tengo que hacer aquí?",
        ["What am I supposed to be doing here?"] = "¿Qué se supone que debo hacer aquí?",
        ["Tee hee hee!"] = "¡Je, ji, ji!",
        ["AHEM!"] = "¡Ejem!",
        ["World Guardian! Thank the gods you're here!"] = "¡Guardián Mundial! ¡Gracias a los dioses que estás aquí!",
        ["Some MYSTERIOUS portals have opened behind me and there are DEMONS pouring out into the crater!"] = "¡Algunos portales MISTERIOSOS se han abierto detrás de mí y hay DEMONIOS saliendo del cráter!",
        ["Huh, that's strange."] = "Eh, eso es extraño.",
        ["Strange? Maybe."] = "¿Extraño? Tal vez.",
        ["But they'll bring DEATH!"] = "¡Pero traerán la MUERTE!",
        ["And DESTRUCTION!"] = "¡Y DESTRUCCIÓN!",
        ["I ask you to think of the children."] = "Les pido que piensen en los niños.",
        ["Why won't you think of the children!?"] = "¿¡Por qué no piensas en los niños!?",
        ["Morn, did you open these portals?"] = "Morn, ¿abriste estos portales?",
        ["YES!"] = "¡SÍ!",
        ["I re-"] = "Re-",
        ["No! This is no time for idle chit chat!"] = "¡No! ¡Este no es momento para charlas ociosas!",
        ["The people need a hero!"] = "¡La gente necesita un héroe!",
        ["A hero who can cut down these hideous creatures!"] = "¡Un héroe que puede acabar con estas horribles criaturas!",
        ["You mean me right?"] = "Te refieres a mí, ¿verdad?",
        ["You can either slay demons from the left portal with melee attacks."] = "Puedes matar demonios desde el portal izquierdo con ataques cuerpo a cuerpo.",
        ["Or you can slay demons from the right portal with magic."] = "O puedes matar demonios desde el portal correcto con magia.",
        ["Matching Morn's suggestions will grant increased XP while skilling at this location!"] = "¡Hacer coincidir las sugerencias de Morn otorgará más XP mientras practicas en esta ubicación!",
        ["What is wrong with this guy?"] = "¿Qué le pasa a este tipo?",
        ["Why are you taking part in the Winter Chill Off?"] = "¿Por qué participas en el Winter Chill Off?",
        ["Why are you taking part in the Chill Off?"] = "¿Por qué participas en el Chill Off?",
        ["Isn't that a conflict of interest?"] = "¿No es eso un conflicto de intereses?",
        ["No!"] = "¡No!",
        ["Not at all!"] = "¡Para nada!",
        ["I'm giving the people what they want!"] = "¡Le estoy dando a la gente lo que quiere!",
        ["DEMONS!"] = "¡DEMONIOS!",
        ["The people want demons?"] = "¿La gente quiere demonios?",
        ["The people want EXCITEMENT!"] = "¡La gente quiere EMOCIÓN!",
        ["The people want KILLING!"] = "¡La gente quiere MATAR!",
        ["The people want BLOOD!"] = "¡La gente quiere SANGRE!",
        ["I'm not s-"] = "No soy s-",
        ["And you know what's really good at killing things?"] = "¿Y sabes qué es realmente bueno para matar cosas?",
        ["Blightreaver."] = "Atraca plagas.",
        ["How did you know!?"] = "¿¡Cómo lo supiste!?",
        ["I didn't say anything, that was y-"] = "No dije nada, ese fuiste tú-",
        ["And do you know why Blightreaver is so effective?"] = "¿Y sabes por qué Blightreaver es tan efectivo?",
        ["Morn is staring at you expectantly."] = "Morn te mira expectante.",
        ["Uh..."] = "Eh...",
        ["Oh World Guardian, I had such high expectations.."] = "Oh, World Guardian, tenía expectativas tan altas...",
        ["You've disappointed me."] = "Me has decepcionado.",
        ["You've disappointed everyone."] = "Has decepcionado a todos.",
        ["What are you talking about?"] = "¿De qué estás hablando?",
        ["Don't worry!"] = "¡No te preocupes!",
        ["You may not know but I know some people that do!"] = "Puede que no lo sepas, ¡pero conozco a algunas personas que sí lo saben!",
        ["I ask again!"] = "¡Pregunto de nuevo!",
        ["Do you know why Blightreaver is so effective!?"] = "¿¡Sabes por qué Blightreaver es tan efectivo!?",
        ["Morn looks around."] = "Morn mira a su alrededor.",
        ["ALL TOGETHER NOW!"] = "¡TODOS JUNTOS AHORA!",
        ["BECAUSE IT FEEDS ON THE BLOOD OF ITS ENEMIES!"] = "¡PORQUE SE ALIMENTA DE LA SANGRE DE SUS ENEMIGOS!",
        ["Well done everyone!"] = "¡Bien hecho a todos!",
        ["I knew I could always count on my fools!"] = "¡Sabía que siempre podría contar con mis tontos!",
        ["Who is he talking to?"] = "¿Con quién está hablando?",
        ["What happened to the winner of the Summer Skill Off?"] = "¿Qué pasó con el ganador del Summer Skill Off?",
        ["Oh!"] = "¡Oh!",
        ["Oh."] = "Ah.",
        ["He wanted to be set free!"] = "¡Quería ser liberado!",
        ["Free?"] = "¿Gratis?",
        ["Free from what exactly?"] = "¿Libre de qué exactamente?",
        ["Everything!"] = "¡Todo!",
        ["Every."] = "Cada.",
        ["Thing."] = "Cosa.",
        ["Everything?"] = "¿Todo?",
        ["I offered to grant his greatest wish!"] = "¡Me ofrecí a concederle su mayor deseo!",
        ["His hearts desire."] = "El deseo de su corazón.",
        ["Riches!"] = "¡Riquezas!",
        ["Popularity!"] = "¡Popularidad!",
        ["But in the end he chose freedom."] = "Pero al final eligió la libertad.",
        ["He begged for freedom!"] = "¡Rogó por la libertad!",
        ["Oh, how he begged."] = "Oh, cómo suplicó.",
        ["Goodbye."] = "Adiós.",
        ["Bye Morn!"] = "¡Adiós Morn!",
        ["I'll be waiting."] = "Estaré esperando.",
    },
    ["Mort'ton local"] = {
        ["Oh...thank you for using this serum on me. Here, have something for your trouble."] = "Oh... gracias por usar este suero en mí. Toma, ten algo para tu problema.",
        ["*The local gives you some [item].*"] = "*El local te regala algo de [item].*",
        ["Oh...thank you, you used the permanent serum on me. Here, have something for your trouble."] = "Oh... gracias, usaste el suero permanente conmigo. Toma, ten algo para tu problema.",
        ["Oh, I feel much better for that super serum. I really hate it when I'm afflicted!"] = "Oh, me siento mucho mejor con ese súper suero. ¡Realmente odio cuando estoy afligido!",
    },
    ["Morten Holdstrom"] = {
        ["Good day to you."] = "Buenos días para ti.",
        ["Hello. What are you up to?"] = "Hola. ¿Qué estás haciendo?",
        ["Ah, today is a surströmming day! The herring I buried six months ago is ready to be dug up."] = "¡Ah, hoy es un día de surströmming! El arenque que enterré hace seis meses está listo para ser desenterrado.",
        ["Eughr! What are you going to do with it?"] = "¡Euf! ¿Qué vas a hacer con eso?",
        ["Eat it, of course! It will be fermented just-right by now."] = "¡Cómelo, por supuesto! A estas alturas ya estará fermentado en su punto perfecto.",
        ["Fermented? You eat rotten fish?"] = "¿Fermentado? ¿Comes pescado podrido?",
        ["Hmmm, tasty. I'm guessing you don't want to come round and try it?"] = "Mmmm, sabroso. ¿Supongo que no querrás venir y probarlo?",
        ["You guess correctly."] = "Adivinas correctamente.",
    },
    ["Morvran"] = {
        ["What do you want?"] = "¿Qué quieres?",
        ["Select an Option"] = "Selecciona una opción",
        ["Can we talk about assignments?"] = "¿Podemos hablar de asignaciones?",
        ["I suppose we can. What do you want to ask about?"] = "Supongo que podemos. ¿Qué quieres preguntar?",
        ["Choose an option:"] = "Elige una opción:",
        ["About your challenge..."] = "Acerca de tu desafío...",
        ["Hmmm. Let's see how you are progressing."] = "Mmmm. A ver cómo vas progresando.",
        ["You need to kill the following bosses while carrying all cumulatively dropped dark crystals: Giant Mole (hard mode), Kalphite Queen, Dagannoth Kings, King Black Dragon, Queen Black Dragon, Kree'arra, Commander Zilyana, K'ril Tsutsaroth, General Graador and Araxxi."] = "Debes matar a los siguientes jefes mientras llevas todos los cristales oscuros acumulados: Topo gigante (modo difícil), Kalphite Queen, Dagannoth Kings, King Black Dragon, Queen Black Dragon, Kree'arra, Commander Zilyana, K'ril Tsutsaroth, General Graador y Araxxi.",
        ["If you wish to concede defeat, tell me now, and I'll let you off the hook."] = "Si deseas admitir la derrota, dímelo ahora y te liberaré.",
        ["And seeing how I'm so nice, there won't even be a penalty, only the shame that comes from giving up so easily."] = "Y viendo lo amable que soy, ni siquiera habrá penalización, sólo la vergüenza que supone rendirse tan fácilmente.",
        ["1. Yes - cancel."] = "1. Sí, cancelar.",
        ["It is done. You are free to request another assignment of me...once you feel up to it."] = "Ya está. Eres libre de solicitarme otra tarea... una vez que te sientas capaz de hacerlo.",
        ["2. No - keep it."] = "2. No, guárdalo.",
        ["I need another assignment."] = "Necesito otra tarea.",
        ["Sorry, but you're not strong enough to be taught by me. Get stronger. Your best trainer would be [slayer master] in [location]."] = "Lo siento, pero no eres lo suficientemente fuerte para que yo te enseñe. Hazte más fuerte. Tu mejor trainer sería [slayer master] en [location].",
        ["You need to be at least level 120 in Combat and level 85 in Slayer to train under this Slayer Master."] = "Debes tener al menos el nivel 120 en Combate y el nivel 85 en Slayer para entrenar con este Slayer Master.",
        ["You're already on a perfectly good assignment. What more do you want?"] = "Ya estás en una tarea perfectamente buena. ¿Qué más quieres?",
        ["You're still hunting [assigned monster]; come back when you've finished your task."] = "Todavía estás cazando a [assigned monster]; Vuelve cuando hayas terminado tu tarea.",
        ["You still need to complete my challenge before I can give you another assignment."] = "Aún debes completar mi desafío antes de que pueda asignarte otra tarea.",
        ["What did you want me to do again?"] = "¿Qué querías que hiciera otra vez?",
        ["I require you to gather ten dark crystals from various famous monsters. In order for their corruption to show, you must do this alone."] = "Necesito que reúnas diez cristales oscuros de varios monstruos famosos. Para que su corrupción se muestre, debes hacerlo solo.",
        ["How would you like a special challenge this time, instead of a regular assignment?"] = "¿Te gustaría un desafío especial esta vez, en lugar de una tarea normal?",
        ["Very well, I accept your challenge."] = "Muy bien, acepto tu desafío.",
        ["Very good."] = "Muy bien.",
        ["No thanks. I'd prefer a regular assignment instead."] = "No gracias. Preferiría una tarea regular.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["No and please don't ask me again."] = "No y por favor no me vuelvas a preguntar.",
        ["Do you have any special assignments for me?"] = "¿Tienes alguna tarea especial para mí?",
        ["*(Returns to previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["You're already doing a special challenge for me. What more do you want?"] = "Ya estás haciendo un desafío especial para mí. ¿Qué más quieres?",
        ["*(Returns to initial options)*"] = "*(Vuelve a las opciones iniciales)*",
        ["I do have a special challenge I've been saving for more able students...but perhaps you could use some of your slayer points to persuade me."] = "Tengo un desafío especial que he estado reservando para estudiantes más capaces... pero tal vez podrías usar algunos de tus puntos de cazador para persuadirme.",
        ["I've heard tell that some small fragments of Seren have found their way into areas of great conflict.  I fear this conflict might corrupt those shards."] = "He oído decir que algunos pequeños fragmentos de Seren han llegado a zonas de gran conflicto.  Temo que este conflicto pueda corromper esos fragmentos.",
        ["I'd like for you to retrieve them, so they might properly be cleansed by Clan Hefin."] = "Me gustaría que los recuperaras para que el Clan Hefin pueda limpiarlos adecuadamente.",
        ["What do you mean by great conflict?"] = "¿Qué quieres decir con gran conflicto?",
        ["They are in the midst of some so-called 'famous' monsters.  I wish for you to slay them, retrieve these fragments and return them to me."] = "Están en medio de algunos de los llamados monstruos \"famosos\".  Deseo que los mates, recuperes estos fragmentos y me los devuelvas.",
        ["The beasts in question are Falador's giant mole, the Kalphite Queen, King and Queen Black Dragons, the three Dagannoth Kings, the four God Wars Dungeon generals and, finally,  Araxxi."] = "Las bestias en cuestión son el topo gigante de Falador, el Kalphite Queen, el Rey y la Reina Black Dragons, los tres Reyes Dagannoth, los cuatro generales de God Wars Dungeon y, finalmente, Araxxi.",
        ["This will not be as simple as it sounds, however.  These fragments will have become corrupted by so much nearby bloodshed, and will likely impart negative effects upon you."] = "Sin embargo, esto no será tan simple como parece.  Estos fragmentos se habrán corrompido por tanto derramamiento de sangre cercano y probablemente te causarán efectos negativos.",
        ["And you need to carry all of these 'dark crystals' that you find inorder to coax out more."] = "Y necesitas llevar todos estos \"cristales oscuros\" que encuentres para poder sacar más.",
        ["You can take this challenge right now in exchange for 100 slayer points.  Or I could give you a regular assignment.  It's up to you."] = "Puedes aceptar este desafío ahora mismo a cambio de 100 puntos de cazador.  O podría darte una tarea regular.  Tu decides.",
        ["1. I accept your challenge (100 slayer points)"] = "1. Acepto tu desafío (100 puntos de cazadora)",
        ["2. I want a regular assignment instead."] = "2. En lugar de eso, quiero una tarea regular.",
        ["3. I need some time to think about this."] = "3. Necesito algo de tiempo para pensar en esto.",
        ["*(Returns to previous-to-previous options)*"] = "*(Vuelve a las opciones anteriores a anteriores)*",
        ["Can we talk about items and incentives?"] = "¿Podemos hablar de artículos e incentivos?",
        ["Well, which is it? Items for sale or incentives?"] = "Bueno, ¿cuál es? ¿Artículos en venta o incentivos?",
        ["Let's talk items."] = "Hablemos de elementos.",
        ["I have plenty of slayer equipment - take a look."] = "Tengo mucho equipo de cazadora. Échale un vistazo.",
        ["*(Slayer Equipment interface opens)*"] = "*(Se abre la interfaz del equipo Slayer)*",
        ["Let's talk incentives."] = "Hablemos de incentivos.",
        ["View rewards"] = "Ver recompensas",
        ["*(Slayer Rewards interface opens)*"] = "*(Se abre la interfaz de recompensas Slayer)*",
        ["How do I earn co-op points to spend on rewards?"] = "¿Cómo gano puntos cooperativos para gastarlos en recompensas?",
        ["You'll gain co-op points if you complete at least half of your contribution to a task with a friend. That means you need to be in a group for most of the time you're working on your task, but it doesn't matter if your friend beats you to the majority of kills! You'll still have been in a group for most of your contribution, so you're still entitled to a co-op reward point."] = "Obtendrás puntos cooperativos si completas al menos la mitad de tu contribución a una tarea con un amigo. Eso significa que debes estar en un grupo la mayor parte del tiempo que estás trabajando en tu tarea, ¡pero no importa si tu amigo te gana en la mayoría de las muertes! Aún habrás estado en un grupo durante la mayor parte de tu contribución, por lo que aún tendrás derecho a un punto de recompensa cooperativa.",
        ["Where can I use the co-op food and potion rewards?"] = "¿Dónde puedo usar las recompensas cooperativas de comida y pociones?",
        ["*(Same as below)*"] = "*(Igual que a continuación)*",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["The rewards can be used in most of the areas we commonly send you to complete your tasks."] = "Las recompensas se pueden usar en la mayoría de las áreas que comúnmente te enviamos para completar tus tareas.",
        ["*(Same as above)*"] = "*(Igual que arriba)*",
        ["Do you have any other rewards?"] = "¿Tienes otras recompensas?",
        ["For my more able students, I have a special challenge that I offer, and there are some small rewards - besides the glory - that I offer for completing it. Each time you complete the challenge, I will pay for a free retune of the Max Guild portals - although I won't pay for more than 30 in advance. I will also allow you to carry special black crystals which have a debilitating effect on you, to make your slaying more challenging."] = "Para mis estudiantes más capaces, tengo un desafío especial que ofrezco, y hay algunas pequeñas recompensas, además de la gloria, que ofrezco por completarlo. Cada vez que completes el desafío, pagaré por una nueva sintonización gratuita de los portales del Gremio Max, aunque no pagaré más de 30 por adelantado. También te permitiré llevar cristales negros especiales que tienen un efecto debilitante sobre ti, para que tu asesinato sea más desafiante.",
        ["What are black crystals?"] = "¿Qué son los cristales negros?",
        ["Black crystals are corrupted crystals that have resisted our attempts to cleanse them. The corruption is too strong. Like the dark crystals, they have debilitating effects when carried. Some of my braver students have taken to carrying some to make their slaying more challengeing. I allow people to carry them only if they have proved their worth by completing my challenge."] = "Los cristales negros son cristales corruptos que han resistido nuestros intentos de limpiarlos. La corrupción es demasiado fuerte. Al igual que los cristales oscuros, cuando se transportan tienen efectos debilitantes. Algunos de mis alumnos más valientes han empezado a llevar algunos para que su asesinato sea más desafiante. Permito que las personas los lleven solo si han demostrado su valía al completar mi desafío.",
        ["Is there any benefit to carrying them?"] = "¿Tiene algún beneficio llevarlos?",
        ["There is no material reward. But, the glory! The challenge! Are these not good enough for you?"] = "No hay recompensa material. Pero ¡la gloria! ¡El desafío! ¿No son estos lo suficientemente buenos para ti?",
        ["Talk about something else."] = "Habla de otra cosa.",
        ["Let's talk about you."] = "Hablemos de ti.",
        ["My favourite subject. What do you want to know?"] = "Mi tema favorito. ¿Qué quieres saber?",
        ["Tell me more about your background."] = "Cuéntame más sobre tus antecedentes.",
        ["I am Lord Iorwerth's nephew. The old Lord Iorwerth, that is. I was raised as a leader in our clan. I looked up to my uncle; it was he who appointed me as our clan's Head of Intelligence."] = "Soy el sobrino de Lord Iorwerth. El viejo Lord Iorwerth, claro está. Me criaron como líder de nuestro clan. Admiraba a mi tío; Fue él quien me nombró Jefe de Inteligencia de nuestro clan.",
        ["It was my duty to amass knowledge of our enemies - their strengths and weaknesses - and how best to defeat them."] = "Era mi deber acumular conocimientos sobre nuestros enemigos (sus fortalezas y debilidades) y la mejor manera de derrotarlos.",
        ["I was also in charge of interrogations and assassinations."] = "También estuve a cargo de interrogatorios y asesinatos.",
        ["How did you become a slayer master?"] = "¿Cómo te convertiste en slayer master?",
        ["My duties gave me cause to travel far beyond the borders of Tirannwn, though always in disguise of course."] = "Mis deberes me dieron motivo para viajar mucho más allá de las fronteras de Tirannwn, aunque siempre disfrazado, por supuesto.",
        ["In my travels, I made the acquaintance of a lovely young lady by the name of Kuradal."] = "En mis viajes, conocí a una encantadora joven llamada Kuradal.",
        ["She taught me much about the wider world, and I her about the many mysteries of this world closed off to her."] = "Ella me enseñó mucho sobre el mundo en general, y yo le aprendí sobre los muchos misterios de este mundo cerrado para ella.",
        ["She is a remarkable woman. I found myself fascinated by her and what she does, and so I decided to turn my talents and knowledge towards slaying."] = "Es una mujer extraordinaria. Me sentí fascinado por ella y lo que hace, y por eso decidí dedicar mis talentos y conocimientos a la matanza.",
        ["We have to find our place again among the other clans. Some of us still begrudge how things played out, but I intend to embrace this change."] = "Tenemos que encontrar nuestro lugar nuevamente entre los otros clanes. Algunos de nosotros todavía lamentamos cómo se desarrollaron las cosas, pero tengo la intención de aceptar este cambio.",
        ["My own knowledge of slaying has now surpassed even Kuradal's...theoretically speaking, of course. She is more suited to practical application..."] = "Mi propio conocimiento sobre matar ahora ha superado incluso el de Kuradal... teóricamente hablando, por supuesto. Ella es más adecuada para aplicaciones prácticas...",
        ["Only theoretically?"] = "¿Solo en teoría?",
        ["Oh, I could easily kill any beast if I so desired. I've certainly done plenty of it in my time...but there are always others willing to do the dirty work. I prefer to watch these days - to study and learn."] = "Oh, podría matar fácilmente a cualquier bestia si así lo deseara. Ciertamente he hecho mucho en mi tiempo... pero siempre hay otros dispuestos a hacer el trabajo sucio. Prefiero mirar estos días, estudiar y aprender.",
        ["Despite what you may think of the Iorwerth, I feel there has been enough blood spilled during the civil war. I have always preferred to only kill when absolutely necessary."] = "A pesar de lo que puedas pensar de Iorwerth, creo que ya se ha derramado suficiente sangre durante la guerra civil. Siempre he preferido matar sólo cuando sea absolutamente necesario.",
        ["About Clan Iorwerth..."] = "Acerca del Clan Iorwerth...",
        ["Look, I was never a fan of that whole Dark Lord business. I have my own interests, and I am still able to indulge them."] = "Mira, nunca fui fanático de todo ese asunto del Señor Oscuro. Tengo mis propios intereses y todavía puedo satisfacerlos.",
        ["But as an Iorwerth, I am duty-bound to my lord. We take duty seriously, something the other clans are less concerned over."] = "Pero como Iorwerth, tengo un deber para con mi señor. Nos tomamos el deber en serio, algo que a los demás clanes les preocupa menos.",
        ["So you were just following orders? Like that's a justification."] = "¿Entonces solo estabas siguiendo órdenes? Como si eso fuera una justificación.",
        ["I cannot speak for the actions of others, but I always ensured that my own actions - my orders - were just."] = "No puedo hablar por las acciones de los demás, pero siempre me aseguré de que mis propias acciones (mis órdenes) fueran justas.",
        ["Within any war, each individual must draw their own lines. I can hold my head high knowing I remained true to my beliefs."] = "Dentro de cualquier guerra, cada individuo debe trazar sus propias líneas. Puedo mantener la cabeza en alto sabiendo que me mantuve fiel a mis creencias.",
        ["Weren't you an assassin and interrogator?"] = "¿No eras asesino e interrogador?",
        ["Wars require both. All of my targets were of military value, never civilians or innocents, and I never once resorted to the use of torture."] = "Las guerras requieren ambos. Todos mis objetivos eran de valor militar, nunca civiles o inocentes, y nunca recurrí al uso de la tortura.",
        ["Again, I can only be held accountable for my own actions, not those of others."] = "Nuevamente, solo puedo ser responsable de mis propias acciones, no de las de los demás.",
        ["Do you think a massacre is justifiable?"] = "¿Crees que una masacre es justificable?",
        ["No, of course not, and I am glad that you put a stop to it."] = "No, por supuesto que no, y me alegra que hayas puesto fin a esto.",
        ["Don't paint all Iorwerth with the same brush simply due to the actions of my uncle. He was wrong, that much is clear, and we must now find a way to once more live among our brethren."] = "No pintes todo Iorwerth con el mismo pincel simplemente por las acciones de mi tío. Se equivocó, eso está claro, y ahora debemos encontrar la manera de vivir una vez más entre nuestros hermanos.",
        ["There is need of someone such as I to ensure the safety of all the clans, the Clan Iorwerth needs a leader with a more... palatable outlook."] = "Se necesita alguien como yo para garantizar la seguridad de todos los clanes, el Clan Iorwerth necesita un líder con una perspectiva más... agradable.",
        ["This is why I have waived my right of lordship over to lestin. He is an unconventional choice, but a necessary one."] = "Es por eso que he renunciado a mi derecho de señorío sobre Lestin. Es una elección poco convencional, pero necesaria.",
        ["Some of the older Iorwerth diehards are having a hard time accepting him, but I will keep them in line. They respect me, and for as long as I support Iestin, they will follow his lead, or they will not be welcome here."] = "Algunos de los más antiguos y acérrimos de Iorwerth están teniendo dificultades para aceptarlo, pero los mantendré a raya. Me respetan y mientras yo apoye a Iestin, seguirán su ejemplo o no serán bienvenidos aquí.",
        ["So what's in this dungeon then?"] = "Entonces, ¿qué hay en esta mazmorra?",
        ["Since the regrowing of Prifddinas, I've tasked the lovely Kuradal to supply me with creatures for my...collection."] = "Desde que Prifddinas volvió a crecer, le he encargado al encantador Kuradal que me proporcione criaturas para mi... colección.",
        ["To what end?"] = "¿Con qué fin?",
        ["A challenge, but only for the most elite of slayers!"] = "¡Un desafío, pero solo para los cazadores más selectos!",
        ["Can I go in there?"] = "¿Puedo entrar ahí?",
        ["No. You are not worthy of my time."] = "No. No eres digno de mi tiempo.",
        ["You require 85 Slayer to access Morvran's arena."] = "Necesitas 85 Slayer para acceder a la arena de Morvran.",
        ["Yes. I'll enjoy watching you fight...but don't bore me or I might reconsider."] = "Sí. Disfrutaré viéndote pelear... pero no me aburras o podría reconsiderarlo.",
        ["So, what's the challenge?"] = "Entonces, ¿cuál es el desafío?",
        ["I'll throw a series of creatures in with you each round; you have ten minutes to complete as many rounds as you can."] = "Te arrojaré una serie de criaturas en cada ronda; Tienes diez minutos para completar tantas rondas como puedas.",
        ["The more rounds you complete in the given time, the greater your reward."] = "Cuantas más rondas completes en el tiempo indicado, mayor será tu recompensa.",
        ["Which creatures?"] = "¿Qué criaturas?",
        ["They could be any which I might otherwise assign you - even ones you've chosen to block. It is meant to be a challenge, after all."] = "Podrían ser cualquiera que de otro modo te asignaría, incluso aquellos que hayas decidido bloquear. Después de todo, se supone que es un desafío.",
        ["So I should be prepared for pretty much anything?"] = "¿Entonces debería estar preparado para casi cualquier cosa?",
        ["You can access a bank chest down there, and buy slayer equipment if you forgot anything."] = "Puedes acceder a un cofre del banco allí abajo y comprar equipo de cazador si olvidaste algo.",
        ["But doing so during the challenge will cost you time, so it's best to be well prepared before you begin."] = "Pero hacerlo durante el desafío te costará tiempo, por lo que es mejor estar bien preparado antes de comenzar.",
        ["What happens if I die?"] = "¿Qué pasa si muero?",
        ["Then you die."] = "Entonces mueres.",
        ["Is that all?"] = "¿Eso es todo?",
        ["Can I use your dungeon?"] = "¿Puedo usar tu mazmorra?",
        ["I don't think so. You're not skilled enough to enter my dungeon."] = "No lo creo. No tienes la habilidad suficiente para entrar a mi mazmorra.",
        ["You require 85 Slayer to enter Morvran's Rush of Blood arena."] = "Necesitas 85 Slayer para ingresar a la arena Rush of Blood de Morvran.",
        ["You haven't attempted my challenge so far this week. I'll be watching this time, so be prepared to impress me."] = "No has intentado mi desafío en lo que va de esta semana. Estaré observando esta vez, así que prepárate para impresionarme.",
        ["Unless you'd prefer to only do a 'trial run' for now?"] = "¿A menos que prefieras hacer solo una \"prueba\" por ahora?",
        ["Go on a reward or trial run?"] = "¿Realizar una recompensa o una prueba?",
        ["Reward run."] = "Carrera de recompensa.",
        ["Which challenge would you like to attempt? Remember this is a reward run, so do your best!"] = "¿Qué desafío te gustaría intentar? Recuerde que esta es una carrera de recompensa, ¡así que haga lo mejor que pueda!",
        ["Trial run."] = "Ejecución de prueba.",
        ["Which challenge would you like to attempt? Remember this is just a trial run."] = "¿Qué desafío te gustaría intentar? Recuerde que esto es sólo una prueba.",
        ["Which level of challenge would you like?"] = "¿Qué nivel de desafío te gustaría?",
        ["Bronze (85 Slayer)."] = "Bronce (85 Slayer).",
        ["You are not eligible for the Bronze challenge yet."] = "Aún no eres elegible para el desafío Bronce.",
        ["I need to know that you can kill vampyres first."] = "Necesito saber que puedes matar a vampyres primero.",
        ["To attempt the Bronze challenge requires 85 Slayer and completion of the Legacy of Seergaze quest."] = "Para intentar el desafío Bronce se requieren 85 Slayer y completar la misión Legacy of Seergaze.",
        ["Silver (90 Slayer)."] = "Plata (90 Slayer).",
        ["You are not eligible for the Silver challenge yet."] = "Aún no eres elegible para el desafío Plata.",
        ["To attempt the Silver challenge requires 90 Slayer and completion of the Legacy of Seergaze quest."] = "Para intentar el desafío Plata se requieren 90 Slayer y completar la misión Legacy of Seergaze.",
        ["Gold (95 Slayer)."] = "Oro (95 Slayer).",
        ["You are not eligible for the Gold challenge yet."] = "Aún no eres elegible para el desafío Gold.",
        ["I need to know that you're an experienced slayer of vyres, dagannoth and TokHaar first."] = "Primero necesito saber que eres un cazador experimentado de vyres, dagannoth y TokHaar.",
        ["To attempt the Gold challenge requires 95 Slayer, 90 Dungeoneering and completion of Blood Runs Deep, Branches of Darkmeyer, Ritual of the Mahjarrat, The Chosen Commander, The Elder Kiln, The Firemaker's Curse and The Void Stares Back quests."] = "Para intentar el desafío Gold se requieren 95 Slayer, 90 Dungeoneering y completar las misiones Blood Runs Deep, Branches of Darkmeyer, Ritual of the Mahjarrat, The Chosen Commander, The Elder Kiln, The Firemaker's Curse y The Void Stares Back.",
        ["Platinum (99 Slayer)."] = "Platino (99 Slayer).",
        ["You are not eligible for the Platinum challenge yet."] = "Aún no eres elegible para el desafío Platino.",
        ["I need to know that you can handle some of the toughest slayer creatures out there first."] = "Necesito saber que primero puedes encargarte de algunas de las criaturas asesinas más duras que existen.",
        ["To attempt the Platnium challenge requires 99 Slayer, 90 Dungeoneering and completion of Branches of Darkmeyer, Fate of the Gods, One of a Kind, Ritual of the Mahjarrat, The Chosen Commander, The Firemaker's Curse, The Void Stares Back, The World Wakes and While Guthix Sleeps"] = "Para intentar el desafío Platnium se requieren 99 Slayer, 90 Dungeoneering y completar Branches of Darkmeyer, Fate of the Gods, One of a Kind, Ritual of the Mahjarrat, The Chosen Commander, The Firemaker's Curse, The Void Stares Back, The World Wakes y While Guthix Sleeps.",
        ["quests."] = "misiones.",
        ["What's the difference?"] = "¿Cuál es la diferencia?",
        ["What's the difference? What do you think would be the difference? They get harder, obviously."] = "¿Cuál es la diferencia? ¿Cuál crees que sería la diferencia? Se vuelven más difíciles, obviamente.",
        ["All of the monsters you'll face in my dungeon are those I might otherwise task you with killing."] = "Todos los monstruos a los que te enfrentarás en mi mazmorra son aquellos que de otro modo te encargaría matar.",
        ["The higher the level of challenge you attempt, the tougher the creatures you'll possibly face."] = "Cuanto mayor sea el nivel del desafío que intentes, más difíciles serán las criaturas a las que posiblemente te enfrentes.",
        ["But then, with greater danger comes the chance to impress me, and a greater reward if you do well."] = "Pero luego, con mayor peligro viene la oportunidad de impresionarme y una mayor recompensa si lo haces bien.",
        ["Er...nothing..."] = "Eh... nada...",
        ["Hello there, Player, what can I help you with?"] = "Hola, Player, ¿en qué puedo ayudarte?",
        ["How am I doing so far?"] = "¿Cómo estoy hasta ahora?",
        ["You're currently assigned to kill [assigned creatures]; only X more to go."] = "Actualmente estás asignado para matar a [assigned creatures]; sólo faltan X más.",
        ["Who are you?"] = "¿Quién eres?",
        ["Where are you?"] = "¿Dónde estás?",
        ["Got any tips for me?"] = "¿Tienes algún consejo para mí?",
        ["That's all thanks."] = "Eso es todo gracias.",
        ["My name is Morvran; I'm a Slayer Master."] = "Mi nombre es Morvran; Soy un Slayer Master.",
        ["You'll find me in Prifddinas. I'll be here when you need a new task."] = "Me encontrarás en Prifddinas. Estaré aquí cuando necesites una nueva tarea.",
        ["The last [assigned creature] I killed I found [weapons] took them down effectively."] = "El último [assigned creature] que maté descubrí que [weapons] los derribó de manera efectiva.",
        ["[Task hint]"] = "[sugerencia de tarea]",
        ["Nothing really."] = "En realidad, nada.",
        ["Hello?"] = "¿Hola?",
        ["You have no business in my head. My secrets are not for your eyes. Get out."] = "No tienes nada que hacer en mi cabeza. Mis secretos no son para tus ojos. Salir.",
        ["It's Player. I'm using my magic to communicate with you."] = "Soy Player. Estoy usando mi magia para comunicarme contigo.",
        ["Too scared to seek me out in person, hmm? Well, what is it?"] = "Tienes demasiado miedo para buscarme en persona, ¿eh? Bueno, ¿qué es?",
        ["Select an option"] = "Seleccione una opción",
        ["*(Same as 'I need another assignment' above)*"] = "*(Igual que 'Necesito otra tarea' arriba)*",
        ["Er...nothing."] = "Eh... nada.",
        ["Abyssal demons are nasty creatures to deal with. They aren't really part of this realm and are able to move very quickly to trap their prey. They can be found in Canifis Slayer Tower and in the Senntisten Asylum."] = "Los demonios abisales son criaturas desagradables con las que lidiar. En realidad, no son parte de este reino y pueden moverse muy rápidamente para atrapar a sus presas. Se pueden encontrar en la Torre Canifis Slayer y en el Asilo Senntisten.",
        ["Acheron Mammoths are honourable yet powerful beasts from the frozen north. When they charge you, get out of the way! They can be found on an iceberg that is accessible from a dock near Rellekka."] = "Los mamuts de Acheron son bestias honorables pero poderosas del norte helado. Cuando te cobren, ¡apártate del camino! Se pueden encontrar en un iceberg al que se puede acceder desde un muelle cerca de Rellekka.",
        ["Adamant dragons are even more dangerous than mithril dragons. Look for them in Brimhaven dungeon, beneath a staircase north-west of the iron and steel dragons."] = "Los dragones Adamant son incluso más peligrosos que los dragones de mithril. Búscalos en la mazmorra Brimhaven, debajo de una escalera al noroeste de los dragones de hierro y acero.",
        ["The airut are aggressive creatures from another world. They have powerful arms and attack with great vigour. Certain abilities can counter and stun them, however."] = "Los airut son criaturas agresivas de otro mundo. Tienen brazos poderosos y atacan con gran vigor. Sin embargo, ciertas habilidades pueden contrarrestarlos y aturdirlos.",
        ["Aquanites are amphibious creatures that attract prey using the glowing lures on their heads. They attack stronger opponents from a distance with water magic, and dislike those who pray against it. They dwell in the Fremennik Slayer Dungeon, in a chamber past the kurasks."] = "Los acuanitas son criaturas anfibias que atraen a sus presas utilizando los señuelos brillantes que tienen en la cabeza. Atacan a oponentes más fuertes desde la distancia con magia de agua y no les agradan aquellos que rezan en contra de ella. Habitan en la mazmorra Fremennik Slayer, en una cámara más allá de los kurasks.",
        ["The Order of Ascension are magic users. It is strongly suggested you use ranged attacks. Their tactics can make them tough one-on-one, so bringing a friend along would be beneficial."] = "La Orden de la Ascensión son usuarios de magia. Se recomienda encarecidamente utilizar ataques a distancia. Sus tácticas pueden hacerlos difíciles uno a uno, por lo que sería beneficioso traer a un amigo.",
        ["Aviansie can be found in the God Wars Dungeon north of Trollheim. As they are flying, you'll find melee attacks are not going to cut it."] = "Aviansie se puede encontrar en God Wars Dungeon al norte de Trollheim. Mientras vuelan, descubrirás que los ataques cuerpo a cuerpo no serán suficientes.",
        ["Black demons are weak to ranged attacks. They're still the strongest demon and very dangerous, however. Seek them out in the Edgeville or Brimhaven dungeons."] = "Los demonios negros son débiles ante los ataques a distancia. Sin embargo, siguen siendo el demonio más fuerte y muy peligroso. Búscalos en las mazmorras Edgeville o Brimhaven.",
        ["Black dragons are among the strongest dragons and are very fierce. Watch out for their fiery breath. I am sure you will have seen them in your travels and have honed your techniques on lesser dragons."] = "Los dragones negros se encuentran entre los dragones más fuertes y son muy feroces. Cuidado con su aliento de fuego. Estoy seguro de que los habrás visto en tus viajes y habrás perfeccionado tus técnicas con dragones menores.",
        ["Camel warriors can use ancient magics to attack you. They also have the blessings of Akthanakos and can create powerful, disorientating mirages.  They can be found in the deep desert."] = "Los guerreros Camel pueden usar magia antigua para atacarte. También cuentan con las bendiciones de Akthanakos y pueden crear espejismos poderosos y desorientadores.  Se pueden encontrar en lo profundo del desierto.",
        ["Celestial dragons are one of the strangest dragons I assign. They use melee but also have a powerful dragonfire attack, as well as a fascinating ability to momentarily stop time. You can find them in the depths of Dragontooth Island."] = "Los dragones celestiales son uno de los dragones más extraños que asigno. Usan cuerpo a cuerpo pero también tienen un poderoso ataque de fuego de dragón, así como una habilidad fascinante para detener el tiempo momentáneamente. Puedes encontrarlos en las profundidades de la isla Dragontooth.",
        ["You can find Chaos giants out in the Barendir tunnels, beyond Keldagrim. Be careful, as they can launch their Dragon throwing axe at range or take a swipe at you if you get close. Perhaps you could recover some."] = "Puedes encontrar gigantes del Caos en los túneles de Barendir, más allá de Keldagrim. Ten cuidado, ya que pueden lanzar su hacha arrojadiza Dragón a distancia o golpearte si te acercas. Quizás puedas recuperar algo.",
        ["You can find corrupted creatures in the Sophanem Slayer Dungeon."] = "Puedes encontrar criaturas corruptas en la mazmorra Sophanem Slayer.",
        ["You can find the creatures of the lost grove within the lost grove, south of the poison waste."] = "Puedes encontrar las criaturas de la arboleda perdida dentro de la arboleda perdida, al sur del páramo venenoso.",
        ["Without their master, Cres's automatons roam Guthix's chambers attacking any who enter. They are programmed to use magic, melee or ranged and can perform a violent area-of-effect attack. Guthix's chambers may be reached via his shrine, or the excavation west of the Legends' Guild."] = "Sin su maestro, los autómatas de Cres deambulan por las cámaras de Guthix atacando a cualquiera que entre. Están programados para usar magia, cuerpo a cuerpo o a distancia y pueden realizar un violento ataque de área de efecto. Se puede llegar a las cámaras de Guthix a través de su santuario o de la excavación al oeste de Legends' Guild.",
        ["Crystal shapeshifters are deranged remnants of the elves on Tarddiad. They are quite mad and, according to Angof, beyond redemption. Show them mercy by ending their suffering."] = "Los cambiaformas de cristal son restos trastornados de los elfos de Tarddiad. Están bastante locos y, según Angof, no tienen redención. Muéstrales misericordia poniendo fin a su sufrimiento.",
        ["Dagannoth are large, sea-dwelling creatures that are very aggressive. You'll often find them in caves near sea water. There is no joy so great as to cleanse these from the face of Gielinor."] = "Los Dagannoth son criaturas marinas grandes que son muy agresivas. A menudo los encontrarás en cuevas cerca del agua de mar. No hay alegría tan grande como limpiar estos de the face de Gielinor.",
        ["Dark beasts are large, dog-like predators with massively muscled bodies that protect them from crushing weapons. We found some while mining the Mourner tunnels, in search of the Temple of Light."] = "Las bestias oscuras son depredadores grandes, parecidos a perros, con cuerpos enormemente musculosos que los protegen de las armas aplastantes. Encontramos algunos mientras minábamos los túneles Mourner, en busca del Templo de la Luz.",
        ["You'll find these east of Al Kharid, atop the mountain. Watch out for their vicious ranged attacks!"] = "Los encontrarás al este de Al Kharid, en la cima de la montaña. ¡Cuidado con sus feroces ataques a distancia!",
        ["Edimmu are ghosts which failed to escape their body. They're ghosts and zombies, yet somehow different altogether. They use ranged attacks and are highly aggressive. You can find them in a resource dungeon, which the Meilyr clan in Prifddinas has access to."] = "Edimmu son fantasmas que no lograron escapar de su cuerpo. Son fantasmas y zombis, pero de alguna manera completamente diferentes. Usan ataques a distancia y son muy agresivos. Puedes encontrarlos en una mazmorra de recursos a la que tiene acceso el clan Meilyr en Prifddinas.",
        ["I'm not advocating the killing of my kind, you understand - we enjoy being tested in combat. You'll find melee fighters in Clan Iorwerth's segment of Prifddinas; mages and rangers in Clan Cadarn's segment."] = "No estoy recomendando matar a los de mi especie, ¿entiendes? Nos gusta que nos pongan a prueba en combate. Encontrarás luchadores cuerpo a cuerpo en el segmento de Prifddinas del Clan Iorwerth; magos y guardabosques en el segmento del Clan Cadarn.",
        ["Ganodermic beasts and runts live in the depths of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Las bestias ganodermicas y los enanos viven en las profundidades de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que debes luchar contra ellas desde la distancia. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
        ["Gargoyles are winged creatures of stone. You'll need to fight them until they are close to death before breaking them apart with a rock hammer. They can be found in Canifis Slayer Tower."] = "Las gárgolas son criaturas aladas de piedra. Tendrás que luchar contra ellos hasta que estén al borde de la muerte antes de romperlos con un martillo de piedra. Se pueden encontrar en la Torre Canifis Slayer.",
        ["You can find gemstone dragons beneath the gem mine in Shilo Village."] = "Puedes encontrar dragones de piedras preciosas debajo de la mina de gemas en Shilo Village.",
        ["Glacors were brought to this world by Lucien. They use magic, ranged and melee attacks. You can find them in an underground cavern on the Frozen Plateau."] = "Lucien trajo los glacors a este mundo. Usan ataques mágicos, a distancia y cuerpo a cuerpo. Puedes encontrarlos en una caverna subterránea en Frozen Plateau.",
        ["Greater demons are weak to ranged attacks. Though not the strongest of demons, they are still dangerous. There are some in Brimhaven Dungeon."] = "Los demonios mayores son débiles ante los ataques a distancia. Aunque no son los demonios más fuertes, siguen siendo peligrosos. Hay algunos en Brimhaven Dungeon.",
        ["Grotworms have recently been spotted in a cave near Rimmington. They will bite and attack with some sort of acid spit. Be careful - they are very aggressive."] = "Recientemente se han visto gusanos grot en una cueva cerca de Rimmington. Morderán y atacarán con una especie de saliva ácida. Tenga cuidado, son muy agresivos.",
        ["The coldest of their kind, they are found beneath the Fremennik mountains. As they are beings of ice, I've found that fire spells inflict far more damage against them."] = "Los más fríos de su tipo, se encuentran debajo de las montañas Fremennik. Como son seres de hielo, descubrí que los hechizos de fuego les infligen mucho más daño.",
        ["Iron dragons are some of the weaker metallic dragons, with iron scales that are far thicker than normal iron armour. Their fiery breath and sharp claws can be negated by a number of means. Look for them in Brimhaven Dungeon."] = "Los dragones de hierro son algunos de los dragones metálicos más débiles, con escamas de hierro que son mucho más gruesas que las armaduras de hierro normales. Su aliento de fuego y sus afiladas garras pueden anularse de diversas formas. Búscalos en Brimhaven Dungeon.",
        ["Kal'gerion demons are powerful creatures that use both magic and melee. They reside in a resource dungeon near Daemonheim. I would recommend you take cover when they smash the ground, or when they use magic to pull you towards them."] = "Los demonios Kal'gerion son criaturas poderosas que usan tanto magia como cuerpo a cuerpo. Residen en una mazmorra de recursos cerca de Daemonheim. Te recomendaría que te cubrieras cuando rompan el suelo o cuando usen magia para atraerte hacia ellos.",
        ["Kalphites are large insects that live in hives under the desert sands. I am sure that, by now, you have seen them to the south-west of Shantay Pass."] = "Los calfitos son insectos grandes que viven en colmenas bajo las arenas del desierto. Estoy seguro de que ya los habrás visto al suroeste del paso Shantay.",
        ["Lava strykewyrms are the most powerful of their kind. They attack with all combat styles and are weak to nothing. They can be found deep within the Wilderness so I would watch your back while slaying them."] = "Los strykewyrms de lava son los más poderosos de su tipo. Atacan con todos los estilos de combate y son débiles o nada. Se pueden encontrar en lo profundo de Wilderness, por lo que yo te cuidaría las espaldas mientras los mato.",
        ["Living wyverns breathe a poison that will kill you rapidly unless you are freezing. But watch out; the colder you are the harder their regular attacks will hit you.  They can be found in the Asgarnia Ice dungeon."] = "Los wyverns vivos respiran un veneno que te matará rápidamente a menos que te congeles. Pero cuidado; cuanto más frío tengas, más duro te golpearán sus ataques habituales.  Se pueden encontrar en la mazmorra de hielo de Asgarnia.",
        ["Mithril dragons are very dangerous opponents. There's some in the Ancient Cavern, north of where you'll find Kuradal. You are a battle master - test your skills."] = "Los dragones de mitril son oponentes muy peligrosos. Hay algunos en la Caverna Antigua, al norte de donde encontrarás Kuradal. Eres un maestro de batalla: prueba tus habilidades.",
        ["Muspah are creatures born of nightmares. Ancient magic is the most effective thing to use against them. You can find them by travelling to Freneskae. They'll be aggressive unless you wear your shard of Zaros."] = "Los muspah son criaturas nacidas de pesadillas. La magia antigua es lo más eficaz que se puede utilizar contra ellos. Puedes encontrarlos viajando a Freneskae. Serán agresivos a menos que uses tu fragmento de Zaros.",
        ["These warped jade vine creatures will not hesitate to use their environment to help them in combat if they cannot retaliate otherwise. The baby jadinkos are easiest to kill, but the males offer the greatest rewards. Ranged weapons made from vines are best against them."] = "Estas criaturas deformadas de enredadera de jade no dudarán en utilizar su entorno para ayudarles en el combate si no pueden tomar represalias de otra manera. Las crías de jadinkos son más fáciles de matar, pero los machos ofrecen las mayores recompensas. Las armas Ranged hechas de enredaderas son mejores contra ellos.",
        ["Nechryael are demons of decay that summon small winged beings to help them fight their victims. They can be found in the Chaos Tunnels or in Canifis Slayer Tower."] = "Nechryael son demonios de la decadencia que convocan a pequeños seres alados para que les ayuden a luchar contra sus víctimas. Se pueden encontrar en los Túneles del Caos o en la Torre Canifis Slayer.",
        ["You can find nightmare creatures on Freneskae, which can be accessed through the world gate."] = "Puedes encontrar criaturas de pesadilla en Freneskae, a las que se puede acceder a través de la puerta del mundo.",
        ["The surviving subjects of Zaros's experiments. They have powerful charge attacks and fight in packs of four. You can find them by travelling to Freneskae. They'll be aggressive unless you wear your shard of Zaros."] = "Los sujetos supervivientes de los experimentos de Zaros. Tienen poderosos ataques cargados y luchan en grupos de cuatro. Puedes encontrarlos viajando a Freneskae. Serán agresivos a menos que uses tu fragmento de Zaros.",
        ["Nodon dragonkin are deeply intelligent creatures, armed with advanced siege weaponry. However, they are weak to dragonbane weapons. You can find them fighting for Jas in Senntisten."] = "Los dragonantes nodon son criaturas profundamente inteligentes, armadas con armamento de asedio avanzado. Sin embargo, son débiles ante las armas dragonbane. Puedes encontrarlos luchando por Jas en Senntisten.",
        ["Ripper Demons are driven crazy by the scent of blood. They will hit you harder the worse your injuries are. And watch out; they can sometimes drop on you from above, which is lethal.  They can be found in a fissure near Al Kharid."] = "Los demonios destripadores se vuelven locos por el olor a sangre. Te golpearán más fuerte cuanto peores sean tus lesiones. Y cuidado; A veces pueden caer sobre ti desde arriba, lo cual es letal.  Se pueden encontrar en una fisura cerca de Al Kharid.",
        ["Rune dragons are even more dangerous than adamant dragons. I highly recommend you bring dragonbane ammunition to pierce their armour. To find them, you must travel to Kethsi via the World Gate in Arandar."] = "Los dragones rúnicos son incluso más peligrosos que los dragones inflexibles. Te recomiendo que traigas munición dragonbane para perforar su armadura. Para encontrarlos, debes viajar a Kethsi a través de la Puerta del Mundo en Arandar.",
        ["Shadows are light creatures that have been corrupted by the Dark Lord. The Amlodd summon them to their section of the city in order to defeat them and then cleanse their cores."] = "Las sombras son criaturas ligeras que han sido corrompidas por el Señor Oscuro. Los Amlodd los convocan a su sección de la ciudad para derrotarlos y luego limpiar sus núcleos.",
        ["You can find soul devourers in the Sophanem Slayer Dungeon."] = "Puedes encontrar devoradores de almas en la mazmorra Sophanem Slayer.",
        ["You can find stalker creatures within Zamorak's hideout."] = "Puedes encontrar criaturas acosadoras dentro del escondite de Zamorak.",
        ["Steel dragons are dangerous and metallic, with steel scales that are far thicker than normal steel armour. Look for them in Brimhaven Dungeon."] = "Los dragones de acero son peligrosos y metálicos, con escamas de acero que son mucho más gruesas que las armaduras de acero normales. Búscalos en Brimhaven Dungeon.",
        ["Tormented demons are powerful creatures that use magic, ranged and melee attacks. They also have the ability to shield themselves. You can find them below the Tears of Guthix cave."] = "Los demonios atormentados son criaturas poderosas que usan ataques mágicos, a distancia y cuerpo a cuerpo. También tienen la capacidad de protegerse. Puedes encontrarlos debajo de la cueva Lágrimas de Guthix.",
        ["The TzHaar are mighty warriors - prove yourself against them. You'll find them deep within the Karamja Volcano."] = "Los TzHaar son guerreros poderosos: pruébate contra ellos. Los encontrarás en lo profundo del volcán Karamja.",
        ["These foul creatures can be found throughout Meiyerditch and Darkmeyer in Morytania. They have a telepathic ability which enables them to dodge incoming attacks, so you'll need a weapon specially created to harm them."] = "Estas repugnantes criaturas se pueden encontrar en Meiyerditch y Darkmeyer en Morytania. Tienen una habilidad telepática que les permite esquivar los ataques entrantes, por lo que necesitarás un arma especialmente creada para dañarlos.",
        ["Waterfiends are elemental creatures found north of Kuradal in the Ancient Cavern. Those followed by familiars are keen to slay them."] = "Los Waterfiends son criaturas elementales que se encuentran al norte de Kuradal en la Caverna Antigua. Los que siguen a sus familiares están ansiosos por matarlos.",
        ["What do you want? Oh, actually, you've been doing quite well in my arena. Here's an XP lamp for your efforts. Use it or lose it, I don't care."] = "¿Qué quieres? Oh, en realidad, te ha ido bastante bien en mi campo. Aquí tienes una lámpara XP por tus esfuerzos. Úsalo o piérdelo, no me importa.",
    },
    ["Mosol Rei"] = {
        ["Sorry bwana, I cannot help you at this time. Go and talk to Trufitus at Tai Bwo Wannai, I believe he needs some help."] = "Lo siento bwana, no puedo ayudarte en este momento. Ve y habla con Trufitus en Tai Bwo Wannai, creo que necesita ayuda.",
    },
    ["Mossbrain"] = {
        ["Best to turn a blind eye to what you're eating and drinking around here."] = "Lo mejor es hacer la vista gorda ante lo que comes y bebes por aquí.",
        ["Pinch your nose, shut your eyes, and just gobble."] = "Pellizca tu nariz, cierra los ojos y simplemente engulle.",
    },
    ["Mostafa the Camel"] = {
        ["** ** The camel eyes you wearily and readies a spit. You think better of saying anything."] = "** ** El camello te mira con cansancio y prepara un asador. Piensa mejor en decir cualquier cosa.",
        ["Hello, camel."] = "Hola, camello.",
        ["The name's Mostafa."] = "El nombre es Mostafa.",
        ["Select an option"] = "Seleccione una opción",
        ["Isn't it a lovely day?"] = "¿No es un hermoso día?",
        ["Lovely? I wouldn't call it lovely. Sun's hot, sand's hot and my feet are killing me."] = "¿Encantador? Yo no lo llamaría encantador. El sol calienta, la arena calienta y mis pies me están matando.",
        ["Oh. Um... Well, can't you lie down in the shade or something?"] = "Oh. Um... Bueno, ¿no puedes tumbarte a la sombra o algo así?",
        ["Shade? Around here? And you try lying down with a ton of granite on your back."] = "¿Sombra? ¿Por aquí? E intentas acostarte con una tonelada de granito en la espalda.",
        ["How are you?"] = "¿Cómo estás?",
        ["Terrible. These panniers chafe something rotten and I have a pain all down my left side."] = "Terrible. Estas alforjas rozan algo podrido y me duele todo el costado izquierdo.",
        ["Oh dear, that sounds nasty. Can't you take them off?"] = "Dios mío, eso suena desagradable. ¿No puedes quitártelos?",
        ["Of course not. No thumbs."] = "Por supuesto que no. Sin pulgares.",
        ["Won't Aligra take them off?"] = "¿No se los quitará Aligra?",
        ["Certainly not - I'm the only way he's going to shift that lot of rock."] = "Por supuesto que no. Soy la única manera de mover esa cantidad de roca.",
        ["Do you enjoy your job?"] = "¿Disfrutas de tu trabajo?",
        ["Horrible. I didn't ask to haul rock around. No one consulted me."] = "Horrible. No pedí transportar piedras. Nadie me consultó.",
        ["That's terrible! How did you start?"] = "¡Eso es terrible! ¿Cómo empezaste?",
        ["I was just sitting there, contemplating the problem of writing out my proof to the twin prime problem without thumbs and then WHACK! I get this halter and whopping great panniers stuck on me and - before I know it - I'm loaded down with rock!"] = "Estaba sentado allí, contemplando el problema de escribir mi prueba del problema de los primos gemelos sin pulgares y luego ¡PAZ! Se me pega este cabestro y unas enormes alforjas y, antes de darme cuenta, ¡estoy cargado de piedras!",
    },
    ["Mourner"] = {
        ["You try to open the large wooden doors..."] = "Intentas abrir las grandes puertas de madera...",
        ["...But they will not open."] = "...Pero no se abren.",
        ["Oi! What are you doing? Get away from there!"] = "¡Oye! ¿Qué estás haciendo? ¡Aléjate de allí!",
        ["Hi."] = "Hola.",
        ["What are you up to?"] = "¿Qué estás haciendo?",
        ["Just sight-seeing."] = "Sólo hacer turismo.",
        ["This is no place for sight-seeing. Don't you know there's been a plague outbreak?"] = "Este no es un lugar para hacer turismo. ¿No sabes que ha habido un brote de peste?",
        ["Yes, I had heard."] = "Sí, lo había oído.",
        ["Then I suggest you leave as soon as you can."] = "Entonces te sugiero que te vayas tan pronto como puedas.",
        ["Select an option"] = "Seleccione una opción",
        ["What brought the plague to Ardougne?"] = "¿Qué trajo la plaga a Ardougne?",
        ["It's all down to King Tyras of West Ardougne. Rather than protecting his people he spends his time in the lands to the West. When he returned last he brought the plague with him then left before the problem became serious."] = "Todo depende del rey Tyras de West Ardougne. En lugar de proteger a su pueblo, pasa su tiempo en las tierras del Oeste. La última vez que regresó, trajo la plaga consigo y se fue antes de que el problema se volviera grave.",
        ["Does he know how bad the situation is now?"] = "¿Sabe lo mala que está la situación ahora?",
        ["If he did he wouldn't care. I believe he wants his people to suffer, he's an evil man."] = "Si lo hiciera, no le importaría. Creo que quiere que su pueblo sufra, es un hombre malvado.",
        ["Isn't that treason?"] = "¿No es eso traición?",
        ["He's not my king."] = "Él no es mi rey.",
        ["What are the symptoms of the plague?"] = "¿Cuáles son los síntomas de la peste?",
        ["The first signs are typical flu symptoms. These tend to be followed by severe nightmares, horrifying hallucinations which drive many to madness."] = "Los primeros signos son los síntomas típicos de la gripe. Suelen ir seguidas de pesadillas graves, alucinaciones espantosas que llevan a muchos a la locura.",
        ["Sounds nasty."] = "Suena desagradable.",
        ["It gets worse. Next the victim's blood changes into a thick black tar-like liquid, at this point they're past help. Their skin is cold to the touch, the victim is now brain dead. Their body however lives on driven by the virus, roaming like a zombie, spreading itself further wherever possible."] = "Se pone peor. Luego, la sangre de la víctima se transforma en un líquido espeso y negro parecido al alquitrán, en este punto ya no hay ayuda. Su piel está fría al tacto, la víctima ahora tiene muerte cerebral. Sin embargo, su cuerpo sigue vivo impulsado por el virus, deambulando como un zombi y propagándose más siempre que sea posible.",
        ["I think I've heard enough."] = "Creo que ya he oído suficiente.",
        ["Thanks for the advice."] = "Gracias por el consejo.",
        ["Hello."] = "Hola.",
        ["Nothing."] = "Nada.",
        ["I don't trust you."] = "No confío en ti.",
        ["You don't have to."] = "No es necesario.",
        ["If I find you attempting to cross the wall I'll make sure you never return."] = "Si te encuentro intentando cruzar el muro, me aseguraré de que nunca regreses.",
        ["Stand back citizen, do not approach me."] = "Apártate ciudadano, no te acerques a mí.",
        ["Hmmm, how did you get over here? You're not one of this rabble. Ah well, you'll have to stay. Can't risk you going back now."] = "Hmmm, ¿cómo llegaste hasta aquí? No eres uno más de esta chusma. Ah, bueno, tendrás que quedarte. No puedo arriesgarme a que regreses ahora.",
        ["So what's a mourner?"] = "Entonces, ¿qué es un doliente?",
        ["We're working for King Lathas of East Ardougne trying to contain the accursed plague sweeping West Ardougne. We also do our best to ease these people's suffering. We're nicknamed mourners because we spend a lot of time at plague victim funerals, no-one else is allowed to risk the funerals. It's a demanding job, and we get little thanks from the people here."] = "Estamos trabajando para King Lathas de East Ardougne tratando de contener la maldita plaga que arrasa West Ardougne. También hacemos todo lo posible para aliviar el sufrimiento de estas personas. Nos llaman dolientes porque pasamos mucho tiempo en los funerales de las víctimas de la peste, nadie más puede arriesgarse a los funerales. Es un trabajo exigente y la gente de aquí nos agradece poco.",
        ["I haven't got the plague though..."] = "Aunque no tengo la peste...",
        ["I haven't got the plague though."] = "Aunque no tengo la plaga.",
        ["Can't risk you being a carrier. That protective clothing you have isn't regulation issue. It won't meet safety standards."] = "No puedo arriesgarme a que seas portador. Esa ropa protectora que tienes no es una cuestión de regulación. No cumplirá con los estándares de seguridad.",
        ["Who are you? Go away!"] = "¿Quién eres? ¡Irse!",
        ["You should know better than to wear non-regulation gear."] = "Deberías saber que no debes usar equipo no reglamentario.",
        ["Sorry, I'm new around here."] = "Lo siento, soy nuevo por aquí.",
        ["Well, you know the drill - lose the gear, I will let it pass this time."] = "Bueno, ya conoces el procedimiento: suelta el engranaje, esta vez lo dejaré pasar.",
        ["Good day. Are you in need of assistance?"] = "Buenos días. ¿Necesita ayuda?",
        ["Yes, but I don't think you can help."] = "Sí, pero no creo que puedas ayudar.",
        ["You will be surprised at how much help the brute force of the Guard can be."] = "Te sorprenderá lo útil que puede ser la fuerza bruta de la Guardia.",
        ["Well I'll be sure to ask if I'm in need of some muscle."] = "Bueno, me aseguraré de preguntarte si necesito algo de músculo.",
        ["No, I just wanted to talk to a friendly face."] = "No, solo quería hablar con una cara amiga.",
        ["Do I look friendly to you? I really must work on my scowl more."] = "¿Te parezco amigable? Realmente debo trabajar más en mi ceño.",
        ["Hello, you must be one of the new guys."] = "Hola, debes ser uno de los nuevos.",
        ["That's right."] = "Así es.",
        ["Watch yourself with the head, he has a bit of a temper."] = "Cuídate con la cabeza, tiene un poco de mal genio.",
        ["Thanks for the warning."] = "Gracias por la advertencia.",
        ["Good day."] = "Buenos días.",
        ["It is good to see so many new recruits, soon no one will be able to stand against the power of the Death Guard."] = "Es bueno ver tantos nuevos reclutas, pronto nadie podrá enfrentarse al poder de la Guardia de la Muerte.",
        ["That sounds... err great."] = "Eso suena... genial.",
        ["Indeed it is."] = "De hecho lo es.",
        ["The Mourner throws a vial at you."] = "El Mourner te lanza un vial.",
        ["You feel weakened."] = "Te sientes debilitado.",
    },
    ["Movario"] = {
        ["What's the device saying now?"] = "¿Qué dice el dispositivo ahora?",
        ["I don't know. It's giving me strange readings..."] = "No lo sé. Me está dando lecturas extrañas...",
        ["I'm not even sure it's working any more."] = "Ni siquiera estoy seguro de que ya funcione.",
        ["This is a wild goose chase! We trek halfway across the world and there's nothing down here but this bunch of useless goblins!"] = "¡Esta es una búsqueda inútil! ¡Atravesamos medio mundo y no hay nada aquí abajo excepto este grupo de duendes inútiles!",
        ["I am sure my triangulation calculations indicated that the source of power was in this rough area..."] = "Estoy seguro de que mis cálculos de triangulación indicaron que la fuente de energía estaba en esta zona aproximada...",
        ["I find it encouraging that it's pointed to somewhere where there actually are caves."] = "Me parece alentador que apunte a algún lugar donde en realidad hay cuevas.",
        ["This part of the world is riddled with caves! It's hard not to hit a cave around here! Are you sure you're not just picking up these goblin lanterns or something stupid?"] = "¡Esta parte del mundo está plagada de cuevas! ¡Es difícil no toparse con una cueva por aquí! ¿Estás seguro de que no estás simplemente recogiendo estas linternas de duendes o algo estúpido?",
        ["You should have more faith in my skills as a mage! I've been working on this for years-"] = "¡Deberías tener más fe en mis habilidades como mago! He estado trabajando en esto durante años.",
        ["Gah! We have an eavesdropper! Buzz off, adventurer - go talk to the goblins or something."] = "¡Ah! ¡Tenemos un espía! Buzz fuera, aventurero: ve a hablar con los duendes o algo así.",
        ["Okay, I won't bother you."] = "Está bien, no te molestaré.",
        ["That's what I like to see: a polite adventurer! Now, where was I..."] = "Eso es lo que me gusta ver: ¡un aventurero educado! Ahora, ¿dónde estaba yo...?",
        ["What are you looking for?"] = "¿Qué estás buscando?",
        ["None of your business!"] = "¡No es asunto tuyo!",
        ["Hey, I'm one of you guys! See this pendant? <sub>While wearing a pendant of Lucien.</sub>"] = "¡Hola, soy uno de ustedes! ¿Ves este colgante? <sub>Con un colgante de Lucien.</sub>",
        ["Where did you come from? Who sent you? I'll have you know I'm the mage's bodyguard for this job. We don't need anyone else!"] = "¿De dónde vienes? ¿Quién te envió? Te haré saber que soy el guardaespaldas del mago para este trabajo. ¡No necesitamos a nadie más!",
        ["No one sent me, I'm just nosy."] = "Nadie me envió, solo soy un entrometido.",
        ["Well stick your nose somewhere else!"] = "¡Pues mete la nariz en otro lado!",
        ["I'm sorry, but pendant or no pendant, this is a secret. I'm sure you understand."] = "Lo siento, pero con o sin colgante, esto es un secreto. Estoy seguro de que lo entiendes.",
        ["Lucien sent me."] = "Lucien me envió.",
        ["He did not! If he had, I would be aware of it!"] = "¡No lo hizo! Si lo hubiera hecho, ¡lo sabría!",
        ["Don't try to lie to us! Now go away!"] = "¡No intentes mentirnos! ¡Ahora vete!",
        ["[Charm] I'm sure you're a much better bodyguard than me... <sub>While wearing a Ring of Charos.</sub>"] = "[Charm] Estoy seguro de que eres mucho mejor guardaespaldas que yo... <sub> Mientras usas un Ring of Charos.</sub>",
        ["I'm sure you're a much better bodyguard than me, but perhaps I can help in some non-bodyguarding way?"] = "Estoy seguro de que eres mucho mejor guardaespaldas que yo, pero ¿tal vez pueda ayudarte de alguna manera que no sea como guardaespaldas?",
        ["Well, we don't know how big this thing is. If we find it, I suppose we might need someone else to help us carry it."] = "Bueno, no sabemos qué tan grande es esta cosa. Si lo encontramos, supongo que necesitaremos que alguien más nos ayude a transportarlo.",
        ["So, what are we looking for?"] = "Entonces, ¿qué estamos buscando?",
        ["You're not very well briefed, are you?"] = "No estás muy bien informado, ¿verdad?",
        ["To be honest I'm still a bit hazy on that point too."] = "Para ser honesto, todavía estoy un poco confuso sobre ese punto.",
        ["*sigh*"] = "*suspiro*",
        ["Lucien has asked us to search for artefacts that give off a very specific type of energy. After many years of research, I think I'm finally drawing near."] = "Lucien nos ha pedido que busquemos artefactos que emitan un tipo de energía muy específico. Después de muchos años de investigación, creo que finalmente me estoy acercando.",
        ["You don't sound very sure."] = "No pareces muy seguro.",
        ["Bah! My detection device is totally shot. I don't understand it."] = "¡Bah! Mi dispositivo de detección está totalmente disparado. No lo entiendo.",
        ["I wouldn't hang around for now, adventurer. It could be a long while before I can get a clear reading."] = "No me quedaría por ahora, aventurero. Podría pasar mucho tiempo antes de que pueda obtener una lectura clara.",
        ["Okay, I'll be on my way."] = "Está bien, seguiré mi camino.",
        ["Ah, Player, you found this place too."] = "Ah, Player, tú también encontraste este lugar.",
        ["What are you doing here?"] = "¿Qué haces aquí?",
        ["Well, the Stone was here, but we're too late. Lucien seems to have moved it away. Still, this cave is very interesting. There's lots of residual energy from the Stone to study."] = "Bueno, la Piedra estaba aquí, pero llegamos demasiado tarde. Lucien parece haberlo alejado. Aún así, esta cueva es muy interesante. Hay mucha energía residual de la Piedra para estudiar.",
        ["I felt some energy myself when I entered the area."] = "Yo mismo sentí algo de energía cuando entré al área.",
        ["Yes, from what I can tell, the energy increases one's potency in combat for a time. I've done a few experiments and discovered that the closer one is to the cave, the greater the effect. It seems to extend some way across the Wilderness and troll country before diminishing entirely."] = "Sí, por lo que puedo decir, la energía aumenta la potencia en combate por un tiempo. Hice algunos experimentos y descubrí que cuanto más cerca uno está de la cueva, mayor es el efecto. Parece extenderse hasta cierto punto por Wilderness y el país de los trolls antes de disminuir por completo.",
        ["Blast, this infernal device isn't working. Too much local interference, maybe? If that were the case, though, does that me- Hey, are you here to help me find the Source?"] = "Maldita sea, este dispositivo infernal no funciona. ¿Demasiada interferencia local, tal vez? Sin embargo, si ese fuera el caso, ¿ese sería yo? Oye, ¿estás aquí para ayudarme a encontrar la Fuente?",
        ["You need to complete the Archaeology tutorial before you can work at this site."] = "Debe completar el tutorial de Archaeology antes de poder trabajar en este sitio.",
        ["Speak to Acting Guildmaster Reiniger at the Archaeology campus, east of the Varrock lodestone, to learn more."] = "Hable con Acting Guildmaster Reiniger en el campus de Archaeology, al este de Varrock lodestone, para obtener más información.",
        ["You need 20 Archaeology to access this site."] = "Necesita 20 Archaeology para acceder a este sitio.",
        ["I struggle to understand the monolith's directions to the 'Source'. It points north-west, but the distance and depth are unclear, variable."] = "Me cuesta entender las direcciones del monolito hacia la 'Fuente'. Apunta al noroeste, pero la distancia y la profundidad no están claras y son variables.",
        ["At least Movario seems confident we are digging in the right place. He explores rumours of a cult that seemingly operated in this area throughout the Third Age."] = "Al menos Movario parece estar seguro de que estamos investigando en el lugar correcto. Explora los rumores de un culto que aparentemente operó en esta zona durante la Tercera Edad.",
        ["Though what the Source itself actually is remains a mystery. Perhaps all of this is due to the chaotic nature of the thing?"] = "Aunque lo que realmente es la Fuente en sí sigue siendo un misterio. ¿Quizás todo esto se deba a la naturaleza caótica del asunto?",
        ["The monolith revealed this chaotic nature to me. That is why it is so interested in learning more about the Source..."] = "El monolito me reveló esta naturaleza caótica. Por eso está tan interesado en aprender más sobre la Fuente...",
        ["Movario was right! The buried Star Lodge contained a secret cult dungeon hidden beneath it, and within that a portal to the Source itself!"] = "¡Movario tenía razón! ¡El Star Lodge enterrado contenía una mazmorra de culto secreta escondida debajo de ella, y dentro de ella un portal a la Fuente misma!",
        ["How many were taken by this cult and sacrificed over the centuries? It's horrific to even think about."] = "¿Cuántos fueron tomados por este culto y sacrificados a lo largo de los siglos? Es horrible incluso pensar en ello.",
        ["To have your soul ripped out to power a portal to Dis, to bring forth demons into this world!"] = "¡Que te arranquen el alma para abrir un portal a Dis y traer demonios a este mundo!",
        ["Dagon the Gatekeeper, an unwitting and unwilling partipicant in this hellscape, is as much a victim as those sacrificed. Is Dagon what the monolith desired we uncover?"] = "Dagon the Gatekeeper, un participante involuntario y reacio en este infierno, es tan víctima como los sacrificados. ¿Es Dagón lo que el monolito deseaba que descubriéramos?",
        ["I have some strange infernal dice here somewhere. Did you lose them or something?"] = "Tengo unos extraños dados infernales aquí en alguna parte. ¿Los perdiste o algo así?",
        ["Take dice back from Movario?"] = "¿Recuperar los dados de Movario?",
        ["Yes."] = "Sí.",
        ["Fine, I'll hold them for now. You know, you really shouldn't play games with imps - they cheat all the time."] = "Bien, los guardaré por ahora. Sabes, realmente no deberías jugar con diablillos: hacen trampa todo el tiempo.",
        ["I'm holding on to this chaotic gatestone you bought."] = "Me aferro a esta caótica piedra de entrada que compraste.",
        ["You need 1 free inventory space."] = "Necesitas 1 espacio de inventario gratuito.",
        ["I found this chaotic gatestone - did you want it back?"] = "Encontré esta caótica piedra de entrada. ¿La querías recuperar?",
        ["Take chaotic gatestone relic component back?"] = "¿Recuperar el caótico componente de reliquia de puerta de entrada?",
        ["Okay, just let me know when you want it back."] = "Está bien, avísame cuando quieras recuperarlo.",
        ["Select an Option"] = "Selecciona una opción",
        ["Why are you the site manager here?"] = "¿Por qué eres el administrador del sitio aquí?",
        ["Because I'm quite well known for tracking down powerful magical relics from ages past. Wait, you're Player - you have already witnessed my greatness. Why am I explaining this to you?"] = "Porque soy bastante conocido por rastrear poderosas reliquias mágicas de épocas pasadas. Espera, eres Player; ya has sido testigo de mi grandeza. ¿Por qué te explico esto?",
        ["Oh, right, yeah. You're not a member of the Archaeology Guild, though, are you?"] = "Ah, claro, sí. Pero no eres miembro del gremio Archaeology, ¿verdad?",
        ["No thank you. I'm an independent contractor. Those guild members disparagingly refer to me as a 'pothunter', think that I'm only interested in the money and the fame. They're wrong. I'm interested in the power too!"] = "No, gracias. Soy un contratista independiente. Esos miembros del gremio se refieren despectivamente a mí como un 'cazador de marihuana', piensan que sólo me interesa el dinero y la fama. Están equivocados. ¡A mí también me interesa el poder!",
        ["Okay. I can see why you were a great choice to manage this site, then..."] = "Está bien. Puedo ver por qué fuiste una gran elección para administrar este sitio, entonces...",
        ["Of course you do!"] = "¡Por supuesto que sí!",
        ["That was sarcasm."] = "Eso fue sarcasmo.",
        ["*sigh* Well, you'll see."] = "*suspiro* Bueno, ya verás.",
        ["What is this dig site about?"] = "¿De qué se trata este sitio de excavación?",
        ["**Player** The Source? What's the Source?"] = "**Player** ¿La fuente? ¿Cuál es la fuente?",
        ["**Movario** It's shorthand for the Infernal Source. Apparently, it's some long-lost and enormously powerful energy source."] = "**Movario** Es la abreviatura de Infernal Source. Aparentemente, se trata de una fuente de energía enormemente poderosa y perdida hace mucho tiempo.",
        ["**Player** Huh, like the Stone of Jas. I can actually see why you were chosen to find it."] = "**Player** Eh, como la Piedra de Jas. De hecho, puedo entender por qué fuiste elegido para encontrarlo.",
        ["**Player** Is this it, then - the Jolly Boar Inn? What's the power source? Is it beer? Chaos gauntlets? Giant hairy cabbages?"] = "**Player** ¿Es éste entonces el Jolly Boar Inn? ¿Cuál es la fuente de energía? ¿Es cerveza? ¿Guanteletes del caos? ¿Coles peludas gigantes?",
        ["**Movario** Philistine! This isn't the Source itself! My research has led me to this being the entrance to it, or at least AN entrance. Mark my words!"] = "**Movario** ¡Filisteo! ¡Esta no es la Fuente misma! Mi investigación me ha llevado a que esta sea la entrada, o al menos UNA entrada. ¡Recuerda lo que te digo!",
        ["**Player** So what, we all just head inside and start drinking... I don't get it."] = "**Player** Entonces, ¿qué? Todos entramos y comenzamos a beber... No lo entiendo.",
        ["**Movario** Not the Inn, you buffoon. Beneath it! The Jolly Boar is built atop an older building called Star Lodge. My research leads me to believe it was buried by fallout from the Forinthry explosion."] = "**Movario** No en la posada, bufón. ¡Debajo de él! El Jolly Boar está construido sobre un edificio antiguo llamado Star Lodge. Mi investigación me lleva a creer que quedó sepultado por las consecuencias de la explosión de Forinthry.",
        ["**Movario** Guild members have dug out a tunnel going under the Jolly Boar. Start in there and look for...the Source!"] = "**Movario** Los miembros del gremio han excavado un túnel que pasa por debajo del Jolly Boar. Comience allí y busque... ¡la Fuente!",
        ["I want to talk about mysteries."] = "Quiero hablar de misterios.",
        ["Bye."] = "Adiós.",
        ["Farewell, Player."] = "Adiós, Player.",
        ["The only mystery I see is why you haven't made any progress towards finding the Source. Admit it, you've been slacking off in the pub!"] = "El único misterio que veo es por qué no has hecho ningún progreso hacia la búsqueda de la Fuente. Admítelo, ¡has estado holgazaneando en el pub!",
        ["Which mystery would you like to discuss?"] = "¿Qué misterio te gustaría discutir?",
        ["Eyes in Their Stars."] = "Ojos en sus estrellas.",
        ["Embrace the Chaos"] = "Abraza el caos",
        ["Contract Claws"] = "Garras de contrato",
        ["Dagon Bye"] = "Adiós Dagón",
        ["Right, so... I've met a demon at the bottom of the Infernal Source..."] = "Bien, entonces... Me encontré con un demonio en el fondo del Infernal Source...",
        ["Indeed, the workers on the site have been hearing and seeing strange things. You are still alive, however, so what does that mean..."] = "De hecho, los trabajadores en el sitio han estado escuchando y viendo cosas extrañas. Aún estás vivo, sin embargo, ¿qué significa eso...?",
        ["It's an infernal demon named Dagon. It's trapped within the heart of the Source...and it wants my help to break its contract."] = "Es un demonio infernal llamado Dagón. Está atrapado en el corazón de la Fuente... y quiere mi ayuda para romper su contrato.",
        ["He's trapped within a strange cage surrounded by star signs."] = "Está atrapado dentro de una extraña jaula rodeada de signos zodiacales.",
        ["Then I shall leave this in your hands. You have made contact, so you should see this through. Build trust with this Dagon."] = "Entonces dejaré esto en tus manos. Has hecho contacto, por lo que deberías llevarlo a cabo. Genera confianza con este Dagon.",
        ["I've finally managed to discover the 13-digit code needed to free Dagon. Now to figure out how to actually input it..."] = "Finalmente logré descubrir el código de 13 dígitos necesario para liberar a Dagon. Ahora, para descubrir cómo ingresarlo realmente...",
        ["Well, I'm afraid I can't much help. You're a natural at this by now, right? Either way, Dagon can probably assist."] = "Bueno, me temo que no puedo ayudar mucho. Eres natural en esto ahora, ¿verdad? De cualquier manera, Dagon probablemente pueda ayudar.",
        ["I did it! I freed Dagon!"] = "¡Lo logré! ¡Liberé a Dagón!",
        ["Yes, quite! My instruments picked up a spike of activity. Well done, Player."] = "¡Sí, bastante! Mis instrumentos registraron un pico de actividad. Bien hecho, Player.",
        ["What happened with Dagon?"] = "¿Qué pasó con Dagón?",
        ["Ah, yes. Good point. I should probably head back in and talk with it."] = "Ah, sí. Buen punto. Probablemente debería regresar y hablar con él.",
        ["So, any idea what this Pact with Dagon is good for?"] = "Entonces, ¿alguna idea de para qué sirve este Pacto con Dagón?",
        ["It's a very rare and valuable prize, a contract with Dagon is what this is... Contracts with demons were very common back during the God Wars, but even then, not with an infernal!"] = "Es un premio muy raro y valioso, un contrato con Dagon es lo que es... Contracts con demonios era muy común durante las Guerras de Dios, pero incluso entonces, ¡no con un infernal!",
        ["Let's see here... If you sign it, you will gain the ability to summon certain demons under Dagon's command. There are also instructions on here for how to go about doing so."] = "Veamos aquí... Si lo firmas, obtendrás la capacidad de convocar a ciertos demonios bajo el mando de Dagon. También hay instrucciones aquí sobre cómo hacerlo.",
        ["There are no further costs to you either. 'This contract is for services already rendered.' For freeing Dagon and thus breaking his old contract, it will grant you this boon on an ongoing basis."] = "Tampoco tendrás ningún coste adicional. 'Este contrato es para servicios ya prestados.' Por liberar a Dagon y así romper su antiguo contrato, te otorgará esta bendición de forma continua.",
        ["However, there is a cost required for each creature you summon - that's part of the process involved to invoke this contract. The process seems only slightly different from what you and I already understand of Summoning."] = "Sin embargo, se requiere un costo para cada criatura que invocas; eso es parte del proceso involucrado para invocar este contrato. El proceso parece ligeramente diferente de lo que usted y yo ya entendemos de Summoning.",
    },
    ["Mr Ex"] = {
        ["Choose an option:"] = "Elige una opción:",
        ["Wilderness hats"] = "Gorros Wilderness",
        ["Are you heading out into the Wilderness? If so, I have a gift for you."] = "¿Vas a salir al Wilderness? Si es así, tengo un regalo para ti.",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes, I am."] = "Sí, lo soy.",
        ["Wouldn't catch me doing that, oh no. I'll just stay here and give wildstalker helmets to fighters like you."] = "No me pillaría haciendo eso, oh no. Me quedaré aquí y les daré cascos de acechador salvaje a luchadores como tú.",
        ["Once you have the space to carry it that is."] = "Una vez que tengas espacio para llevarlo, claro está.",
        ["[Mr Ex gives you an armoured helmet.]"] = "[Mr Ex te ofrece un casco blindado.]",
        ["I hope this looks after you out there. Wear it with pride."] = "Espero que esto te cuide. Llévalo con orgullo.",
        ["Erm, no."] = "Mmmm, no.",
        ["A [man/lady] after my own heart! Stop here where it's safe."] = "¡Un [man/lady] según mi propio corazón! Detente aquí donde sea seguro.",
        ["You've still got that helmet I gave you? Good stuff. Better you than me out there, I say."] = "¿Aún tienes ese casco que te regalé? Buen material. Mejor tú que yo ahí fuera, digo.",
        ["You've lost your hat, it seems."] = "Parece que has perdido tu sombrero.",
        ["Yes, somewhere out there."] = "Sí, en algún lugar por ahí.",
        ["Well, I don't mind getting it back for you..."] = "Bueno, no me importa devolvértelo...",
        ["It's not in the Wilderness, is it?"] = "No está en Wilderness, ¿verdad?",
        ["That is if you make space to carry it."] = "Eso es si haces espacio para llevarlo.",
        ["Ah, here we go, it's come home to me. Look after it."] = "Ah, allá vamos, ha llegado a casa para mí. Cuídalo.",
        ["Thanks!"] = "¡Gracias!",
        ["Tell me more about this hat, then."] = "Entonces cuéntame más sobre este sombrero.",
        ["While you own this hat, your kills and deaths in the Wilderness will be recorded, as will your most valuable kill and your current kill streak."] = "Mientras tengas este sombrero, se registrarán tus muertes y asesinatos en Wilderness, al igual que tu muerte más valiosa y tu racha de muertes actual.",
        ["You can use your hat to display your achievements by turning yourself into a statue. Others will be able to read your statue's plague and see your statistics."] = "Puedes usar tu sombrero para mostrar tus logros convirtiéndote en una estatua. Otros podrán leer la plaga de tu estatua y ver tus estadísticas.",
        ["If you wish to, you can cause the hat to forget the carnage you've caused, or instruct it not to show certain elements."] = "Si lo deseas, puedes hacer que el sombrero olvide la masacre que causaste o indicarle que no muestre ciertos elementos.",
        ["Handy, thanks!"] = "¡Útil, gracias!",
        ["Farewell."] = "Adiós.",
        ["Hardcore mode"] = "Modo duro",
        ["The gods appear to be turning a blind eye to you. Have you angered them...or was this a path of your choosing?"] = "Los dioses parecen estar haciéndote la vista gorda. ¿Los has enojado... o fue este un camino que elegiste?",
        ["That's why I'm here. I've heard you may be able to help me."] = "Por eso estoy aquí. He oído que tal vez puedas ayudarme.",
        ["Jar of divine light"] = "Jarra de luz divina",
        ["Well, I did find this handy jar of divine light, it's yours if you want it?"] = "Bueno, encontré este práctico frasco de luz divina. ¿Es tuyo si lo quieres?",
        ["You will need to take the jar in order to open it now, otherwise it will automatically activate to save you when you die - even without owning it."] = "Deberás tomar el frasco para poder abrirlo ahora; de lo contrario, se activará automáticamente para salvarte cuando mueras, incluso sin tenerlo.",
        ["The jar of divine light, when used, will disable Hardcore mode. This cannot be undone once used."] = "El frasco de luz divina, cuando se usa, desactivará el modo Extremo. Esto no se puede deshacer una vez utilizado.",
        ["That's great, thanks!"] = "¡Es genial, gracias!",
        ["I'll keep hold of the jar for you. Speak to me again if you want to open it, otherwise I'll open it when it's time for you to meet the gods."] = "Te guardaré el frasco. Háblame de nuevo si quieres abrirlo; de lo contrario, lo abriré cuando llegue el momento de que conozcas a los dioses.",
        ["No thanks, I'll wait until I die."] = "No gracias, esperaré hasta morir.",
        ["You're back about the jar of divine light? You've already taken it. Would you like to open it now?"] = "¿Has vuelto por el frasco de luz divina? Ya lo has tomado. ¿Quieres abrirlo ahora?",
        ["[Opening this jar will envelop you in divine light, showing your presence to the gods. Once the gods are aware of your presence, you will be able to return to the world after death.]"] = "[Abrir este frasco te envolverá en una luz divina, mostrando tu presencia a los dioses. Una vez que los dioses sean conscientes de tu presencia, podrás regresar al mundo después de la muerte.]",
        ["[This will permanently disable Hardcore mode on your account after 7 days, dropping you to an Ironman account. This process cannot be reversed. This item can also be used automatically upon death. Are you sure?]"] = "[Esto desactivará permanentemente el modo Hardcore en tu cuenta después de 7 días y te llevará a una cuenta Ironman. Este proceso no se puede revertir. Este elemento también se puede usar automáticamente al morir. ¿Está seguro?]",
        ["**Disable Hardcore mode?**"] = "**¿Desactivar el modo Extremo?**",
        ["I want to disable Hardcore mode"] = "Quiero desactivar el modo Hardcore",
        ["Try to open the jar of light in 7 days to disable Hardcore mode."] = "Intenta abrir el frasco de luz en 7 días para desactivar el modo Hardcore.",
        ["Cancel"] = "Cancelar",
        ["You have chosen to disable Hardcore mode in [number] days. Do you still wish to disable Hardcore mode?"] = "Has elegido desactivar el modo Hardcore en los días [número]. ¿Aún deseas desactivar el modo Hardcore?",
        ["Disable hardcore mode"] = "Desactivar el modo duro",
        ["Yes, I want to disable Hardcore mode"] = "Sí, quiero desactivar el modo Hardcore",
        ["No, I want to remain in Hardcore mode"] = "No, quiero permanecer en modo Hardcore.",
        ["Disabling Hardcore mode cancelled."] = "Se canceló la desactivación del modo Hardcore.",
        ["Divine coin"] = "moneda divina",
        ["I found this coin. It seems to be exuding divine power. I'd be willing to sell it to you...for a price."] = "Encontré esta moneda. Parece estar exudando poder divino. Estaría dispuesto a vendérselo... por un precio.",
        ["Yes, I think 100,000 coins will do nicely."] = "Sí, creo que 100.000 coins estarán bien.",
        ["You will need to take it with you, wherever you go. Keep it concealed."] = "Tendrás que llevarlo contigo dondequiera que vayas. Mantenlo oculto.",
        ["Should you fall, present the coin to whomever greets you. Meet their gaze without fear, but say nothing...and you shall live once again."] = "Si te caes, presenta la moneda a quien te salude. Encuentra su mirada sin miedo, pero no digas nada... y vivirás una vez más.",
        ["This coin will grant you 1 extra death in Hardcore mode."] = "Esta moneda te otorgará 1 muerte extra en el modo Hardcore.",
        ["Excellent. Let's see..."] = "Excelente. Veamos...",
        ["[Mr Ex hands you the coin. You quickly stow it away.]"] = "[Mr Ex te entrega la moneda. Lo guardas rápidamente.]",
        ["No thanks."] = "No, gracias.",
        ["I found this coin. It seems to be exuding divine power. I'd be willing to sell it to you... for a price. Yes, I think 10,000,000 coins will do nicely."] = "Encontré esta moneda. Parece estar exudando poder divino. Estaría dispuesto a vendérselo... por un precio. Sí, creo que 10.000.000 coins estarán bien.",
        ["I bought an identical coin from you for far cheaper! Why is this so expensive?"] = "¡Te compré una moneda idéntica por mucho más barata! ¿Por qué es esto tan caro?",
        ["Supply and demand, ma'am."] = "Oferta y demanda, señora.",
        ["Fine..."] = "Bien...",
        ["You will need to take it with you, wherever you go. Keep it concealed. Should you fall, present the coin to whomever greets you. Meet their gaze without fear, but say nothing... and you shall live once again."] = "Tendrás que llevarlo contigo dondequiera que vayas. Mantenlo oculto. Si te caes, presenta la moneda a quien te salude. Encuentra su mirada sin miedo, pero no digas nada... y vivirás una vez más.",
        ["Mr Ex hands you the coin. You quickly stow it away."] = "Mr Ex te entrega la moneda. Lo guardas rápidamente.",
        ["Never disable Hardcore Ironman mode"] = "Nunca desactives el modo Hardcore Ironman",
        ["I never want to open the Jar of Divine Light unless I fall in combat. Is this possible?"] = "No quiero abrir nunca el Jarro de la Luz Divina a menos que caiga en combate. ¿Es esto posible?",
        ["I can seal the jar so you can't open it. I'll still be able to open the jar on your behalf should you be on your way to meet the gods."] = "Puedo sellar el frasco para que no puedas abrirlo. Aún podré abrir el frasco en tu nombre si estás en camino a encontrarte con los dioses.",
        ["However, if I do this, I won't sell the Book of Diplomacy to you either. I'd rather sell it to someone who may actually require it."] = "Sin embargo, si hago esto, tampoco te venderé el Libro de la Diplomacia. Prefiero vendérselo a alguien que realmente lo necesite.",
        ["I won't undo this, mind. Once I've sealed your jar, you'll never be able to open it again. Nor will I offer to sell the Book of Diplomacy to you again."] = "No desharé esto, claro. Una vez que haya sellado tu frasco, nunca podrás volver a abrirlo. Tampoco volveré a ofrecerle venderle el Libro de la Diplomacia.",
        ["Never disable Hardcore Ironman mode?"] = "¿Nunca deshabilitas el modo Hardcore Ironman?",
        ["Yes, I never want to disable Hardcore Ironman mode"] = "Sí, nunca quiero desactivar el modo Hardcore Ironman",
        ["Your jar is now sealed."] = "Tu frasco ya está sellado.",
        ["No, I want the option to disable Hardcore Ironman mode"] = "No, quiero la opción de desactivar el modo Hardcore Ironman.",
        ["Ironman mode"] = "modo hombre de hierro",
        ["I'm afraid that I can't sell you this book without selling you this lovely jar I have first."] = "Me temo que no puedo venderte este libro sin venderte primero este hermoso frasco que tengo.",
        ["Hey, I don't mean offence by this, but I'm trying to sell this book."] = "Oye, no quiero ofenderte con esto, pero estoy intentando vender este libro.",
        ["I bought it myself for a decent sum of money, but I have no use for it."] = "Lo compré yo mismo por una buena suma de dinero, pero no lo uso.",
        ["It's a book which teaches the reader about how to interact with others. However, I'd need 50,000 coins to part with it."] = "Es un libro que enseña al lector cómo interactuar con los demás. Sin embargo, necesitaría 50.000 coins para desprenderme de él.",
        ["I've been looking for a book like this..."] = "He estado buscando un libro como este...",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["You don't seem to have enough coins."] = "Parece que no tienes suficiente coins.",
        ["[Mr Ex hands you the book.]"] = "[Mr Ex te entrega el libro.]",
        ["No thanks"] = "No gracias",
        ["I never want to buy this book"] = "Nunca quiero comprar este libro.",
        ["Never means never. I won't offer you this book again. Are you sure you don't want this book?"] = "Nunca significa nunca. No te volveré a ofrecer este libro. ¿Estás seguro de que no quieres este libro?",
        ["I will also seal your Jar of divine light, so only I can open it should you fall."] = "También sellaré tu Jarra de luz divina, para que solo yo pueda abrirla si te caes.",
        ["Never disable ironman mode?"] = "¿Nunca desactivas el modo ironman?",
        ["Yes, I never want to disable Ironman mode"] = "Sí, nunca quiero desactivar el modo Ironman.",
        ["So be it, you'll never see the Book of Diplomacy again."] = "Que así sea, nunca volverás a ver el Libro de la Diplomacia.",
        ["No, I want to be able to cancel Ironman mode"] = "No, quiero poder cancelar el modo Ironman.",
        ["I never want to read the book of diplomacy, ever! I don't know why I bought it."] = "¡Nunca quiero leer el libro de diplomacia! No sé por qué lo compré.",
        ["I'll take it back off you then."] = "Entonces te lo quitaré.",
        ["Task System"] = "Sistema de tareas",
        ["Tell me about the Task System."] = "Cuéntame sobre el sistema de tareas.",
        ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["For completing the Wilderness set, you are presented with Wilderness sword."] = "Por completar el conjunto Wilderness, se te presenta la espada Wilderness.",
        ["This sword will become increasingly useful with each difficulty level of the set that you complete."] = "Esta espada será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
        ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
        ["You may also select a set Task (denoted in the main Task System interface by a small shield icon) and choose 'Rewards' to see what rewards a set item provides."] = "También puede seleccionar una tarea determinada (indicada en la interfaz principal del sistema de tareas mediante un pequeño icono de escudo) y elegir 'Recompensas' para ver qué recompensas proporciona un elemento determinado.",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["You need to complete all the Tasks in the set of a particular difficulty, then you can claim your reward. Most of the Wilderness set's Tasks are straightforward, although you might find some require quests to be"] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Wilderness son sencillas, aunque es posible que algunas requieran misiones.",
        ["started, if not finished."] = "iniciado, si no terminado.",
        ["To claim the Wilderness set reward, speak to Mandrith, Quercus, Kolodion or myself."] = "Para reclamar la recompensa del conjunto Wilderness, habla con Mandrith, Quercus, Kolodion o conmigo mismo.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
        ["You don't have any more rewards to claim!"] = "¡Ya no tienes más recompensas para reclamar!",
        ["I've completed all the tasks in the easy Wilderness task set."] = "He completado todas las tareas del sencillo conjunto de tareas Wilderness.",
        ["Well done Player, I've kept some rewards aside for you."] = "Bien hecho Player, he reservado algunas recompensas para ti.",
        ["I'm afraid you don't have enough inventory space to claim all your rewards. Speak to me again when you have 3 spaces."] = "Me temo que no tienes suficiente espacio en el inventario para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 3 espacios.",
        ["[You are given some rewards for completing the easy Wilderness task set!]"] = "[¡Recibirás algunas recompensas por completar el sencillo conjunto de tareas Wilderness!]",
        ["There you go, looks like that's everything."] = "Ahí lo tienes, parece que eso es todo.",
        ["I lost the Wilderness sword 1 you gave me..."] = "Perdí la espada Wilderness 1 que me diste...",
        ["Lucky for you I have a spare... I'm afraid it's going to cost you 50,000 coins though."] = "Por suerte para ti, tengo uno de repuesto... Aunque me temo que te costará 50.000 coins.",
        ["Reclaim for 50,000 coins?"] = "¿Reclamar 50.000 coins?",
        ["Yes."] = "Sí.",
        ["But it doesn't look like you have enough money for that. Come back to me when you do."] = "Pero no parece que tengas suficiente dinero para eso. Vuelve conmigo cuando lo hagas.",
        ["[You're handed another Wilderness sword 1.]"] = "[Te entregan otra espada Wilderness 1.]",
        ["I lost the Wilderness sword 4."] = "Perdí la espada Wilderness 4.",
        ["Lucky for you I have a spare... I'm afraid it's going to cost you 100,000 coins though."] = "Por suerte para ti, tengo uno de repuesto... Aunque me temo que te va a costar 100.000 coins.",
        ["Reclaim for 100,000 coins?"] = "¿Reclamar 100.000 coins?",
        ["[You're handed another Wilderness sword 4.]"] = "[Te entregan otra espada Wilderness 4.]",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Wilderness sword 1"] = "Wilderness espada 1",
        ["Wilderness sword 1? Yes, but I'm afraid it would cost you 50,000 coins."] = "Wilderness espada 1? Sí, pero me temo que te costaría 50.000 coins.",
        ["Purchase another for 50,000 coins?"] = "¿Comprar otro por 50.000 coins?",
        ["Yes"] = "si",
        ["Wilderness sword 2"] = "Wilderness espada 2",
        ["Wilderness sword 2? Yes, but I'm afraid it would cost you 65,000 coins."] = "Wilderness espada 2? Sí, pero me temo que te costaría 65.000 coins.",
        ["Purchase another for 65,000 coins?"] = "¿Comprar otro por 65.000 coins?",
        ["[You're handed another Wilderness sword 2.]"] = "[Te entregan otra espada Wilderness 2.]",
        ["Wilderness sword 3"] = "Wilderness espada 3",
        ["Wilderness sword 3? Yes, but I'm afraid it would cost you 80,000 coins."] = "Wilderness espada 3? Sí, pero me temo que te costaría 80.000 coins.",
        ["Purchase another for 80,000 coins?"] = "¿Comprar otro por 80.000 coins?",
        ["[You're handed another Wilderness sword 3.]"] = "[Te entregan otra espada Wilderness 3.]",
        ["Wilderness sword 4"] = "Wilderness espada 4",
        ["Wilderness sword 4? Yes, but I'm afraid it would cost you 100,000 coins."] = "Wilderness espada 4? Sí, pero me temo que te costaría 100.000 coins.",
        ["Purchase another for 100,000 coins?"] = "¿Comprar otro por 100.000 coins?",
    },
    ["Mr Mordaut"] = {
        ["*(Only on first time:)*"] = "*(Sólo la primera vez:)*",
        ["Ah, a visitor! Do come in!"] = "¡Ah, un visitante! ¡Entra!",
        ["Yes, I'm a dragon...but don't be alarmed. I'm not going to eat you."] = "Sí, soy un dragón... pero no te alarmes. No te voy a comer.",
        ["You...work at the museum? A dragon...works here?"] = "¿Tú... trabajas en el museo? ¿Un dragón... trabaja aquí?",
        ["Why, of course, dear [chap/lady]! My name is Mr Mordaut. I'm the resident expert on UN-natural history - and dragonkind, of course."] = "¡Por supuesto, querido [chap/lady]! Mi nombre es Mr Mordaut. Soy el experto residente en historia natural de la ONU y en dragones, por supuesto.",
        ["I also curate the museum's coin collection. I have an Avarrocka guinea, you know - very rare and valuable!"] = "También soy curador de la colección de monedas del museo. Tengo una guinea Avarrocka, ¿sabes? ¡Muy rara y valiosa!",
        ["Did you used to do something else before this?"] = "¿Solías hacer algo más antes de esto?",
        ["Ah, yes - you may remember me from my teaching days! I've seen so many pupils come through my class, I can't recall all their names and faces."] = "Ah, sí. ¡Quizás me recuerdes de mis días de profesora! He visto a tantos alumnos pasar por mi clase que no puedo recordar todos sus nombres y caras.",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["Choose an option:"] = "Elige una opción:",
        ["I am terribly sorry, Player, but you're not quite experienced enough to take on this quest."] = "Lo siento muchísimo, Player, pero no tienes la experiencia suficiente para emprender esta misión.",
        ["About your office..."] = "Sobre tu oficina...",
        ["It feels like it's bigger on the inside than on the outside..."] = "Se siente como si fuera más grande por dentro que por fuera...",
        ["Ah, that's because it is! Dimensional architecture, see? My office is actually in a pocket universe, much like some of your human houses."] = "¡Ah, eso es porque lo es! Arquitectura dimensional, ¿ves? En realidad, mi oficina está en un universo de bolsillo, muy parecido a algunas de sus casas humanas.",
        ["The door to my office is actually a portal, but then technically speaking - all doors are. Hahaha!"] = "La puerta de mi oficina es en realidad un portal, pero técnicamente hablando, todas las puertas lo son. ¡Jajaja!",
        ["But if that's the case, why isn't your office...bigger?"] = "Pero si ese es el caso, ¿por qué tu oficina no es... más grande?",
        ["Budgetary cutbacks."] = "Recortes presupuestarios.",
        ["What's your role at the museum?"] = "¿Cuál es tu papel en el museo?",
        ["I head the museum's Unnatural History department. I perform much the same function as the natural historians, but I focus on the more...unusual species."] = "Dirijo el departamento de Historia Antinatural del museo. Realizo prácticamente la misma función que los historiadores naturales, pero me concentro en las especies más... inusuales.",
        ["Mythical beasts, sentient plants, dimensional anomalies those sorts of things."] = "Bestias míticas, plantas sensibles, anomalías dimensionales, ese tipo de cosas.",
        ["Though I leave the more social side of the job to my human counterparts. There aren't many museum visitors who wouldn't flee for their lives upon coming face to face with a dragon!"] = "Aunque dejo el lado más social del trabajo a mis homólogos humanos. ¡No hay muchos visitantes del museo que no huirían para salvar sus vidas al encontrarse cara a cara con un dragón!",
        ["Not even one as erudite and cultured as I."] = "Ni siquiera uno tan erudito y culto como yo.",
        ["I can see how that might be awkward for you."] = "Puedo ver que eso podría resultar incómodo para ti.",
        ["Indeed! When a visiting human child accidentally comes in here, I have to pretend I'm one of the displays in storage."] = "¡Efectivamente! Cuando un niño humano visitante entra aquí accidentalmente, tengo que fingir que soy una de las exhibiciones almacenadas.",
        ["Though I do occasionally 'spring to life' to give them a scare! Hahaha."] = "¡Aunque de vez en cuando \"cobro vida\" para darles un susto! Jajaja.",
        ["Tell me about dragons."] = "Háblame de dragones.",
        ["Ah, my draconic brethren...though I am unique among them."] = "Ah, mis hermanos dracónicos... aunque yo soy único entre ellos.",
        ["It isn't common knowledge to humans that dragons are a sentient species. While most of us are beastly, we are not beasts."] = "Los humanos no saben que los dragones son una especie sensible. Si bien la mayoría de nosotros somos bestias, no somos bestias.",
        ["Although I'll admit that most of my kind are also not blessed with much in the way of intelligence."] = "Aunque admito que la mayoría de los de mi especie tampoco están bendecidos con mucha inteligencia.",
        ["Are you the exception?"] = "¿Eres la excepción?",
        ["You think me intelligent? How kind of you to say! But no - there are a handful of others, the most famous being the King Black Dragon."] = "¿Me crees inteligente? ¡Qué amable de tu parte decirlo! Pero no, hay muchos otros, siendo el más famoso el Rey Dragón Negro.",
        ["But most of us are base creatures, relishing in rage-fuelled carnage."] = "Pero la mayoría de nosotros somos criaturas viles que disfrutamos de una matanza alimentada por la ira.",
        ["Any other interesting dragon facts?"] = "¿Algún otro dato interesante sobre dragones?",
        ["Hmm, let me see..."] = "Hmm, déjame ver...",
        ["Oh, all dragons are capable of speech, though the aforementioned lack of intelligence, coupled with our aggressive nature, means discourse is rarely our first recourse..."] = "Oh, todos los dragones son capaces de hablar, aunque la falta de inteligencia antes mencionada, junto con nuestra naturaleza agresiva, significa que el discurso rara vez es nuestro primer recurso...",
        ["...and humans often our main course. Haha!"] = "...y los humanos a menudo nuestro plato principal. ¡Ja ja!",
        ["Though I would like to state that I myself am cheegan. I only eat cheese and cheese-related products. I had some lovely Red Lumbridge with crackers the other day."] = "Aunque me gustaría afirmar que yo mismo soy cheegan. Sólo como queso y productos relacionados con el queso. El otro día comí un delicioso Red Lumbridge con galletas saladas.",
        ["Can you tell me about dragonkin?"] = "¿Puedes hablarme sobre los dragonantes?",
        ["*(If you not yet have talked to him about each dragonkin subject at least once:)*"] = "*(Si aún no has hablado con él sobre cada tema dragonkin al menos una vez:)*",
        ["What sort of professor would I be if I just gave you all the answers? If, however, you perform your own research and bring me your findings, I shall reward you with further insight, and perhaps a more tangible reward too."] = "¿Qué clase de profesor sería si te diera todas las respuestas? Sin embargo, si realiza su propia investigación y me trae sus hallazgos, lo recompensaré con más información y quizás también con una recompensa más tangible.",
        ["*(If you have discussed all the topics you have available with him:)*"] = "*(Si has discutido todos los temas que tienes disponibles con él :)*",
        ["Now, tell me what YOU know of them..."] = "Ahora, dime lo que TÚ sabes de ellos...",
        ["*(If you have completed A Tale of Two Cats)* Robert the Strong (A Tail of Two Cats)."] = "*(Si has completado Un cuento de dos gatos)* Robert el Fuerte (Un cuento de dos gatos).",
        ["I've met the reincarnation of a famous hero - Robert the Strong - who once killed a dragonkin!"] = "¡Conocí la reencarnación de un héroe famoso, Robert el Fuerte, que una vez mató a un dragonante!",
        ["Well, have you indeed? How fascinating!"] = "Bueno, ¿verdad? ¡Qué fascinante!",
        ["I have long known that us dragons are extremely long-lived. Combat is the means by which most dragons succumb to death."] = "Hace tiempo que sé que los dragones somos extremadamente longevos. El combate es el medio por el cual la mayoría de los dragones sucumben a la muerte.",
        ["I'm certain our dragonkin progenitors have even longer lifespans and power, which makes it all the more remarkable that a lone human could defeat one."] = "Estoy seguro de que nuestros progenitores dragonantes tienen una vida útil y un poder aún más largos, lo que hace que sea aún más notable que un humano solitario pueda derrotar a uno.",
        ["Wait, are you saying dragons are descended from the dragonkin?"] = "Espera, ¿estás diciendo que los dragones descienden de los dragonantes?",
        ["Ahem. Well...er...that is to say, there are those of us who suspect as much. The similarity in the species names suggests at least an etymological link."] = "Ejem. Bueno…eh…es decir, hay quienes lo sospechamos. La similitud en los nombres de las especies sugiere al menos un vínculo etimológico.",
        ["*(If you have completed Ritual of the Mahjarrat)* Stone of Jas (Ritual of the Mahjarrat)."] = "*(Si has completado Ritual del Mahjarrat)* Piedra de Jas (Ritual del Mahjarrat).",
        ["I've discovered that the dragonkin are in some way tied to the Stone of Jas, a powerful artefact that once belonged to an elder god!"] = "¡He descubierto que los dragonantes están de alguna manera vinculados a la Piedra de Jas, un poderoso artefacto que una vez perteneció a un dios anciano!",
        ["My word! Historical documents on the dragonkin suggest that they only appear in the world in times of strife, though there is much debate as to whether they are the strife or if their arrival is what puts a stop to it."] = "¡Mi palabra! Los documentos históricos sobre los dragonantes sugieren que sólo aparecen en el mundo en tiempos de conflicto, aunque hay mucho debate sobre si son el conflicto o si su llegada es lo que lo detiene.",
        ["Either way, the scant few remaining survivor accounts suggest that the dragonkin leave a wake of destruction behind them."] = "De cualquier manera, los pocos relatos de supervivientes que quedan sugieren que los dragonantes dejan una estela de destrucción tras ellos.",
        ["Perhaps they are some kind of safeguard against misuse of the artefact."] = "Quizás sean algún tipo de protección contra el mal uso del artefacto.",
        ["What an intriguing theory..."] = "Qué teoría tan intrigante...",
        ["*(If you have defeated the King Black Dragon)*  Dragon riders (Killed KBD)."] = "*(Si has derrotado al Rey Dragón Negro)* Jinetes de dragones (Killed KBD).",
        ["I've fought the King Black Dragon! Do you know much about the fabled dragon riders?"] = "¡He luchado contra el Rey Dragón Negro! ¿Sabes mucho sobre los legendarios jinetes de dragones?",
        ["That is most remarkable!"] = "¡Eso es de lo más extraordinario!",
        ["We dragons don't follow typical notions of monarchism, but our King is to be both feared and respected."] = "Nosotros, los dragones, no seguimos las nociones típicas del monarquismo, pero nuestro Rey debe ser temido y respetado.",
        ["As for these 'dragon riders', they too were deserving of respect, but it was their fearsome reputation that ultimately led to their downfall."] = "En cuanto a estos 'jinetes de dragones', ellos también merecían respeto, pero fue su temible reputación lo que finalmente los llevó a su caída.",
        ["Although my kind and theirs did not have a common ancestry, we did share an affinity. This was perhaps due to our similarly reptilian taxonomy."] = "Aunque mi especie y la de ellos no tenían una ascendencia común, sí compartíamos una afinidad. Esto quizás se debió a nuestra taxonomía similar a la de los reptiles.",
        ["Indeed, they were originally the antithesis of my brethren - gentle and kind. It is a tragedy that their once peaceful race was exposed to the atrocities of war."] = "De hecho, originalmente eran la antítesis de mis hermanos: gentiles y amables. Es una tragedia que su raza, una vez pacífica, haya quedado expuesta a las atrocidades de la guerra.",
        ["Their race had another name once. I only hope that some of them chose not to come and fight our wars, and to this day live on in peace and harmony in their home realm."] = "Su raza alguna vez tuvo otro nombre. Sólo espero que algunos de ellos decidan no venir a pelear nuestras guerras y hasta el día de hoy vivir en paz y armonía en su reino natal.",
        ["*(If you have defeated the Queen Black Dragon)*  Kerapac's journal (Killed QBD)."] = "*(Si has derrotado a la Reina Dragón Negro)* Diario de Kerapac (Mató a QBD).",
        ["I've discovered the Queen Black Dragon residing below Rimmington."] = "Descubrí que la Reina Dragón Negro reside debajo de Rimmington.",
        ["I found a journal there that suggests all dragons were created by the dragonkin as some sort of experiment!"] = "¡Encontré un diario allí que sugiere que todos los dragones fueron creados por dragonantes como una especie de experimento!",
        ["They - well, you too, I suppose - were supposed to be a way for the dragonkin to free themselves from their link to the Stone of Jas."] = "Se suponía que ellos (bueno, tú también, supongo) eran una forma para que los dragonantes se liberaran de su vínculo con la Piedra de Jas.",
        ["But they were deemed failures: too brutish, slaves to anger, or lacking in intelligence or power."] = "Pero fueron considerados fracasos: demasiado brutales, esclavos de la ira o carentes de inteligencia o poder.",
        ["The queen is still alive? Well, I never!"] = "¿La reina sigue viva? ¡Pues yo nunca!",
        ["But how does that explain you? You're intelligent and you've never so much as hurt my feelings, let alone try to eat me."] = "¿Pero cómo te explica eso? Eres inteligente y nunca has herido mis sentimientos, y mucho menos has intentado comerme.",
        ["*sigh* It's not something I like to talk about, but I suppose as you've uncovered this much on your own..."] = "*suspiro* No es algo de lo que me guste hablar, pero supongo que como has descubierto todo esto por tu cuenta...",
        ["I too am a creation of the dragonkin, though before I was old enough to comprehend the world, my creator had left. I never knew them."] = "Yo también soy una creación de los dragonantes, aunque antes de tener la edad suficiente para comprender el mundo, mi creador se había ido. Nunca los conocí.",
        ["And I, too, was deemed a failure."] = "Y yo también fui considerado un fracaso.",
        ["My creator's name was Taraket, who fused an egg from the queen with something called a fairy dragon. I was the result."] = "El nombre de mi creador era Taraket, quien fusionó un huevo de la reina con algo llamado dragón de hadas. Yo fui el resultado.",
        ["My failure was that I went too far the other way. While my brethren were too aggressive, I had no aggression whatsoever; no desire to harm others."] = "Mi fracaso fue que fui demasiado lejos en el otro sentido. Mientras mis hermanos eran demasiado agresivos, yo no tenía agresión alguna; ningún deseo de dañar a otros.",
        ["Where they had power, I had none. Even to this day, I can muster no more than a spit of dragonfire."] = "Donde ellos tenían poder, yo no tenía ninguno. Incluso hasta el día de hoy, no puedo reunir más que un escupitajo de fuego de dragón.",
        ["So while I may possess the mental prowess the dragonkin desired from their progeny, I was barely even a dragon in my creator's eyes."] = "Entonces, si bien puedo poseer la destreza mental que los dragonantes deseaban de su progenie, apenas era un dragón a los ojos de mi creador.",
        ["I tried, in my youth, to prove the voice in those journals wrong, but after half-chewing my first adventurer I spat it out - it just felt wrong."] = "Intenté, en mi juventud, demostrar que la voz de esos diarios estaba equivocada, pero después de medio masticar a mi primer aventurero, la escupí; simplemente me sentí mal.",
        ["Those that can, do', so the saying goes. But I could not...and so I chose to become a teacher! I set out to lead others to their true destiny."] = "El que puede, hace', dice el refrán. Pero no pude... ¡y por eso elegí ser maestra! Me propuse llevar a otros a su verdadero destino.",
        ["What should I research?"] = "¿Qué debo investigar?",
        ["Perhaps there's some clue within an ancient tale of heroism."] = "Quizás haya alguna pista en una antigua historia de heroísmo.",
        ["To talk about this with Mr Mordaut, you must complete the 'A Tail of Two Cats' quest."] = "Para hablar de esto con Mr Mordaut, debes completar la misión 'Una cola de dos gatos'.",
        ["You might possibly gain some first hand experience some day."] = "Es posible que algún día adquieras experiencia de primera mano.",
        ["To talk about this with Mr Mordaut, you must complete the 'Ritual of the Mahjarrat' quest."] = "Para hablar de esto con Mr Mordaut, debes completar la misión 'Ritual del Mahjarrat'.",
        ["You'd probably learn something from defeating the King Black Dragon."] = "Probablemente aprenderías algo al derrotar al Rey Dragón Negro.",
        ["To talk about this with Mr Mordaut, you must either kill the King Black Dragon at least once, or have already received the 'Last Riders' book drop!"] = "Para hablar de esto con Mr Mordaut, debes matar al Rey Dragón Negro al menos una vez o haber recibido ya el libro 'Last Riders'.",
        ["You could also do some research into the Queen Black Dragon."] = "También puedes investigar un poco sobre la Reina Dragón Negro.",
        ["To talk about this with Mr Mordaut, you must have beaten the Queen Black Dragon at least once (and received Kerapac's first journal)!"] = "¡Para hablar de esto con Mr Mordaut, debes haber vencido a la Reina Dragón Negro al menos una vez (y haber recibido el primer diario de Kerapac)!",
        ["Enough about dragonkin."] = "Ya basta de dragonantes.",
        ["I must be going."] = "Debo irme.",
        ["My office door is always open - figuratively speaking, of course. If you learn of any interesting facts about dragonkind, please do come and tell me of it."] = "La puerta de mi oficina siempre está abierta, en sentido figurado, por supuesto. Si aprendes algún dato interesante sobre los dragones, por favor ven y cuéntamelo.",
        ["Your research has been most diligent. You know more of my progenitors than I do! Here, accept your prize."] = "Su investigación ha sido muy diligente. ¡Sabes más de mis progenitores que yo! Toma, acepta tu premio.",
        ["[Mr Mordaut hands you a dragonkin-styled reward lamp.]"] = "[Mr Mordaut te entrega una lámpara de recompensa estilo dragonkin.]",
        ["I guess I should have always expected us to arrive safely with you on this expedition, Player. Another heroic performance by you!"] = "Supongo que siempre debí haber esperado que llegáramos sanos y salvos contigo en esta expedición, Player. ¡Otra actuación heroica tuya!",
        ["Thanks. So, now that we're here, what is next?"] = "Gracias. Entonces, ahora que estamos aquí, ¿qué sigue?",
        ["Now we pause for breath. This is a dangerous place...and it is certainly not what I expected to find."] = "Ahora hacemos una pausa para respirar. Este es un lugar peligroso... y ciertamente no es lo que esperaba encontrar.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["The climate. The animals. The plant life. We are too far north for any of this to be viable."] = "El clima. Los animales. La vida vegetal. Estamos demasiado al norte para que algo de esto sea viable.",
        ["It's almost like it is from a different time period entirely. We can't call it Fossil Island any more, that is for sure."] = "Es casi como si perteneciera a un período de tiempo completamente diferente. Ya no podemos llamarla Isla Fósil, eso es seguro.",
        ["What should we call it then?"] = "¿Cómo deberíamos llamarlo entonces?",
        ["Hmm... I have an idea."] = "Hmm... Tengo una idea.",
        ["Anachronia. The Land Out of Time."] = "Anacronía. La tierra fuera del tiempo.",
        ["There is much to learn here and it will take time to understand what is truly going on here."] = "Hay mucho que aprender aquí y llevará tiempo comprender lo que realmente está sucediendo aquí.",
        ["For now this will serve as a base of operations. We can fortify our position and learn the landscape before we press onwards."] = "Por ahora esto servirá como base de operaciones. Podemos fortalecer nuestra posición y conocer el paisaje antes de seguir adelante.",
        ["*(After the first time:)*"] = "*(Después de la primera vez:)*",
        ["Hello there, Player."] = "Hola, Player.",
        ["Choose topic."] = "Elige tema.",
        ["Anachronia."] = "Anacronía.",
        ["Select An Option"] = "Selecciona una opción",
        ["Ask about Desperate Measures."] = "Pregunte sobre medidas desesperadas.",
        ["Ask about something else."] = "Pregunta por otra cosa.",
        ["How can I help?"] = "¿Cómo puedo ayudar?",
        ["Be here. Be strong. Be prepared."] = "Estar aquí. Sé fuerte. Estar listo.",
        ["We have entered a hostile environment, woefully under-prepared, but ready to make the sacrifices necessary to survive."] = "Hemos entrado en un entorno hostil, lamentablemente mal preparados, pero dispuestos a hacer los sacrificios necesarios para sobrevivir.",
        ["The island is full of threats and danger that could put an end to your life if you drop your guard."] = "La isla está llena de amenazas y peligros que podrían poner fin a tu vida si bajas la guardia.",
        ["Help us build up the base camp and form a defence, ready for whatever comes next."] = "Ayúdanos a construir el campamento base y formar una defensa, listos para lo que venga después.",
        ["What are your plans?"] = "¿Cuales son tus planes?",
        ["First, I wish to ensure all those that travel here are safe. We should fortify this base camp to ensure those in our care are protected. I hope I can rely on your assistance here."] = "Primero, deseo asegurarme de que todos aquellos que viajan aquí estén seguros. Deberíamos fortificar este campamento base para garantizar que quienes están bajo nuestro cuidado estén protegidos. Espero poder contar con su ayuda aquí.",
        ["After that we prepare for whatever happens next."] = "Después de eso nos preparamos para lo que suceda a continuación.",
        ["There are larger plans at work; we should never lose sight of that. However, this island provides us with a unique opportunity to learn."] = "Hay planes más amplios en marcha; Nunca debemos perder eso de vista. Sin embargo, esta isla nos brinda una oportunidad única de aprender.",
        ["I strongly recommend you use this time to your own advantage as well. Who knows what treasures are out there waiting to be discovered. Maybe there is even a pile of gold to retire on!"] = "Te recomiendo encarecidamente que utilices este tiempo también para tu propio beneficio. Quién sabe qué tesoros hay esperando a ser descubiertos. ¡Quizás incluso haya un montón de oro para jubilarse!",
        ["How does it feel to be out of an office again?"] = "¿Cómo se siente estar nuevamente fuera de una oficina?",
        ["It has been far too long. A dragon needs to stretch his wings from time to time."] = "Ha pasado demasiado tiempo. Un dragón necesita estirar sus alas de vez en cuando.",
        ["My long tenure in the Unnatural History department makes me a perfect candidate for an island such as this."] = "Mi larga permanencia en el departamento de Historia Antinatural me convierte en un candidato perfecto para una isla como esta.",
        ["Take a second to think about the opportunities this presents! An island outside of time! There is so much we can discover!"] = "¡Tómate un segundo para pensar en las oportunidades que esto presenta! ¡Una isla fuera del tiempo! ¡Hay tanto que podemos descubrir!",
        ["Several of the archaeologists shared my excitement and were bashing my door down as soon as they heard of the plans to sail here."] = "Varios de los arqueólogos compartieron mi entusiasmo y derribaron mi puerta tan pronto como se enteraron de los planes de navegar hasta aquí.",
        ["Well good luck! I hope you make all the discoveries you dreamed of."] = "¡Buena suerte! Espero que hagas todos los descubrimientos que soñaste.",
        ["Did you see those creatures?"] = "¿Viste esas criaturas?",
        ["Fascinating creatures, aren't they?"] = "Criaturas fascinantes, ¿no?",
        ["I have my theories of what they are but further study will be required."] = "Tengo mis teorías sobre cuáles son, pero será necesario realizar más estudios.",
        ["What is clear, however, is that they are extremely dangerous and should be treated with the utmost caution."] = "Lo que está claro, sin embargo, es que son extremadamente peligrosos y deben tratarse con la máxima precaución.",
        ["I think you're right. At least this base camp seems safe."] = "Creo que tienes razón. Al menos este campamento base parece seguro.",
        ["For now, yes. But we must stay vigilant at all times. Don't worry, King Roald provided us with a number of guards who should keep the camp safe."] = "Por ahora, sí. Pero debemos permanecer alerta en todo momento. No te preocupes, King Roald nos proporcionó varios guardias que deberían mantener el campamento seguro.",
        ["I should go."] = "Debería irme.",
        ["Look after yourself out there, Player."] = "Cuídate, Player.",
        ["Orthen Dig Site."] = "Sitio de excavación de Orthen.",
        ["Welcome to the Orthen Dig Site!"] = "¡Bienvenido al sitio de excavación de Orthen!",
        ["You need 90 Archaeology to access this site."] = "Necesita 90 Archaeology para acceder a este sitio.",
        ["A cutscene will be played shortly and you have some audio settings muted. Would you like to hear the speech?"] = "En breve se reproducirá una escena y algunas configuraciones de audio estarán silenciadas. ¿Quieres escuchar el discurso?",
        ["Select an Option"] = "Selecciona una opción",
        ["Why are you the site manager here?"] = "¿Por qué eres el administrador del sitio aquí?",
        ["Well, I think that should be obvious! My role at the museum is that of Unnatural Historian, but I am also our resident expert on the dragonkin."] = "Bueno, ¡creo que debería ser obvio! Mi función en el museo es la de Historiador antinatural, pero también soy nuestro experto residente en dragonantes.",
        ["Of course, we did not know that we would find all of these dinosaurs here, nor for certain that there would be dragonkin ruins, but for the latter part, at least, I had a strong suspicion."] = "Por supuesto, no sabíamos que encontraríamos todos estos dinosaurios aquí, ni con certeza que habría ruinas de dragonantes, pero al menos en lo último, tenía una fuerte sospecha.",
        ["Why's that?"] = "¿Por qué?",
        ["Why, my research, of course. Dragonkin had to come from somewhere. Many reports had them flying in from 'the east'."] = "Vaya, mi investigación, por supuesto. Dragonkin tenía que venir de alguna parte. Muchos informes los decían volando desde \"el este\".",
        ["It turns out, however, that this island has long been abandoned by the dragonkin, so it appears these two things are not related. Not to mention this instantiation of the island is actually from our own pre-history, which doubly complicates matters."] = "Sin embargo, resulta que esta isla ha sido abandonada hace mucho tiempo por los dragonantes, por lo que parece que estas dos cosas no están relacionadas. Sin mencionar que esta instanciación de la isla proviene en realidad de nuestra propia prehistoria, lo que complica doblemente las cosas.",
        ["So I have simply chalked it all up to being a happy accident, and that I just happen to be in the right place at the, er, right time."] = "Así que simplemente lo atribuí a que fue un feliz accidente y que casualmente estoy en el lugar correcto en el momento correcto.",
        ["What is this dig site about?"] = "¿De qué se trata este sitio de excavación?",
        ["Orthen is the ruins of a dragonkin city built on this island we have named Anachronia. The island's actual name from back then is unknown, but may also just have been simply Orthen Island or some such. Regardless, the island's name is unimportant."] = "Orthen son las ruinas de una ciudad dragonante construida en esta isla que hemos llamado Anacronia. Se desconoce el nombre real de la isla en aquel entonces, pero es posible que también haya sido simplemente Isla Orthen o algo así. De todos modos, el nombre de la isla no tiene importancia.",
        ["What is important, however, is that these are the most preserved and complete dragonkin settlement ruins ever discovered. Also, the first and only of such ruins!"] = "Lo importante, sin embargo, es que estas son las ruinas de asentamientos dragonantes más conservadas y completas jamás descubiertas. Además, ¡la primera y única de esas ruinas!",
        ["This gives us an incredibly rare opportunity to learn what they were like as a people before they succumbed to their unfortunate fate as pawns of the elder gods."] = "Esto nos brinda una oportunidad increíblemente única de aprender cómo eran como pueblo antes de sucumbir a su desafortunado destino como peones de los dioses mayores.",
        ["What about the various dragonkin facilities I've encountered?"] = "¿Qué pasa con las diversas instalaciones dragonkin que he encontrado?",
        ["I believe any encountered before now are all post-curse constructions, though there is still some debate surrounding the castle ruins sat atop Daemonheim."] = "Creo que todas las encontradas hasta ahora son construcciones posteriores a la maldición, aunque todavía hay cierto debate en torno a las ruinas del castillo que se encuentran encima de Daemonheim.",
        ["So, where should I start?"] = "Entonces, ¿por dónde debería empezar?",
        ["Well, there are two areas immediately accessible - my team here have been working hard to gain access to them."] = "Bueno, hay dos áreas a las que se puede acceder inmediatamente; mi equipo ha estado trabajando arduamente para obtener acceso a ellas.",
        ["First are the crypts built into the south-west of the volcano here. To find them, first travel west out of base camp, then north to the volcano."] = "Primero están las criptas construidas aquí en el suroeste del volcán. Para encontrarlos, primero viaja hacia el oeste fuera del campamento base y luego hacia el norte hasta el volcán.",
        ["There is also some sort of small outpost in the north-east of the island. It's trickier to reach, but I'm sure you're capable."] = "También hay una especie de pequeño puesto de avanzada en el noreste de la isla. Es más complicado de alcanzar, pero estoy seguro de que eres capaz.",
        ["I do have a third team attempting to gain access to the large temple ruins on the south-east island, where Laniakea has been exploring, but they have so far been unsuccessful."] = "Tengo un tercer equipo que intenta acceder a las ruinas del gran templo en la isla sureste, donde Laniakea ha estado explorando, pero hasta ahora no han tenido éxito.",
        ["At each of these three sites, the teams have uncovered strange devices. Indeed, there is also one here at base camp, just down the stairs in front of me. You should inspect the one at the crypts first; the team there are close to understanding it, I hear."] = "En cada uno de estos tres sitios, los equipos han descubierto dispositivos extraños. De hecho, también hay uno aquí en el campamento base, justo bajando las escaleras frente a mí. Primero debes inspeccionar el que está en las criptas; He oído que el equipo está cerca de entenderlo.",
        ["There have also been some strange readings from somewhere south of here, but no entrances have been discovered yet in any ruins."] = "También ha habido algunas lecturas extrañas desde algún lugar al sur de aquí, pero aún no se han descubierto entradas en ninguna ruina.",
        ["The team have plenty of rumours flying around as to what we'll find here - of a complete undercity, of a contained evil, of a large hoard of gold and"] = "El equipo tiene muchos rumores sobre lo que encontraremos aquí: una ciudad subterránea completa, un mal contenido, un gran tesoro de oro y",
        ["treasure. That last one I find personally offensive - dragons hoard treasure, not dragonkin, and even then not all dragons. My own hoard is quite modest; it's more akin to a trove, in point of fact."] = "tesoro. Esto último lo encuentro personalmente ofensivo: los dragones atesoran tesoros, no los dragonantes, y aun así no todos los dragones. Mi propio tesoro es bastante modesto; De hecho, es más parecido a un tesoro.",
        ["Okay, so, crypts or outpost first! Perhaps I can find a way to enter the other sites in one of those..."] = "Bien, entonces, ¡criptas o puestos avanzados primero! Quizás pueda encontrar una manera de ingresar a los otros sitios en uno de esos...",
        ["I want to talk about mysteries."] = "Quiero hablar de misterios.",
        ["Bye."] = "Adiós.",
        ["Fare thee well."] = "Que te vaya bien.",
        ["Hmm, we are still struggling to make much headway gaining access to Orthen's ruins. You should head to the crypts west of here to see what you can discover..."] = "Hmm, todavía estamos luchando por avanzar mucho para acceder a las ruinas de Orthen. Deberías dirigirte a las criptas al oeste de aquí para ver qué puedes descubrir...",
        ["Which mystery would you like to discuss?"] = "¿Qué misterio te gustaría discutir?",
        ["Teleport Node On."] = "Nodo de teletransporte activado.",
        ["Know Thy Measure."] = "Conoce tu medida.",
        ["Fragmented Memories."] = "Recuerdos fragmentados.",
        ["Mysterious City."] = "Ciudad misteriosa.",
        ["Crypt o' Zoology."] = "Cripta de Zoología.",
        ["Death Watch."] = "Guardia de la Muerte.",
        ["Free Your Mind."] = "Libera tu mente.",
        ["I Am Become Death."] = "Me he convertido en la muerte.",
        ["We've made some good progress, but we need to find more clues."] = "Hemos logrado algunos buenos avances, pero necesitamos encontrar más pistas.",
        ["Great job, we've found everything and I've made notes in the site report."] = "Buen trabajo, hemos encontrado todo y tomé notas en el informe del sitio.",
        ["You gain [amount] Archaeology XP for completing a mystery!"] = "¡Obtienes [amount] Archaeology XP por completar un misterio!",
        ["Congratulations! You have completed: '[Mystery]' - Solve this mystery."] = "¡Felicitaciones! Has completado: '[Mystery]' - Resuelve este misterio.",
        ["We've found everything and I've made notes in the site report."] = "Hemos encontrado todo y tomé notas en el informe del sitio.",
        ["Replay which cutscene?"] = "¿Reproducir qué escena?",
        ["Anachronia arrival."] = "Llegada de la Anacronía.",
        ["Which cutscene would you like to view?"] = "¿Qué escena te gustaría ver?",
        ["Opening cutscene."] = "Escena de apertura.",
        ["Closing cutscene."] = "Escena de cierre.",
        ["Cancel."] = "Cancelar.",
    },
    ["Mr Pinsworth"] = {
        ["What're you up to in here?"] = "¿Qué estás haciendo aquí?",
        ["We managed to...acquire access to the banking system. Want a look?"] = "Logramos...adquirir acceso al sistema bancario. ¿Quieres echar un vistazo?",
        ["Select an option"] = "Seleccione una opción",
        ["Yes"] = "si",
        ["No thanks."] = "No, gracias.",
    },
    ["Mrs Gord"] = {
        ["Hi, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
        ["What do you want to say?"] = "¿Qué quieres decir?",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm a widow of one of the Void Knights. My husband died protecting the world from the pest invasion."] = "Soy viuda de uno de los Caballeros del Vacío. Mi esposo murió protegiendo al mundo de la invasión de plagas.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is the Void Knight Outpost. The Void Knights keep us all safe from the pests that are trying to invade. You should talk to one of them if you want to know more."] = "Este es el puesto avanzado Void Knight. Los Void Knights nos mantienen a todos a salvo de las plagas que intentan invadir. Deberías hablar con uno de ellos si quieres saber más.",
        ["I'm fine, thanks."] = "Estoy bien, gracias.",
        ["I heard about the landing party. All those young people...and the Commodore..."] = "Me enteré del grupo de desembarco. Todos esos jóvenes... y el comodoro...",
        ["I guess you're glad you stopped Terry from becoming a knight, huh?"] = "Supongo que te alegra haber impedido que Terry se convirtiera en caballero, ¿eh?",
        ["Yes, but now he knows a pain that won't leave him for the rest of his life. Maybe I should reconsider, let him train...it might help take his mind off things."] = "Sí, pero ahora conoce un dolor que no lo abandonará por el resto de su vida. Tal vez debería reconsiderarlo, dejarlo entrenar… podría ayudarlo a distraerse de las cosas.",
    },
    ["Mrs. Winkin"] = {
        ["Oh, hello there, dear. How can I help you?"] = "Oh, hola, querida. ¿Le puedo ayudar en algo?",
        ["Select an option"] = "Selecciona una opción",
        ["Where are we?"] = "¿Dónde estamos?",
        ["This is Winkin's Farm, dear."] = "Esta es Winkin's Farm, querida.",
        ["Oh, I see. So where is Mr. Winkin?"] = "Ah, ya veo. ¿Dónde está entonces el señor Winkin?",
        ["Oh, he headed off to the market a while back. We look after the farm while he's gone."] = "Oh, se dirigió al mercado hace un tiempo. Cuidaremos la granja mientras él no está.",
        ["Now, was there anything else you wanted?"] = "Ahora, ¿había algo más que quisieras?",
        ["Have you got any flags?"] = "¿Tienes alguna bandera?",
        ["Let me check for you."] = "Déjame comprobarlo por ti.",
        ["Oh, you must be new, dear! It's always good to see a new face. Now, usually we charge for flags, since so many go missing, but you can have your first set for free."] = "¡Oh, debes ser nueva, querida! Siempre es bueno ver una cara nueva. Normalmente cobramos por las banderas, ya que muchas se pierden, pero puedes tener el primer juego gratis.",
        ["Wow, thanks!"] = "¡Vaya, gracias!",
        ["Now, remember: if you plant the flags in any place that doesn't have seeds in it, you'll lose yer flag - and they're not cheap to buy back from me. Here you go, then."] = "Ahora, recuerda: si plantas las banderas en cualquier lugar que no tenga semillas, perderás tu bandera, y no es barato volver a comprármelas. Aquí tienes, entonces.",
        ["Thanks very much! I'll be off, then."] = "¡Muchas gracias! Entonces me voy.",
        ["Bye now."] = "Adiós.",
        ["Ah! First things first. One of the farmers dropped off some flags for you. You can have them back. Here you go."] = "¡Ah! Lo primero es lo primero. Uno de los granjeros te dejó algunas banderas. Puedes recuperarlos. Aquí tienes.",
        ["Alright. You can have a total of 10 flags. To obtain a full set of flags will cost you [price] coins. Would you like to buy these flags?"] = "Muy bien. Puedes tener un total de 10 banderas. Obtener un conjunto completo de banderas le costará [price] coins. ¿Quieres comprar estas banderas?",
        ["Yes, please."] = "Sí, por favor.",
        ["Here you are then, dear."] = "Aquí estás, querida.",
        ["No, thanks."] = "No, gracias.",
        ["Okay, dear. Goodbye."] = "Está bien, querida. Adiós.",
        ["It looks like you have all the flags you need. You don't need to buy any more."] = "Parece que tienes todas las banderas que necesitas. No necesitas comprar más.",
        ["Now, remember: if you plant the flags in any place that doesn't have seeds in it, you'll lose the flag - and they're not cheap to buy back from me. Here you go, then."] = "Ahora, recuerda: si plantas las banderas en cualquier lugar que no tenga semillas, perderás la bandera, y no es barato volver a comprarlas. Aquí tienes, entonces.",
        ["Do you have a spare spade?"] = "¿Tienes una pala de repuesto?",
        ["Why, of course. I can sell you one for 5 gold pieces."] = "Por qué, por supuesto. Puedo venderte uno por 5 piezas de oro.",
        ["Okay, thanks."] = "Está bien, gracias.",
        ["Here you are, then."] = "Aquí tienes, entonces.",
        ["Actually, I've changed my mind."] = "En realidad, he cambiado de opinión.",
        ["Okay then."] = "Está bien, entonces.",
        ["Do you have anything for trade?"] = "¿Tienes algo para intercambiar?",
        ["Of course."] = "Por supuesto.",
        ["Nothing. I'm fine, thanks."] = "Nada. Estoy bien gracias.",
        ["Okay, dear."] = "Está bien, querida.",
    },
    ["Mubariz"] = {
        ["Welcome to the Duel Arena."] = "Bienvenido a Duel Arena.",
        ["Select an option"] = "Seleccione una opción",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["The Duel Arena has four arenas and a boxing ring where you can fight other players in a controlled environment. Duels are available to free players and members. We have our own dedicated hospital where we guarantee to put you back together, even if you lose. In between the arenas are walkways where you can watch the fights and challenge other players."] = "Duel Arena tiene cuatro arenas y un ring de boxeo donde puedes luchar contra otros jugadores en un entorno controlado. Los duelos están disponibles para jugadores y miembros gratuitos. Tenemos nuestro propio hospital dedicado donde garantizamos que lo recuperaremos, incluso si pierde. Entre las arenas hay pasarelas donde puedes ver las peleas y desafiar a otros jugadores.",
        ["How do I challenge someone to a duel?"] = "¿Cómo desafío a alguien a un duelo?",
        ["When you go to the arena, you'll go up an access ramp to the walkways that overlook the duels. From the walkways you can watch the fighting and challenge other players. You'll know you're in the right place as you'll have a 'Challenge' option when you right-click a player. There are two types of duels. There are 'Friendly' duels, in which you can duel against someone without staking anything, and there are 'Staked' duels, in which you can stake up to 50M coins."] = "Cuando vayas a la arena, subirás por una rampa de acceso a las pasarelas que dan a los duelos. Desde las pasarelas podrás observar los combates y desafiar a otros jugadores. Sabrás que estás en el lugar correcto porque tendrás la opción \"Desafío\" cuando hagas clic derecho en un jugador. Hay dos tipos de duelos. Hay duelos \"Amistosos\", en los que puedes batirte en duelo contra alguien sin apostar nada, y hay duelos \"Apostados\", en los que puedes apostar hasta 50M coins.",
        ["What kind of options are there?"] = "¿Qué tipo de opciones hay?",
        ["You and your opponent can offer coins as a stake. If you win, you receive what your opponent staked, but, if you lose, your opponent will get whatever coins you staked. You can choose to use rules to spice things up a bit. For instance, if you both agree to use the 'No Magic' rule, neither player can use Magic to attack. The fight will be restricted to Ranged and melee only. The rules are fairly self-evident, with lots of different combinations for you to try out!"] = "Tú y tu oponente podéis ofrecer coins como apuesta. Si ganas, recibirás lo que tu oponente apostó, pero, si pierdes, tu oponente obtendrá el coins que hayas apostado. Puedes optar por utilizar reglas para darle vida un poco a las cosas. Por ejemplo, si ambos acuerdan usar la regla 'No Magic', ninguno de los jugadores podrá usar Magic para atacar. La pelea estará restringida a Ranged y cuerpo a cuerpo únicamente. ¡Las reglas son bastante evidentes y hay muchas combinaciones diferentes que puedes probar!",
        ["This place looks really old. Where did it come from?"] = "Este lugar parece muy viejo. ¿De dónde vino?",
        ["The archaeologists excavating the area east of Varrock have been working on this site as well. From these cliffs they uncovered this huge building. The experts think it may date back to the Second Age! Now that the archaeologists have moved out, a group of warriors, headed by myself, bought the land and converted it into the Duel Arena. The best fighters from around the world come here to fight!"] = "Los arqueólogos que excavan el área al este de Varrock también han estado trabajando en este sitio. Desde estos acantilados descubrieron este enorme edificio. ¡Los expertos creen que puede remontarse a la Segunda Edad! Ahora que los arqueólogos se han mudado, un grupo de guerreros, encabezados por mí, compraron el terreno y lo convirtieron en la Arena de Duelo. ¡Los mejores luchadores de todo el mundo vienen aquí a pelear!",
        ["I challenge you!"] = "¡Te desafío!",
        ["Ho, ho, ho!"] = "¡Ho, ho, ho!",
        ["Goodbye."] = "Adiós.",
        ["May you duel with honour!"] = "¡Que tengas un duelo con honor!",
        ["Oh, woe is me. My livelihood gone, in an instant. Literally swallowed up whole by the desert."] = "Oh, ¡ay de mí! Mi sustento se fue, en un instante. Literalmente tragado entero por el desierto.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["Once I was the overseer of the Duel Arena. I maintained a place where the greatest warriors in the land did battle."] = "Una vez fui el supervisor de Duel Arena. Mantuve un lugar donde lucharon los guerreros más grandes de la tierra.",
        ["Oh, but it was glorious. The clash of steel against steel. Spell against spell. Fist against face."] = "Oh, pero fue glorioso. El choque del acero contra el acero. Hechizo contra hechizo. Puño contra la cara.",
        ["Such beautiful sounds."] = "Qué sonidos tan hermosos.",
        ["But then... but then...."] = "Pero entonces... pero entonces...",
        ["The ground just fell away and the arena plunged into the desert itself. Everything I had built there. Everything...just...gone."] = "El suelo simplemente cayó y la arena se hundió en el desierto mismo. Todo lo que había construido allí. Todo...simplemente...desapareció.",
        ["So now I stand here. Lamenting the greatest moments of my life and waiting to see what new opportunities arise."] = "Así que ahora estoy aquí. Lamentando los mejores momentos de mi vida y esperando a ver qué nuevas oportunidades surgen.",
        ["Mubariz! I'm glad to see you're okay."] = "¡Mubariz! Me alegra ver que estás bien.",
        ["Okay? OKAY? I am very far from OKAY! My entire livelihood is gone, sunk beneath the sands."] = "¿Está bien? ¿BUENO? ¡Estoy muy lejos de estar BIEN! Todo mi sustento se ha esfumado, hundido bajo la arena.",
        ["What am I to do now?"] = "¿Qué debo hacer ahora?",
        ["Well, at least you have your health?"] = "Bueno, ¿al menos tienes salud?",
        ["What good is my health? How am I going to make money from that?"] = "¿De qué me sirve mi salud? ¿Cómo voy a ganar dinero con eso?",
        ["You have completed: 'Console Mubraiz' and gained progress towards the Oasis Restoration event."] = "Has completado: 'Consola Mubraiz' y has progresado hacia el evento Restauración del Oasis.",
        ["Well... I'll just be going now then. Just wanted to check in and see if you were okay."] = "Bueno... Entonces me iré ahora. Sólo quería comprobar si estabas bien.",
    },
    ["Muckthumb"] = {
        ["Hello, dryfoot."] = "Hola, pie seco.",
        ["Choose..."] = "Elige...",
        ["Tool storage."] = "Almacenamiento de herramientas.",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["What tools can you store?"] = "¿Qué herramientas puedes almacenar?",
        ["Yes, please."] = "Sí, por favor.",
        ["What can you store?"] = "¿Qué puedes almacenar?",
        ["Me can store farming tools, obviously. You want to be using the store?"] = "Puedo guardar herramientas agrícolas, obviamente. ¿Quieres usar la tienda?",
        ["What do you do with the tools you're storing?"] = "¿Qué haces con las herramientas que estás almacenando?",
        ["No thanks, I'll keep hold of my stuff."] = "No, gracias, guardaré mis cosas.",
        ["What do you do with the tools you're storing?<br>They can't possibly all fit in your pockets!"] = "¿Qué haces con las herramientas que guardas?<br>¡No es posible que quepan todas en tus bolsillos!",
        ["Silly question, obviously keep tools in bog."] = "Pregunta tonta, obviamente mantén las herramientas en el pantano.",
        ["Now, you want me to look after yours or not?"] = "Ahora, ¿quieres que cuide el tuyo o no?",
        ["Okay? Another time maybe."] = "¿Está bien? Quizás en otra ocasión.",
        ["Open your tool store, please."] = "Abre tu tienda de herramientas, por favor.",
        ["Actually, I'm fine."] = "En realidad, estoy bien.",
        ["Winkin's Farm."] = "La granja de Winkin.",
        ["Can you take me to Winkin's Farm?"] = "¿Puedes llevarme a la granja de Winkin?",
        ["Composting."] = "Compostaje.",
        ["Other topics."] = "Otros temas.",
        ["Tell me about yourself."] = "Háblame de ti.",
        ["How did you end up farming out here?"] = "¿Cómo terminaste cultivando aquí?",
        ["Mud good. Bog wet. 'Shrooms grow if you talk to them enough."] = "Barro bueno. Mojado como un pantano. 'Los hongos crecen si les hablas lo suficiente.",
        ["Good for licking. Good for baiting rummertums."] = "Bueno para lamer. Bueno para cebar rummertums.",
        ["Rummertums?"] = "¿Rummertums?",
        ["You know... bouncy legs, squishy tail. Oh yes, yes. Little lick for boggo, little lick for rummertum."] = "Ya sabes... piernas saltarinas, cola blanda. Ah, sí, sí. Un pequeño lamido para boggo, un pequeño lamido para rummertum.",
        ["Need to be patient like Old Sogwood if you want to catch them though."] = "Sin embargo, debes ser paciente como Old Sogwood si quieres atraparlos.",
        ["Okay..."] = "Está bien...",
        ["If rummertum comes, good day. If boggo eats mushroom first, also good day."] = "Si llega rummertum, buenos días. Si boggo come hongos primero, también buenos días.",
        ["Anyway. Want me to hold onto somefing?"] = "De todos modos. ¿Quieres que me quede con algo?",
        ["Sorry, no use. Only for boggos or friend of boggos. Talk to Waterface in da snail."] = "Lo siento, no sirve de nada. Sólo para boggos o amigo de boggos. Habla con Waterface en el caracol.",
    },
    ["Mudflippers"] = {
        ["Da hoggies ain't biting today."] = "Los hoggies no muerden hoy.",
        ["Hoggies'?"] = "¿'Hoggies'?",
        ["Oh, sorry, da hog fishies. They sometimes swin down da waterfall from up top."] = "Oh, lo siento, peces cerdo. A veces bajan nadando por la cascada desde arriba.",
        ["Up top' - Berylbrook - is overrun by sanguine werewolves. Maybe they are eating them all?"] = "Arriba', Berylbrook, está invadido por hombres lobo sanguíneos. ¿Quizás se los están comiendo todos?",
        ["Could you tell them to stop? I want my fishies!"] = "¿Podrías decirles que paren? ¡Quiero mis peces!",
    },
    ["Mugger (level_ 6)"] = {
        ["**Mugger (level: 6)** I didn't do it!"] = "**Atracador (nivel: 6)** ¡Yo no lo hice!",
    },
    ["Mugger"] = {
        ["**Mugger (level: 6)** I didn't do it!"] = "**Atracador (nivel: 6)** ¡Yo no lo hice!",
    },
    ["Muggh"] = {
        ["Hey, what you doing here? We not open yet."] = "Oye, ¿qué haces aquí? Aún no abrimos.",
        ["Just having a nosey, really."] = "Sólo estoy entrometiendo, en realidad.",
        ["You bring dat nose back here when we open for business. I fix you up good."] = "Traes esa nariz aquí cuando abramos el negocio. Te arreglo bien.",
        ["Fix me up?"] = "¿Arreglarme?",
        ["Yeah, me give you facial. Try to make your ugly face look bit nicer."] = "Sí, te daré un tratamiento facial. Intenta hacer que tu fea cara se vea un poco mejor.",
        ["Charming."] = "Encantador.",
        ["Hey, what you doing here? You want me give you facial?"] = "Oye, ¿qué haces aquí? ¿Quieres que te haga un facial?",
        ["Select an Option"] = "Selecciona una opción",
        ["Why, sure, since you make it sound so delightful."] = "Claro, ya que lo haces sonar tan delicioso.",
        ["Take dat thing off your head, human, else you no get facial."] = "Quítate eso de la cabeza, humano, de lo contrario no tendrás facial.",
        ["Silly human, you already gots face full of muds."] = "Humano tonto, ya tienes la cara llena de barro.",
        ["Muggh smacks a fistful of mud on your face."] = "Muggh te golpea la cara con un puñado de barro.",
        ["Um, maybe later."] = "Um, tal vez más tarde.",
    },
    ["Mummy (Jaldraocht sarcophagus)"] = {
        ["The mummy"] = "la momia",
        ["The mummy appears to be immune to your attacks."] = "La momia parece ser inmune a tus ataques.",
    },
    ["Mummy"] = {
        ["The mummy"] = "la momia",
        ["The mummy appears to be immune to your attacks."] = "La momia parece ser inmune a tus ataques.",
    },
    ["Muncher"] = {
        ["Good doggo!"] = "¡Buen perro!",
        ["**FEED MUNCHER THESE BONES?**"] = "**¿Alimentar a Muncher con estos huesos?**",
        ["Yes."] = "Sí.",
        ["2 souls fly over to power the vessel."] = "2 almas vuelan para impulsar el barco.",
    },
    ["Munsim"] = {
        ["What treasure will you discover here, buried beneath the sands?"] = "¿Qué tesoro descubrirás aquí, enterrado bajo la arena?",
    },
    ["Murcaily"] = {
        ["Hello there...thanks for helping out Trufitus commune with the gods Bwana. We've been able to return to the village thanks to your help."] = "Hola... gracias por ayudar a Trufitus a comunicarse con los dioses Bwana. Hemos podido regresar al pueblo gracias a vuestra ayuda.",
        ["Select an option{{anchor|init}}"] = "Seleccione una opción{{anchor|init}}",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["Well, I tend the hardwood grove nearby, you can enter if you like and harvest some of the very fine hardwood that grows within. Apart from that I'm a simple Tai Bwo Wannai villager...I like to try and find out what's going on in the mainland and the rest of the known world."] = "Bueno, cuido el bosquecillo de maderas duras cercano, puedes entrar si quieres y cosechar algo de la fina madera dura que crece dentro. Aparte de eso, soy un simple aldeano de Tai Bwo Wannai... Me gusta intentar descubrir qué está pasando en el continente y en el resto del mundo conocido.",
        ["Is there anything interesting to do here?"] = "¿Hay algo interesante que hacer aquí?",
        ["Is there anything interesting to do around here?"] = "¿Hay algo interesante que hacer por aquí?",
        ["*Unknown condition 1 (presumably at high favour):*"] = "*Condición desconocida 1 (presumiblemente con gran favor):*",
        ["Apart from cutting back the jungle and repairing the fence, I think we've got most things covered now Bwana."] = "Aparte de recortar la jungla y reparar la cerca, creo que ahora tenemos la mayoría de las cosas cubiertas, Bwana.",
        ["*Unknown condition 2 (presumably at low favour):*"] = "*Condición desconocida 2 (presumiblemente con poco favor):*",
        ["Well Bwana, if you're stuck for something to do, you could always do a bit of handymanship about the village and cut away the jungle that lies here about. If you's is good with da machete Bwana, you's can get's some thatching spars and put them to use repairing the run-down village fence."] = "Bueno, Bwana, si no tienes nada que hacer, siempre puedes hacer un poco de mantenimiento en la aldea y cortar la jungla que se encuentra por aquí. Si eres bueno con el machete Bwana, puedes conseguir algunos palos de paja y usarlos para reparar la cerca deteriorada de la aldea.",
        ["Select an option{{anchor|options-2}}"] = "Seleccione una opción{{anchor|options-2}}",
        ["*Unknown condition:*"] = "*Condición desconocida:*",
        ["Ask about cutting back the jungle."] = "Pregunte sobre la reducción de la jungla.",
        ["Do I get anything for doing this?"] = "¿Recibiré algo por hacer esto?",
        ["Yes Bwana, you gain experience in woodcutting. In addition many members of the community will reward you with trading sticks, our local currency, for your efforts."] = "Sí, Bwana, adquieres experiencia en la tala de madera. Además, muchos miembros de la comunidad te recompensarán con palos comerciales, nuestra moneda local, por tus esfuerzos.",
        ["Trading sticks?"] = "¿Intercambiar palos?",
        ["Correct Bwana, trading sticks! It's our form of local currency! Everything you do to help out in the village will give you some favour, but there's a maximum limit! When you've reached one hundred percent, you cannot gain any more favour, you need to cash in your favour for trading sticks before you can increase your favour again."] = "¡Correcto Bwana, intercambiando palos! ¡Es nuestra forma de moneda local! Todo lo que hagas para ayudar en el pueblo te dará algún favor, ¡pero hay un límite máximo! Cuando hayas alcanzado el cien por cien, no podrás ganar más favores; tendrás que cobrar tu favor por intercambiar palos antes de poder aumentar tu favor nuevamente.",
        ["Select an option"] = "Seleccione una opción",
        ["Who do I get trading sticks from?"] = "¿De quién obtengo palos de intercambio?",
        ["Well Bwana, there's a good ten villagers I know of who would show their appreciation for your effort. Who do you want to ask about?"] = "Bueno, Bwana, conozco unos diez aldeanos que mostrarían su agradecimiento por tu esfuerzo. ¿Sobre quién quieres preguntar?",
        ["Villagers: Page 1{{anchor|villagers-1}}"] = "Aldeanos: Página 1{{anchor|villagers-1}}",
        ["Sharimika is married to Mamma Bufetta, Bwana. They live in the houses just in front of the tribal statue."] = "Sharimika está casado con Mamma Bufetta, Bwana. Viven en las casas justo enfrente de la estatua tribal.",
        ["Mamma Bufetta lives with her family in the building that faces the stone statue, she lives there with her husband Sharimika and her daughter Layleen."] = "Mamma Bufetta vive con su familia en el edificio que está frente a la estatua de piedra, vive allí con su esposo Sharimika y su hija Layleen.",
        ["Layleen is a young girl, the daughter of Mamma Bufetta and Sharimika, she lives with her parents."] = "Layleen es una niña, hija de Mamma Bufetta y Sharimika, vive con sus padres.",
        ["Karaday is a young man and his chosen profession is fishing, he follows after his father Safta Doc in that respect. You can find him usually around the center of the village, that is when he's not off fishing."] = "Karaday es un hombre joven y su profesión elegida es la pesca, sigue a su padre Safta Doc en ese sentido. Normalmente lo puedes encontrar en el centro del pueblo, es decir, cuando no está pescando.",
        ["Villagers: Page 2"] = "Aldeanos: Página 2",
        ["Villagers: Page 2{{anchor|villagers-2}}"] = "Aldeanos: Página 2{{anchor|villagers-2}}",
        ["Safta Doc used to be a fisherman, but he's just about retired now. He has an interesting profession which you might like to talk to him about. You'll find him usually near the building with the anvil in it. It's just slightly north of the village statue."] = "Safta Doc solía ser pescador, pero ahora está casi jubilado. Tiene una profesión interesante de la que quizás te gustaría hablar con él. Generalmente lo encontrarás cerca del edificio con el yunque. Está un poco al norte de la estatua del pueblo.",
        ["Gabooty is a bit of a mystery, no one's sure where he came from! He's quite helpful though, you can find him in the middle of the village enclosure, to the south of Sharimika's house."] = "Gabooty es un poco misterioso, ¡nadie está seguro de dónde vino! Sin embargo, es bastante útil, puedes encontrarlo en el medio del recinto del pueblo, al sur de la casa de Sharimika.",
        ["Fanellaman was a fisherman, he's retired now, but he'll try and regale you with tales of his salty sea dog days. He's often walking up and down the western beach."] = "Fanellaman era pescador, ahora está jubilado, pero intentará deleitarte con historias de sus días de lobo de mar salado. A menudo camina arriba y abajo por la playa occidental.",
        ["Jagbakoba is a wild hunter. He can be a bit aggressive but he'll reward anyone who helps to keep the village in good order. You'll find him to the south of the enclosure, near the fires."] = "Jagbakoba es un cazador salvaje. Puede ser un poco agresivo, pero recompensará a cualquiera que ayude a mantener el pueblo en buen orden. Lo encontrarás al sur del recinto, cerca de los incendios.",
        ["Villagers: Page 3"] = "Aldeanos: Página 3",
        ["Ah Rionasta! He's an enterprising man! Had a very good idea and is now much in demand, you'll find him between the blacksmith's and Timfraku's hut."] = "¡Ah, Rionasta! ¡Es un hombre emprendedor! Tuve una muy buena idea y ahora tiene mucha demanda, lo encontrarás entre la cabaña del herrero y Timfraku.",
        ["Murcaily! That's me! Well, what do you want to know?! I look after the teak and mahogany trees and make sure that we get payment of anyone who uses the facility. And I'm usually standing just about here!"] = "¡Murcaily! ¡Ese soy yo! Bueno, ¿qué quieres saber? Cuido los árboles de teca y caoba y me aseguro de que recibamos el pago de cualquiera que utilice las instalaciones. ¡Y normalmente estoy parado justo aquí!",
        ["Back to original questions."] = "Volver a las preguntas originales.",
        ["Ask another question."] = "Haz otra pregunta.",
        ["Villagers: Page 1."] = "Aldeanos: Página 1.",
        ["Where can I get a machete from?"] = "¿Dónde puedo conseguir un machete?",
        ["Where is this jungle?"] = "¿Dónde está esta jungla?",
        ["Where is the fence that needs to be repaired?"] = "¿Dónde está la cerca que necesita ser reparada?",
        ["Ok, thanks."] = "Vale, gracias.",
        ["Where can I get a machete from?{{anchor|machete}}"] = "¿De dónde puedo conseguir un machete?{{anchor|machete}}",
        ["You can purchase a standard machete from Jiminua's store. Gabooty has a selection of local items which you may like to purchase, including better machetes. Also, you may like to chat to Safta Doc, he may have a deal you'll find interesting."] = "Puedes comprar un machete estándar en la tienda de Jiminua. Gabooty tiene una selección de artículos locales que quizás le interese comprar, incluidos mejores machetes. Además, es posible que desees chatear con Safta Doc, es posible que tenga una oferta que te resulte interesante.",
        ["Where is this jungle?{{anchor|jungle}}"] = "¿Dónde está esta jungla?{{anchor|jungle}}",
        ["You'll find much of it to the southern end of Tai Bwo Wannai, outside of the village. Some is tougher than others so you may have difficulties cutting it back. Beware though Bwana, those bushes can conceal a great many dangers or trophies, it could be the death... or the making of you!"] = "Encontrarás gran parte en el extremo sur de Tai Bwo Wannai, en las afueras del pueblo. Algunos son más duros que otros, por lo que es posible que tengas dificultades para reducirlos. Pero ten cuidado, Bwana, esos arbustos pueden esconder muchos peligros o trofeos, podría ser tu muerte... ¡o tu destrucción!",
        ["What do you mean by that?"] = "¿Qué quieres decir con eso?",
        ["It means that you may find something you wish you hadn't but then discover something you never thought you could! If you find me too vague, go and have a chat with Sharimika about it!"] = "¡Significa que puedes encontrar algo que desearías no haber encontrado pero luego descubres algo que nunca pensaste que podrías! Si me encuentras demasiado vago, ¡ve y charla con Sharimika al respecto!",
        ["Where is the fence that needs to be repaired?{{anchor|fence}}"] = "¿Dónde está la cerca que necesita ser reparada?{{anchor|fence}}",
        ["This is to the South{{Sic}} Bwana, you should see that there are sections which are rotten, but some other passers-by sometimes help out repairing it. You'll need some thatching spars and a machete in order to repair the fence though Bwana."] = "Esto es hacia el sur{{Sic}} Bwana, deberías ver que hay secciones que están podridas, pero algunos otros transeúntes a veces ayudan a repararlo. Necesitarás algunos palos de paja y un machete para reparar la cerca a través de Bwana.",
        ["*If the player has some favour:*"] = "*Si el player tiene algún favor:*",
        ["I've been doing some work around the village."] = "He estado trabajando en el pueblo.",
        ["I've already given you some trading sticks and I don't have any more on me at the moment. Why not go and talk to some of the other villagers and get some contributions?"] = "Ya te he dado algunos palitos de intercambio y no tengo ninguno más en este momento. ¿Por qué no vas y hablas con algunos de los otros aldeanos y consigues algunas contribuciones?",
        ["Hey there, you wanna go in there to chop da special wood, it's gonna cost you's 100 trading sticks my friend."] = "Hola, si quieres entrar a cortar una madera especial, te costará 100 palos de intercambio, amigo mío.",
        ["Ok, I'll pay 100 trading sticks to enter."] = "Ok, pagaré 100 trading sticks para participar.",
        ["You pay 100 trading sticks and gain access to the hardwood grove."] = "Pagas 100 palos comerciales y obtienes acceso al bosquecillo de madera dura.",
        ["Nah thanks, I'll give it a miss at the moment I think."] = "No, gracias. Creo que lo dejaré pasar por el momento.",
        ["Fair enough, pop back if you change your mind."] = "Muy bien, vuelve si cambias de opinión.",
        ["Great, I saw you were fixing the fence earlier, it looks like you've got the hang of this now! Let me give you something for your effort!"] = "Genial, vi que estabas arreglando la cerca antes, ¡parece que ya dominas esto! ¡Déjame darte algo por tu esfuerzo!",
        ["You get <number> trading sticks.<br />Your remaining favour totals <number>%."] = "Obtienes palos comerciales <number>.<br />Tu favor restante asciende a <number>%.",
        ["*If the player has enough favour for trading sticks and has not traded favour for trading sticks in a while with Murcaily:*"] = "*Si el player tiene suficiente favor para intercambiar palos y no ha intercambiado favor para intercambiar palos por un tiempo con Murcaily:*",
        ["Hey, I've seen you working around the village. You've been doing a lot of good work around here for us. Let me give you something for your trouble."] = "Oye, te he visto trabajando en el pueblo. Has estado haciendo un muy buen trabajo aquí para nosotros. Déjame darte algo por tu molestia.",
    },
    ["Murknose, Emissary of Bandos"] = {
        ["I Murknose, big strong goblin! I am here to tell you about Big High War God - Bandos."] = "¡Yo, Murknose, duende grande y fuerte! Estoy aquí para contarles sobre Big High War God - Bandos.",
        ["If you strong like me, you can join Bandos, and I give you work."] = "Si te gusto, puedes unirte a Bandos y te daré trabajo.",
        ["*Who are you?*"] = "*¿Quién eres?*",
        ["Who are you?"] = "¿Quién eres?",
        ["I Murknose, big strong goblin! But - even I not as strong as Big High War God."] = "¡Yo Nariz Murk, duende grande y fuerte! Pero ni siquiera yo soy tan fuerte como Big High War God.",
        ["So I tell you about Big High War God - Bandos. I am his emi... mish... I tell you all about him!"] = "Así que les hablo de Big High War God - Bandos. Soy su emi...mish... ¡Te cuento todo sobre él!",
        ["*Can you tell me about Bandos?*"] = "*¿Puedes contarme sobre Bandos?*",
        ["Can you tell me about Bandos?"] = "¿Puedes hablarme de Bandos?",
        ["What do you want to know about Big High War God?"] = "¿Qué quieres saber sobre Big High War God?",
        ["*Who is Bandos?*"] = "*¿Quién es Bandos?*",
        ["Who is Bandos?"] = "¿Quién es Bandos?",
        ["Bandos is Big High War God. Bandos command us to fight, and we fight! Bandos big, and Bandos strong. Very strong. Bandos is strongest god."] = "Bandos es el Dios Grande War. ¡Bandos nos ordena luchar y luchamos! Bandos grande y Bandos fuerte. Acérrimo. Bandos es el dios más fuerte.",
        ["*Why should I follow Bandos?*"] = "*¿Por qué debería seguir a Bandos?*",
        ["Why should I follow Bandos?"] = "¿Por qué debería seguir a Bandos?",
        ["Because Bandos is strongest! Bandos commands and weak take orders. Bandos strong, if you strong, you follow him. If you follow Big High War God, he maybe make you strong like he make goblins strong."] = "¡Porque Bandos es más fuerte! Comandos Bandos y órdenes débiles. Bandos fuerte, si eres fuerte, lo sigues. Si sigues a Big High War Dios, él tal vez te haga fuerte como hace a los duendes.",
        ["*What does Bandos want?*"] = "*¿Qué quiere Bandos?*",
        ["What does Bandos want?"] = "¿Qué quiere Bandos?",
        ["Bandos want war! Bandos want to fight! The strongest must rule, and Bandos strongest!"] = "¡Bandos quiere la guerra! ¡Bandos quiere pelear! ¡El más fuerte debe gobernar, y Bandos el más fuerte!",
        ["*I want to declare my support for Bandos!*"] = "*¡Quiero declarar mi apoyo a Bandos!*",
        ["....The emissary gives you the Book of the Gods."] = "....(Acción: El emisario te entrega el Libro de los Dioses.)",
        ["I Murknose, big strong goblin. But - even I not as strong as Big High War God."] = "Yo Murknose, un duende grande y fuerte. Pero ni siquiera yo soy tan fuerte como Big High War God.",
        ["So I tell you about Big High War God. I am his emi... mish... I tell you all about him."] = "Así que les hablo de Big High War God. Soy su emi... mish... Les cuento todo sobre él.",
        ["*Can you tell me about the Big High War God?*"] = "*¿Puedes hablarme sobre el Gran Dios War?*",
        ["Can you tell me about the Big High War God?"] = "¿Puedes hablarme del Gran Dios War?",
        ["*Who is Big High War God?*"] = "*¿Quién es el Dios Grande y Alto War?*",
        ["Who is Big High War God?"] = "¿Quién es Big High War Dios?",
        ["But Bandos fought Armadyl - bird god - and Armadyl recruited many, many people to do fighting for him."] = "Pero Bandos luchó contra Armadyl, el dios pájaro, y Armadyl reclutó a muchas, muchas personas para luchar por él.",
        ["Army of Bandos fought well! Fought hard. Lost."] = "¡El ejército de Bandos luchó bien! Luchó duro. Perdido.",
        ["So Bandos dead now. But he still right! Strongest always win. Armadyl's army was stronger. Proof what Bandos think right, even though he die of it."] = "Así que Bandos ya está muerto. ¡Pero todavía tiene razón! Los más fuertes siempre ganan. El ejército de Armadyl era más fuerte. Prueba de lo que Bandos piensa bien, aunque muera por ello.",
        ["So join us and be strong! Be strongest and fiercest and best at fighting! Be top of the pile."] = "¡Únete a nosotros y sé fuerte! ¡Sé el más fuerte, el más feroz y el mejor luchando! Sé el primero en la lista.",
        ["Everyone else get crushed."] = "Todos los demás quedan aplastados.",
        ["*Why should I follow Big High War God?*"] = "*¿Por qué debería seguir a Big High War God?*",
        ["Why should I follow Big High War God?"] = "¿Por qué debería seguir a Big High War Dios?",
        ["Because strongest will always rule the world! Strongest commands and weaker take orders. If you strong, you follow path of Big High War God."] = "¡Porque los más fuertes siempre gobernarán el mundo! Los comandos más fuertes y los más débiles reciben órdenes. Si eres fuerte, sigues el camino del Gran Dios War.",
        ["Following Bandos make goblins strong. Following way of strength and bigness work for you too."] = "Seguir Bandos fortalece a los duendes. Seguir el camino de la fuerza y ​​la grandeza también funcionará para usted.",
        ["*What does the path of the Big High War God say?*"] = "*¿Qué dice el camino del Gran Dios Alto War?*",
        ["What does the path of the Big High War God say?"] = "¿Qué dice el camino del Dios Grande War?",
        ["Big High War God want war! Big High War God want to fight! The strongest must rule, and you can be strong too!"] = "Gran altura War ¡Dios quiera guerra! Big High War ¡Dios quiere pelear! ¡El más fuerte debe gobernar y tú también puedes ser fuerte!",
        ["That what Bandos wanted. That what strongest want now. That maybe what you want too."] = "Eso era lo que quería Bandos. Eso es lo que más quieren ahora. Eso tal vez sea lo que tú también quieras.",
        ["*I want to declare my support for the Big High War God!*"] = "*¡Quiero declarar mi apoyo al Gran Dios War!*",
        ["You clever! Big High War God strongest god. You take banner, show you support strongest god. I give you Book of the Gods. You like reading, right? Weird. Anyway, you read stories about gods in that book. Ha, but book not complete. You complete some jobs, I give you more pages."] = "¡Eres inteligente! Big High War Dios dios más fuerte. Tomas una pancarta y muestras que apoyas al dios más fuerte. Os doy el Libro de los Dioses. Te gusta leer, ¿verdad? Extraño. De todos modos, lees historias sobre dioses en ese libro. Ja, pero el libro no está completo. Completas algunos trabajos, te doy más páginas.",
        ["Category:God Emissaries"] = "Categoría:God Emissaries",
    },
    ["Murky Matt (runes)"] = {
        ["Hello."] = "Hola.",
        ["**Murky Matt (runes):{{anchor|arr}}** Arrrr, me-lad, I would speak with ye, but may I ask ye to speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance. Brugsen will give ye a great and plunderous lesson on the Grand Exchange and the Tutor a much shorter and simpler explanation."] = "**Murky Matt (runas):{{anchor|arr}}** Arrrr, muchacho, hablaría contigo, pero ¿puedo pedirte que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada? Brugsen os dará una gran y saqueadora lección sobre el Grand Exchange y el Tutor una explicación mucho más breve y sencilla.",
        ["Arrrr, me-lad, I must ask ye to get yerself some learnin' about the Grand Exchange first. Brugsen will give ye a great and plunderous lesson, or the Tutor can offer ye a much shorter and simpler explanation."] = "Arrrr, muchacho, debo pedirte que primero aprendas un poco sobre Grand Exchange. Brugsen os dará una gran y saqueadora lección, o el Tutor puede ofreceros una explicación mucho más breve y sencilla.",
        ["A pirate!"] = "¡Un pirata!",
        ["Arrrr, How'd ye be guessing that, [me-lad/me-lady]?"] = "Arrrr, ¿cómo adivinarías eso, [me-lad/me-lady]?",
        ["You're kidding, right?"] = "Estás bromeando, ¿verdad?",
        ["Nay! Now, what is it ye be wantin? I can tell ye all about the prices of runes, or perhaps I could combine the charges on yer teleport jewellery."] = "¡No! Ahora bien, ¿qué es lo que queréis? Puedo contarte todo sobre los precios de las runas, o tal vez podría combinar los cargos de tus joyas de teletransporte.",
        ["Choose an option:"] = "Elige una opción:",
        ["What's a pirate doing here?"] = "¿Qué hace un pirata aquí?",
        ["By my sea-blistered skin, I could ask the same of you!"] = "¡Por mi piel llena de ampollas marinas, podría pedirte lo mismo!",
        ["But... I'm not a pirate?"] = "Pero... ¿No soy un pirata?",
        ["No? Then what's that smell? The smell o' someone spent too long at sea without a bath!"] = "¿No? ¿Entonces qué es ese olor? ¡El olor de alguien que pasó demasiado tiempo en el mar sin bañarse!",
        ["I think that's probably you."] = "Creo que probablemente seas tú.",
        ["Har har har!"] = "¡Jar, ja, ja!",
        ["We've got a stern landlubber 'ere! Well, let me tell ye, I'm here for the Grand Exchange! Gonna cash in me loot!"] = "¡Tenemos un marinero de tierra severo aquí! Bueno, déjame decirte que estoy aquí para el Grand Exchange. ¡Voy a cobrar mi botín!",
        ["Don't you just want to sell it in a shop or trade it to someone specific?"] = "¿No quieres simplemente venderlo en una tienda o canjeárselo a alguien específico?",
        ["By my wave-battered bones! Not when I can sell to the whole world from this very spot!"] = "¡Por mis huesos golpeados por las olas! ¡No cuando puedo vender a todo el mundo desde este mismo lugar!",
        ["You pirates are nothing but trouble! Why, once I travelled to Lunar Isle with a bunch of your type, and spent days sailing around in circles!"] = "¡Ustedes, los piratas, no son más que problemas! ¡Vaya, una vez viajé a Lunar Isle con un grupo de tu tipo y pasé días navegando en círculos!",
        ["Then ye must know me brother! Murky Pat!"] = "¡Entonces debes conocerme hermano! ¡Murky Pat!",
        ["Hmmm. Not so sure I remember him."] = "Mmmm. No estoy tan seguro de recordarlo.",
        ["Well, 'e be on that ship for sure. And I remember 'im tellin' me about some guy like ye, getting all mixed up with curses and cabin boys."] = "Bueno, seguro que estará en ese barco. Y recuerdo que me habló de un tipo como tú, mezclado con maldiciones y grumetes.",
        ["Yes! That was me!"] = "¡Sí! ¡Ese era yo!",
        ["Ye sure be a different character."] = "Seguro que serás un personaje diferente.",
        ["Tell me about the prices of runes."] = "Cuéntame sobre los precios de las runas.",
        ["Combine the charges on my teleport jewellery, please."] = "Combina los cargos de mis joyas de teletransporte, por favor.",
        ["Arrr, there be nothing in yer inventory that I can combine."] = "Arrr, no hay nada en tu inventario que pueda combinar.",
        ["Arrr! Yer pockets are as empty as a ghost ship at an exorcism!"] = "¡Arrr! ¡Tus bolsillos están tan vacíos como un barco fantasma en un exorcismo!",
        ["Arrr, all done."] = "Arrr, todo listo.",
        ["Thanks!"] = "¡Gracias!",
        ["I got to go, erm, swab some decks! Yarr!"] = "¡Tengo que irme, ejem, a limpiar algunas cubiertas! ¡Yarr!",
        ["Defer your speech right there! Quit this derogatory and somewhat narrow-minded allusion that all folks of sea voyage are only concerned with washing the decks, looking after parrots and drinking rum. I'll have ye know there is  much more to a pirate than meets the eye."] = "¡Aplaza tu discurso allí mismo! Dejemos de lado esta alusión despectiva y un tanto estrecha de miras de que todos los que viajan por mar sólo se preocupan de lavar las cubiertas, cuidar de los loros y beber ron. Te haré saber que un pirata es mucho más de lo que parece.",
        ["Aye-aye, captain!"] = "¡Sí, sí, capitán!",
        ["Oh, come on! Lighten up!"] = "¡Oh, vamos! ¡Relájate!",
    },
    ["Murky Matt"] = {
        ["Hello."] = "Hola.",
        ["**Murky Matt (runes):{{anchor|arr}}** Arrrr, me-lad, I would speak with ye, but may I ask ye to speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance. Brugsen will give ye a great and plunderous lesson on the Grand Exchange and the Tutor a much shorter and simpler explanation."] = "**Murky Matt (runas):{{anchor|arr}}** Arrrr, muchacho, hablaría contigo, pero ¿puedo pedirte que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada? Brugsen os dará una gran y saqueadora lección sobre el Grand Exchange y el Tutor una explicación mucho más breve y sencilla.",
